"""PIT RESCUE live check (PIT_ACCESS_BUILD_LADDERS_CLIMBING_JUMPS A4: "a colonist downed in a sheer pit nobody can reach gets
a ladder job queued at the nearest wall (portable if spare/shallow, else fixed), it is built and the colonist rescued";
BENCH belt 2026-10-22).

  python.exe src/RimMandrake/FlowWorks/northstar/pit_rescue_live.py [out.json] [--origin X,Z] [--fresh-map] [--ticks N]
      [--scene rescue|escape] [--raised-ticks N]

Scene (plot from --origin, default 30,30; 16 x 12 cleared + read back): a sheer pit x = 6..8, z = 4..6 dug D 4 (2 m: nobody
without gear climbs it, climb_proof); a colonist DOWNED on its floor (7, 5) (pawn_force_incapacitate, no bleeding); every
other colonist on the map vanished, then two fresh rescuers on the rim (2, 5), (2, 6), undrafted; MEDICAL wooden beds at
(12, 9) and (14, 9) (a rescue needs a bed: one for the control, one for the victim); 100 steel + 100 wood at (3, 9) for the ladder.
PIT_RESCUE_FIX_LADDER_UP_NOBODY_COMES (HARNESS, bridge run 1 2026-10-23): with plain beds a rescuer who got tired slept in the
victim's bed and so OWNED it (vanilla claims a non-medical bed on lying down); RestUtility.FindBedFor then had no bed for the
victim and WorkGiver_RescueDowned never offered the rescue (2/2 runs FAIL, both with a rescuer LayDown at (14, 9)). Medical
beds are never claimed for sleep and are the ones a patient is carried to; each is set with jawa/set_bed_owner_type
medical=true and READ BACK (not medical: every row UNMEASURED SITE). The final bed census rides in the result ("beds"), and a
colonist not out while fewer than two beds were left for a patient (owned, or a rescuer lying in it) is SITE, not MOD;
with no census to read, it is UNMEASURED HARNESS.
Rows:
  RESCUE_LADDER_QUEUED   EXPECT within 500 ticks (RM_MapComponent_PitRescueLadder checks every 250) a ladder blueprint,
                         frame or ladder stands on a pit square.
  RESCUE_LADDER_BUILT    EXPECT within --ticks a built RM_LadderPortable / RM_Ladder in the pit.
  RESCUE_COLONIST_OUT    EXPECT within --ticks the downed colonist is off the pit floor (carried out; in the bed or on
                         the way). LIES: a colonist who died is not rescued (dead is read); the plain stepper is used
                         (the governed clock stops on a downed colonist by design).

--scene escape (PIT_ESCAPE_PROVE_LADDER_LEFT_DOWN; LADDER_PARITY_BUILD_NO_KEYS_REQUIRED A6, owner Q4 2026-10-23: "A prison
ladder left down is equivalent to a prison door left open... same game rules apply."): the same plot and sheer pit, an RM_Ladder
on its west wall (6, 5), a hostile Villager on the floor (8, 5) made the colony's prisoner (pawn_set_guest_status, read back).
Phase 1 RAISED (RM_PromotionProofs.ProofLadder raise, read back) for --raised-ticks; phase 2 LOWERED for up to --ticks or
until he is off the pit floor. Each phase reads RM_LadderParity.ProofLadderParity "may:" (mayClimb, letsOut) and counts the
new "escap" lines in rimworld/list_messages (vanilla JobGiver_PrisonerEscape sends MessagePrisonerIsEscaping as it starts the
escape: a Goto with exitMapOnArrival); in the LOWERED phase a sampled Goto counts as the escape started too (a live message can expire between
samples). Verdict: escape_verdict (pure; selftest_pit_escape_live.py).
  LADDER_RAISED_PRISONER_STAYS     EXPECT no escape message and the prisoner on the pit floor at every sample.
  LADDER_LOWERED_PRISONER_ESCAPES  EXPECT an escape message and the prisoner off the pit floor (or gone off the map).
  LIES: a ladder not read back in the wanted state, a pawn not a prisoner, a dead prisoner -> UNMEASURED SITE; a prisoner
  already out when the lowered phase starts -> UNMEASURED SITE; asleep (LayDown) through a quiet lowered phase -> UNMEASURED
  SITE (vanilla does not escape in his sleep), never MOD.
"""
import argparse
import json
import os
import re
import sys
import time

HERE = os.path.dirname(os.path.abspath(__file__))
if HERE not in sys.path:
    sys.path.insert(0, HERE)
NSP = "RimMandrake.FlowWorks.RM_NorthstarProofs"
PROMO = "RimMandrake.FlowWorks.RM_PromotionProofs"
LADP = "RimMandrake.FlowWorks.RM_LadderParity"
ITEM = "PIT_ACCESS_BUILD_LADDERS_CLIMBING_JUMPS"
LADDERS = ("RM_LadderPortable", "RM_Ladder")


def free_patient_beds(census, taken=()):
    """Beds a downed colonist can still be carried to: one with an unowned sleeping slot (a medical bed has no owners; a
    plain one a sleeper lay down in is his) whose cell is not in <taken> (a rescuer lying in it: an injured one may rest in a
    medical bed). Census rows are jawa/set_bed_owner_type's (owners, sleepingSlots, pos); a row that does not say is not
    counted. The control's bed is not marked in the census and still counts, hence the caller's < 2."""
    n = 0
    for b in (census or {}).get("beds") or []:
        pos = b.get("pos") or {}
        if (b.get("owners") is not None and b.get("sleepingSlots") is not None and b["owners"] < b["sleepingSlots"]
                and (pos.get("x"), pos.get("z")) not in set(taken)):
            n += 1
    return n


def lying_cells(last):
    """Cells where a rescuer of the last trail entry is lying down (job LayDown*)."""
    cells = []
    for _id, at, job in (last or {}).get("rescuers") or []:
        if str(job or "").startswith("LayDown") and at:
            cells.append((at.get("x"), at.get("z")))
    return cells


ESCAPE_ITEM = "PIT_ESCAPE_PROVE_LADDER_LEFT_DOWN"
ESCAPE_IDS = ("LADDER_RAISED_PRISONER_STAYS", "LADDER_LOWERED_PRISONER_ESCAPES")


def kv(txt):
    """'a=1 b=x' -> {'a': '1', 'b': 'x'} (the ProofLadder / ProofLadderParity reply shape)."""
    out = {}
    for tok in str(txt or "").split():
        if "=" in tok:
            k, v = tok.split("=", 1)
            out[k] = v
    return out


def escape_lines(reply):
    """Every string anywhere in a rimworld/list_messages reply that speaks of an escape (lowercase 'escap')."""
    found = []

    def walk(x):
        if isinstance(x, str):
            if "escap" in x.lower():
                found.append(x)
        elif isinstance(x, dict):
            for v in x.values():
                walk(v)
        elif isinstance(x, (list, tuple)):
            for v in x:
                walk(v)
    walk((reply or {}).get("messages") if isinstance(reply, dict) else reply)
    return found


def new_lines(before, after):
    """Lines in <after> beyond their count in <before> (a ring of messages: the same text may repeat)."""
    left = list(before or [])
    out = []
    for line in after or []:
        if line in left:
            left.remove(line)
        else:
            out.append(line)
    return out


def escape_verdict(raised, lowered):
    """Pure verdict of the escape scene. Each phase: {"ladder": ProofLadder kv, "prisoner": bool read back, "startInPit": bool,
    "trail": [{"t", "inPit", "gone", "dead", "job"}], "escapeMsgs": int, "escapeJob": bool (a Goto sampled), "may":
    ProofLadderParity may: kv}. A phase the driver
    never reached is None. Returns [(row id, status, class, detail)] for ESCAPE_IDS, in order."""
    rows = []
    for rid, ph, want_raised in ((ESCAPE_IDS[0], raised, True), (ESCAPE_IDS[1], lowered, False)):
        if not ph:
            rows.append((rid, "UNMEASURED", "HARNESS", {"why": "phase not run"}))
            continue
        det = {k: ph.get(k) for k in ("ladder", "may", "escapeMsgs", "escapeJob", "startInPit")}
        trail = ph.get("trail") or []
        det["samples"] = len(trail)
        det["last"] = trail[-1] if trail else None
        lad = ph.get("ladder") or {}
        why = None
        if lad.get("present") != "True" or lad.get("raised") != str(want_raised):
            why = "ladder not read back %s" % ("raised" if want_raised else "lowered")
        elif not ph.get("prisoner"):
            why = "the pawn is not the colony's prisoner (read back)"
        elif not trail:
            why = "no samples"
        elif any(s.get("dead") for s in trail):
            why = "the prisoner died"
        elif not ph.get("startInPit"):
            why = "the prisoner was not on the pit floor when the phase began"
        if why:
            det["why"] = why
            rows.append((rid, "UNMEASURED", "SITE", det))
            continue
        # escape started: MessagePrisonerIsEscaping; when LOWERED also the Goto it gives (rimworld/list_messages may read the
        # live, expiring messages, so a message can fall between samples). Not when RAISED: vanilla gives other plain Gotos
        # too (JobGiver_MoveToStandable, FleePotentialExplosion, SeekAllowedArea), so a Goto alone never fails that row.
        msgs = int(ph.get("escapeMsgs") or 0) + (1 if ph.get("escapeJob") and not want_raised else 0)
        out = any((not s.get("inPit")) or s.get("gone") for s in trail)
        if want_raised:
            rows.append((rid, "PASS" if msgs == 0 and not out else "FAIL", "MOD", det))
            continue
        if msgs > 0 and out:
            rows.append((rid, "PASS", "MOD", det))
            continue
        tail = [str(s.get("job") or "") for s in trail[-3:]]
        if msgs == 0 and not out and len(tail) == 3 and all(j.startswith("LayDown") for j in tail):
            det["why"] = "asleep through the lowered phase (no escape is started in sleep)"
            rows.append((rid, "UNMEASURED", "SITE", det))
            continue
        rows.append((rid, "FAIL", "MOD", det))
    return rows


def run_escape(a, B, V, res, row, all_rows, step, P):
    """The escape scene (module docstring, --scene escape); the plot is already reset and prepared."""
    pit = {P(x, z) for x in range(6, 9) for z in range(4, 7)}
    for c in sorted(pit):
        B.call("jawa/flowworks_excavation_drive", x=c[0], z=c[1], deepenLevels=4, setFill=-1)
    foot, start = P(6, 5), P(8, 5)
    lad = B.call("jawa/spawn_batch", ops="RM_Ladder:%d,%d" % foot) or {}
    step(60)
    sp = B.call("jawa/spawn_pawn", kindDef="Villager", x=start[0], z=start[1], faction="hostile", count=1) or {}
    pid = ((sp.get("pawns") or [{}])[0]).get("id")
    gs = (B.call("jawa/pawn_set_guest_status", pawn=pid, guestStatus="Prisoner", hostFaction="PlayerColony") or {}) if pid else {}
    res["scene"] = {"ladder": {k: lad.get(k) for k in ("success", "thingsPlaced")}, "prisoner": pid, "guest": str(gs)[:200]}

    def sc(typ, method, arg):
        r = B.call("jawa/static_call", type=typ, method=method, args=arg) or {}
        return str(r.get("result") if r.get("result") is not None else "")

    def state():
        ps = {p.get("id"): p for p in (B.call("jawa/list_pawns", limit=400, includeCorpses=True) or {}).get("pawns") or []}
        p = ps.get(pid)
        if p is None:  # list_pawns lists spawned pawns and corpses: absent = off the map (an escape ends at the edge)
            return {"gone": True, "inPit": False, "dead": False}
        pos = (p.get("x"), p.get("z"))
        return {"pos": pos, "inPit": pos in pit, "gone": p.get("spawned") is False, "dead": bool(p.get("dead"))}
    # list_pawns carries no prisoner flag; the guest tool reads GuestStatus and HostFaction back after the engine call
    is_prisoner = gs.get("guestStatusAfter") == "Prisoner" and bool(gs.get("hostFactionAfter"))
    # ProofLadderParity takes the thingIDNumber (int.TryParse); spawn_pawn gives the ThingID ("Human123")
    m = re.search(r"(\d+)$", str(pid or ""))
    num = int(m.group(1)) if m else None

    def phase(op, ticks, stop_out):
        ladder = kv(sc(PROMO, "ProofLadder", "%d,%d,%s" % (foot[0], foot[1], op)))
        step(2)
        s0 = state()
        ph = {"ladder": ladder, "prisoner": is_prisoner, "startInPit": bool(s0.get("inPit") and not s0.get("gone")),
              "may": kv(sc(LADP, "ProofLadderParity", "may:%d,%d,%d" % (num, foot[0], foot[1]))) if num else {}}
        before = escape_lines(B.call("rimworld/list_messages", limit=200))
        trail, t, msgs = [], 0, []
        while t < ticks:
            step(250)
            t += 250
            s = state()
            pr = B.call("jawa/attack_target_probe", pawn=pid, maxDist=60, _answer=True) or {}
            s.update({"t": t, "job": pr.get("curJob")})
            trail.append(s)
            msgs = new_lines(before, escape_lines(B.call("rimworld/list_messages", limit=200)))
            if s.get("dead") or (stop_out and (msgs or s["job"] == "Goto") and (s["gone"] or not s["inPit"])):
                break
        ph.update({"trail": trail, "escapeMsgs": len(msgs), "escapeText": msgs[:3],
                   "escapeJob": any(s_.get("job") == "Goto" for s_ in trail)})
        return ph
    if not pid or not (lad.get("success") and lad.get("thingsPlaced")):
        for rid in ESCAPE_IDS:
            row(rid, "UNMEASURED", "SITE", {"why": "scene not staged", "scene": res["scene"]})
        if pid:
            B.call("jawa/pawn_force_incapacitate", pawn=pid, action="vanish", _answer=True)
        return 2
    raised = phase("raise", a.raised_ticks, False)
    lowered = phase("lower", a.ticks, True) if raised["trail"] and not raised["trail"][-1].get("dead") else None
    res["phases"] = {"raised": raised, "lowered": lowered}
    for rid, st, cls, det in escape_verdict(raised, lowered):
        row(rid, st, cls, det)
    if pid:
        B.call("jawa/pawn_force_incapacitate", pawn=pid, action="vanish", _answer=True)
    res["finished"] = time.strftime("%Y-%m-%dT%H:%M:%S")
    return 0 if all(r["status"] == "PASS" for r in res["rows"]) else 1


def main(argv=None, bridge=None, validation=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("out", nargs="?", default=None)
    ap.add_argument("--origin", default="30,30")
    ap.add_argument("--fresh-map", action="store_true")
    ap.add_argument("--ticks", type=int, default=8000)
    ap.add_argument("--scene", choices=("rescue", "escape"), default="rescue")
    ap.add_argument("--raised-ticks", type=int, default=2500)
    a = ap.parse_args(argv)
    if bridge is None or validation is None:
        import proof_hose as PH  # noqa: E402
    V = validation or PH.V
    B = bridge or PH.PB()
    out = a.out or os.path.join(HERE, "pit_rescue_result_%s.json" % time.strftime("%Y%m%dT%H%M%S"))
    if os.path.dirname(out):
        os.makedirs(os.path.dirname(out), exist_ok=True)
    rows = []
    res = {"script": "pit_rescue_live.py", "started": time.strftime("%Y-%m-%dT%H:%M:%S"), "rows": rows, "args": vars(a)}
    IDS = ESCAPE_IDS if a.scene == "escape" else ("RESCUE_LADDER_QUEUED", "RESCUE_LADDER_BUILT", "RESCUE_COLONIST_OUT")
    item = ESCAPE_ITEM if a.scene == "escape" else ITEM

    def save():
        with open(out + ".tmp", "w", encoding="utf-8") as f:
            json.dump(res, f, indent=1, default=str)
        os.replace(out + ".tmp", out)

    def row(rid, st, cls, det):
        rows.append({"id": rid, "status": st, "class": cls, "item": item, "detail": det})
        print("%-24s %-10s %-6s %s" % (rid, st, cls, json.dumps(det, default=str)[:400]), flush=True)
        save()

    def all_rows(st, cls, det):
        for rid in IDS:
            if rid not in [r["id"] for r in rows]:
                row(rid, st, cls, det)

    def step(n):
        return B.call("rimworld/step_game_ticks", ticks=n, pauseFirst=True, timeoutMs=max(60000, n * 40)) or {}

    ox, oz = (int(v) for v in a.origin.split(","))
    P = lambda dx, dz: (ox + dx, oz + dz)  # noqa: E731
    if a.fresh_map:
        B.call("rimworld/go_to_main_menu")
        B.call("rimworld/start_debug_game_ready", readiness="mapData", pauseIfNeeded=True, timeoutMs=280000)
    ok, _ = V._wait_playing(B, leave_s=0)
    if not ok:
        all_rows("UNMEASURED", "HARNESS", {"why": "no game in Playing"})
        return 2
    res["site_calm"] = V.site_calm(B)
    B.call("jawa/kill_hostiles")
    rect = (ox, oz, 16, 12)
    B.call("jawa/static_call", type=NSP, method="ProofResetRect", args="%d;%d;%d;%d" % rect)
    site_rows = []
    V.prepare_site(B, rect, site_rows, "rescue_site")
    if [r for r in site_rows if r.get("status") not in (None, "PASS")]:
        all_rows("UNMEASURED", "SITE", {"why": "site not prepared", "site": site_rows[:2]})
        return 2
    if a.scene == "escape":
        rc = run_escape(a, B, V, res, row, all_rows, step, P)
        save()
        return rc
    pit = {P(x, z) for x in range(6, 9) for z in range(4, 7)}
    for c in sorted(pit):
        B.call("jawa/flowworks_excavation_drive", x=c[0], z=c[1], deepenLevels=4, setFill=-1)
    for p in (B.call("jawa/list_pawns", limit=400) or {}).get("pawns") or []:
        if not p.get("dead") and p.get("isPlayer"):
            B.call("jawa/pawn_force_incapacitate", pawn=p.get("id"), action="vanish")
    beds = []

    def medical_bed(c):
        B.call("jawa/build_batch", ops="Bed:%d,%d" % c, faction="player", wipeExisting=False, stuff="WoodLog")
        th = (B.call("jawa/list_things", defName="Bed", rect="%d,%d,1,1" % c, limit=1) or {}).get("things") or [{}]
        bid = th[0].get("id")
        r = (B.call("jawa/set_bed_owner_type", thing=bid, medical="true") or {}) if bid else {}
        beds.append({"cell": c, "id": bid, "medicalAfter": r.get("medicalAfter")})
    medical_bed(P(12, 9))
    for d, c in (("Steel", P(3, 9)), ("WoodLog", P(4, 9))):
        B.call("rimworld/spawn_thing", defName=d, stackCount=100, x=c[0], z=c[1])

    def spawn(c):
        r = B.call("jawa/spawn_pawn", kindDef="Colonist", x=c[0], z=c[1], faction="player", count=1) or {}
        return ((r.get("pawns") or [{}])[0]).get("id")
    victim = spawn(P(7, 5))
    rescuers = [spawn(P(2, 5)), spawn(P(2, 6))]
    # SITE (belt live 2026-10-22): bridge-spawned colonists can come with work types at priority 0 (the quarry check's job
    # probe read Mining priority 0, workActive False) -- the first rescue runs' "nobody finishes the frame" may be exactly
    # that. Construction, Hauling and Doctor (rescue) are set on.
    res["work"] = {}
    for r_ in rescuers:
        for wt in ("Construction", "Hauling", "Doctor"):
            w = B.call("jawa/set_work_priority", pawnId=r_, workType=wt, priority=1) or {}
            res["work"]["%s/%s" % (r_, wt)] = str(w)[:160]
    inc = B.call("jawa/pawn_force_incapacitate", pawn=victim, action="downed", allowBleedingWounds=False) or {}
    # can-fail control (belt run 3: nobody rescued even after the ladder stood): a colonist downed on OPEN ground; if he is
    # not rescued either, the scene cannot rescue at all (SITE), whatever the pit does
    control = spawn(P(13, 3))
    B.call("jawa/pawn_force_incapacitate", pawn=control, action="downed", allowBleedingWounds=False)
    res["control"] = control
    medical_bed(P(14, 9))
    res["scene"] = {"victim": victim, "rescuers": rescuers, "incap": str(inc)[:200], "beds": beds}
    if any(b.get("medicalAfter") is not True for b in beds):
        all_rows("UNMEASURED", "SITE", {"why": "a rescue bed is not medical (read back)", "beds": beds})
        for pid in [victim, control] + rescuers:
            if pid:
                B.call("jawa/pawn_force_incapacitate", pawn=pid, action="vanish", _answer=True)
        return 2

    def ladder_in_pit():
        hits = []
        lt = B.call("jawa/list_things", rect="%d,%d,3,3" % P(6, 4), limit=60) or {}
        for t in lt.get("things") or []:
            d = str(t.get("def") or t.get("defName") or "")
            if any(l in d for l in LADDERS) or "Blueprint" in d or "Frame" in d:
                hits.append((d, t.get("x"), t.get("z")))
        return hits

    def victim_state(who=None):
        ps = {p.get("id"): p for p in (B.call("jawa/list_pawns", limit=400, includeCorpses=True) or {}).get("pawns") or []}
        p = ps.get(who or victim) or {}
        return (p.get("x"), p.get("z")), p.get("downed"), p.get("dead"), p.get("spawned")
    control_moved = None

    t, queued_at, built_at, out_at = 0, None, None, None
    trail = []
    while t < a.ticks:
        step(250)
        t += 250
        lad = ladder_in_pit()
        pos, downed, dead, spawned = victim_state()
        cpos = victim_state(control)
        if control_moved is None and (cpos[0] != P(13, 3) or cpos[3] is False):
            control_moved = t
        jobs = []
        for r_ in rescuers:
            pr = B.call("jawa/attack_target_probe", pawn=r_, maxDist=60, _answer=True) or {}
            jobs.append([r_, pr.get("position"), pr.get("curJob")])
        trail.append({"t": t, "ladder": lad, "victim": [pos, downed, dead, spawned], "rescuers": jobs})
        if lad and queued_at is None:
            queued_at = t
        if built_at is None and any(d in LADDERS for d, _x, _z in lad):
            built_at = t
        if out_at is None and (pos not in pit and pos[0] is not None or spawned is False) and not dead:
            out_at = t
        if dead:
            break
        if out_at is not None:
            break
        # belt live 2026-10-22: idle rescuers hauled the wood into the frame and then never took FinishFrame (8000 ticks,
        # 'Work left' untouched) while an ORDERED FinishFrame completed it. After 2000 stalled ticks the frame is finished
        # by order (recorded as an assist) so the rescue half can still be measured; RESCUE_LADDER_BUILT stays FAIL.
        frames = [x for x in lad if x[0].startswith("Frame_")]
        if frames and built_at is None and t >= 2000 and not res.get("assist"):
            fid = (B.call("jawa/list_things", defName=frames[0][0], rect="%d,%d,1,1" % (frames[0][1], frames[0][2]), limit=1)
                   or {}).get("things") or [{}]
            o = B.call("jawa/ordered_job", pawnId=rescuers[0], jobDef="FinishFrame", targetAId=fid[0].get("id")) or {}
            res["assist"] = {"t": t, "frame": fid[0].get("id"), "order": {k: o.get(k) for k in ("accepted", "afterJobDef")}}
        if t % 1000 == 0:
            save()
    res["trail"] = trail
    det = {"queuedAt": queued_at, "builtAt": built_at, "outAt": out_at, "last": trail[-1] if trail else None}
    row("RESCUE_LADDER_QUEUED", "PASS" if queued_at is not None and queued_at <= 500 else "FAIL", "MOD", det)
    det["assist"] = res.get("assist")
    row("RESCUE_LADDER_BUILT", "PASS" if built_at is not None and not res.get("assist") else "FAIL", "MOD", det)
    dead = trail and trail[-1]["victim"][2]
    det["controlRescuedAt"] = control_moved
    res["beds"] = B.call("jawa/set_bed_owner_type") or {}
    det["freePatientBeds"] = free_patient_beds(res["beds"], lying_cells(trail[-1] if trail else None))
    no_census = out_at is None and not (res["beds"].get("beds") or [])
    no_rescue_here = control_moved is None
    # a FAIL with no bed left for the victim (the control holds one) is the scene's, not the mod's
    no_bed = out_at is None and not no_census and det["freePatientBeds"] < 2
    site = dead or (no_rescue_here and out_at is None) or no_bed
    row("RESCUE_COLONIST_OUT", "UNMEASURED" if site or no_census else ("PASS" if out_at is not None else "FAIL"),
        "HARNESS" if no_census and not site else ("SITE" if site else "MOD"), det)
    for pid in [victim, control] + rescuers:
        if pid:
            B.call("jawa/pawn_force_incapacitate", pawn=pid, action="vanish", _answer=True)
    res["finished"] = time.strftime("%Y-%m-%dT%H:%M:%S")
    save()
    return 0 if all(r["status"] == "PASS" for r in rows) else 1


if __name__ == "__main__":
    sys.exit(main())

scripts.src/RimMandrake/Graffiti/graffiti_v1_liv:
"""Live proofs of GRAFFITI_V1_LIVE_PROOF_1, one clause per call:

    python.exe src/RimMandrake/Graffiti/graffiti_v1_live_proof.py A1|A2|A3|A4|A5|A6|A7|A8

Calls RimMandrake.Graffiti.RM_GraffitiProof through jawa/static_call on the current (quicktest) map; every set-up rebuilds
the same 20x12 walled site at the map centre (see the C# class), so the clauses run in any order.
Exit 0 = the clause holds, 1 = it answered and something is wrong, 2 = UNMEASURED (no bridge, REFUSED, no line).
  A1 spree     SpreeStart forces RM_GraffitiPaintingSpreeState on a colonist, the clock runs up to 3000 ticks, SpreeRead:
               marks >= 1 and every one has factionOk and ideoOk (maker/faction/ideo stamped)
  A2 raid      RaidStart closes and roofs the site's south half into a room, spawns 3 enemy pawns outside the wall and 1
               inside the room under LordJob_AssaultColony (marksIn 0), 120 ticks run, RaidExit moves the lord onto its own
               leaving toil: mid 0 (none on the way in), after >= 1, every tag raidExitEligible, on a wall and exterior
               (outside the room by geometry, unroofed, in the outdoors room); interiorClosed False, inside 0 or outsideOpen False is a SITE
               fault (UNMEASURED). "In its faction's mark": the driver then saves the game (RM_GraffitiA2Proof.rws, deleted after)
               and reads every mark placed since RaidStart's tick: factionOk (makerFaction = the RAID line's faction) must cover
               every exit tag; an unreadable save is UNMEASURED
  A3 sigil     Sigil paints RM_Graffiti_IdeoSigil by a colonist: ideo True, frame halo_0, iconIsIdeo True, tinted True
  A4 over      GoingOver: a colonist's Tag_A, then an enemy's ThrowUp_A on the same cell: firstGone True, marksAtCell 1,
               def RM_Graffiti_ThrowUp_A, rivalFaction True
  A5 thought   HostileThought: an enemy's tag 3 cells from a colonist: makerHostile True, worker True, mood True
  A6 scrub     CleanSetup (own Vandal, enemy Devotional sigil, enemy Vandal control), 700 ticks, CleanRead: unforced own False,
               unforced devotional False, unforced control True, forced own/devotional True, ordered True; then up to
               4000 ticks until CleanDone reads ownGone True and devotionalGone True
  A7 choose    DesignateSetup designates 3 cells with 3 named marks and orders the colonist onto them; up to 6000 ticks until
               DesignateRead reads painted 3, matched 3, pending 0
  A8 load      Player.log of this load (Graffiti reachable, all DLC) names no Graffiti config / cross-reference / XML error
verdict(), field() and log_verdict() are pure and are exercised offline by selftest_graffiti_v1_live.py.
"""
import json
import os
import re
import sys
import time
import xml.etree.ElementTree as ET

PROBE = "RimMandrake.Graffiti.RM_GraffitiProof"
CLAUSES = ("A1", "A2", "A3", "A4", "A5", "A6", "A7", "A8")
STEP = 250
HEADS = ("SPREE", "READ", "RAID", "EXIT", "SIGIL", "OVER", "THOUGHT", "CLEANSET", "CLEAN", "DONE", "DESIGNATED", "LOADED")
WANT = {
    "A3": {"ideo": "True", "frame": "halo_0", "iconIsIdeo": "True", "tinted": "True"},
    "A4": {"placed": "True", "firstGone": "True", "marksAtCell": "1", "def": "RM_Graffiti_ThrowUp_A", "rivalFaction": "True"},
    "A5": {"makerHostile": "True", "worker": "True", "mood": "True"},
    "A6": {"unforcedOwn": "False", "unforcedDevotional": "False", "unforcedControl": "True",
           "forcedOwn": "True", "forcedDevotional": "True", "ordered": "True"},
    "A6done": {"ownGone": "True", "devotionalGone": "True"},
    "A7": {"painted": "3", "matched": "3", "pending": "0"},
}
# a Graffiti-owned load error: an error-kind line that names anything Graffiti (namespace, def prefix, package, or one of
# its XML file names such as ThingDefs_Graffiti.xml) on itself or on its own continuation lines (indented, or a stack frame
# "at ..."), never on the next record. Deliberately wide: an error in a Graffiti family mod (SacredGraffiti, GraffitiImperial)
# loaded beside it fails A8 too.
OURS = re.compile(r"Graffiti|graffiti")
# continuation = indented, a .NET frame "at ...", Unity's "(Filename: ...)", or an unindented Unity frame
# "Namespace.Type:Method (args)" (UnityEngine StackTrace formatter)
CONTINUATION = re.compile(r"^(?:\s|at |\(Filename|\(wrapper |\[Ref |[\w.`<>+\[\],]+:[\w<>.`|$]+ ?\()")
# wide on purpose (a keyword list kept missing wordings: "XML format error", "is not a Def type"): any error, exception,
# failure, could-not, not-found, invalid or duplicate wording counts
ERROR_KIND = re.compile(r"error|exception|fail|could not|couldn't|cannot|not found|could not be found|not a Def type|invalid|"
                        r"duplicate|missing", re.I)


def _text(text):
    """A reply as plain probe text: a JSON-serialised bridge reply is decoded to its `result` string, so neither its
    escaping nor its closing quote reaches a field, and a faction name holding a quote or backslash stays whole."""
    s = str(text)
    if s.lstrip().startswith("{"):
        try:
            d = json.loads(s)
        except ValueError:
            return s
        if isinstance(d, dict) and isinstance(d.get("result"), str):
            return d["result"]
    return s


def field(text, key):
    """The token after `key ` in a probe line (' |' ends it), or None."""
    m = re.search(r"(?:^|\| |\b(?:%s) )%s ([^|\n]*)" % ("|".join(HEADS), re.escape(key)), _text(text))
    return m.group(1).strip() if m else None


def line(text, head):
    """The probe's own line starting with `head` out of a reply text, or None."""
    m = re.search(r"\b%s [^\n]*" % re.escape(head), _text(text))
    return m.group(0) if m else None


def _int(text, key):
    v = field(text, key)
    try:
        return int(v)
    except (TypeError, ValueError):
        return None


def _match(text, want):
    return ["%s %s (want %s)" % (k, field(text, k), v) for k, v in want.items() if field(text, k) != v]


SAVE_NAME = "RM_GraffitiA2Proof"


def exit_faction_marks(save_text, faction_name, since_tick):
    """-> (factionOk, sinceMarks, None) or (None, None, why) from a .rws text: of the Filth_Marks placed at or after
    since_tick, how many carry makerFaction = the faction named faction_name (Scribe ref 'Faction_<loadID>'; a loadID of 0
    is the Scribe default and is omitted from the save, so a missing loadID reads 0)."""
    try:
        root = ET.fromstring(save_text)
    except ET.ParseError as ex:
        return None, None, "save does not parse: %s" % ex
    facs = root.find(".//factionManager/allFactions")
    if facs is None:
        return None, None, "save has no factionManager/allFactions"
    ids = ["Faction_" + ((li.findtext("loadID") or "").strip() or "0") for li in facs.findall("li")
           if (li.findtext("name") or "").strip() == faction_name]
    if len(ids) != 1:
        return None, None, "faction %r is named by %d factions in the save" % (faction_name, len(ids))
    since = ok = 0
    for el in root.iter():
        tick = el.findtext("rmMarkPlacedTick")
        if tick is None:
            continue
        try:
            tick = int(tick)
        except ValueError:
            return None, None, "unreadable rmMarkPlacedTick %r" % tick
        if tick < since_tick:
            continue
        since += 1
        if (el.findtext("rmMarkMakerFaction") or "").strip() == ids[0]:
            ok += 1
    return ok, since, None


def verdict(clause, text, extra=None):
    """-> (exit code, reason) for one clause's decisive reply text (A2: the EXIT line with `extra` = the RAID line;
    A6: the CLEAN line with `extra` = the DONE line)."""
    s = str(text)
    if "REFUSED" in s:
        return 2, "probe refused: " + s[s.find("REFUSED"):][:300]
    head = {"A1": "READ", "A2": "EXIT", "A3": "SIGIL", "A4": "OVER", "A5": "THOUGHT", "A6": "CLEAN", "A7": "READ"}[clause]
    ln = line(s, head)
    if not ln:
        return 2, "no %s line: %s" % (head, s[:300])
    if clause == "A1":
        n, f, i = _int(ln, "marks"), _int(ln, "factionOk"), _int(ln, "ideoOk")
        if n is None or f is None or i is None:
            return 2, "unreadable spree read: " + ln
        if n < 1:
            return 1, "the spree left no mark: " + ln
        return (0, ln) if f == n and i == n else (1, "marks without maker faction/ideo: " + ln)
    if clause == "A2":
        raid = line(str(extra), "RAID")
        if not raid or _int(raid, "marksIn") is None:
            return 2, "no RAID line: " + str(extra)[:300]
        fails = []
        if _int(raid, "marksIn") != 0:
            fails.append("marks of the raid faction before it arrived: %s" % field(raid, "marksIn"))
        if _int(ln, "mid") != 0:
            fails.append("tagged on the way in (mid %s)" % field(ln, "mid"))
        after = _int(ln, "after")
        if not after:
            fails.append("no tag when the raid turned to leave (after %s)" % field(ln, "after"))
        elif _int(ln, "eligible") != after or _int(ln, "onWall") != after:
            fails.append("a tag not raidExitEligible or not on a wall")
        elif _int(ln, "exterior") != after:
            fails.append("a tag on an interior wall (exterior %s of %s)" % (field(ln, "exterior"), after))
        if after and _int(ln, "factionOk") is None:
            return 2, "the exit tags' maker faction was not read (no factionOk): " + ln
        if after and _int(ln, "factionOk") < after:
            fails.append("a tag not in the raid faction's mark (factionOk %s of %s)" % (field(ln, "factionOk"), after))
        if _int(ln, "standing") == 0:
            return 2, "SITE: no raider was standing when the exit fired: " + ln
        if field(ln, "interiorClosed") != "True" or not _int(ln, "inside"):
            return 2, "SITE: the roofed interior was not closed or held no raider, so exterior is not tested: " + ln
        if field(ln, "outsideOpen") != "True":
            return 2, "SITE: the raiders' side of the wall is not open outdoors (enclosed terrain), so no exterior face exists: " + ln
        return (1, "; ".join(fails) + " | " + ln) if fails else (0, ln)
    if clause == "A6":
        fails = _match(ln, WANT["A6"])
        if fails:
            return 1, "; ".join(fails) + " | " + ln
        done = line(str(extra), "DONE")
        if not done:
            return 2, "no DONE line: " + str(extra)[:300]
        fails = _match(done, WANT["A6done"])
        return (1, "forced clean left a mark: " + "; ".join(fails) + " | " + done) if fails else (0, ln + " || " + done)
    fails = _match(ln, WANT[clause])
    return (1, "; ".join(fails) + " | " + ln) if fails else (0, ln)


def log_verdict(log_text, loaded_reply):
    """-> (exit code, reason). loaded_reply is the Loaded() answer proving Graffiti is in this game."""
    r = str(loaded_reply)
    ln = line(r, "LOADED")
    if not ln:
        return 2, "RimMandrake.Graffiti not reachable in this game (a clean log would prove nothing): " + r[:200]
    if field(ln, "graffiti") != "True":
        return 2, "the probe answered but does not report Graffiti loaded: " + ln
    if field(ln, "ideology") != "True":
        return 2, "Ideology is not active: every DLC is assumed, restage with all five: " + ln
    if not log_text or "RimWorld" not in log_text:
        return 2, "Player.log empty or unreadable"
    # a record counts when its head is error-worded and any line names Graffiti, or when any of its lines is a Graffiti
    # stack frame (a frame of ours is only printed under an error or exception, whatever its heading looked like)
    # and, whatever the grouping, an error-worded line with Graffiti on it or on any of the next WINDOW lines (RimWorld's
    # own continuations - "Full node:", "Context:", "[Ref ...]" - keep coming in new shapes; a false FAIL here costs a
    # look at the named line, a false PASS certifies a broken load)
    hits = [rec[0].strip()[:200] for rec in _records(log_text)
            if (ERROR_KIND.search(rec[0]) and any(OURS.search(x) for x in rec)) or any(OUR_FRAME.search(x) for x in rec)]
    lines = log_text.splitlines()
    hits += [l.strip()[:200] for i, l in enumerate(lines)
             if ERROR_KIND.search(l) and any(OURS.search(x) for x in lines[i:i + 1 + WINDOW]) and l.strip()[:200] not in hits]
    if hits:
        return 1, "Player.log names %d Graffiti load error line(s): %s" % (len(hits), " || ".join(hits[:5]))
    if field(ln, "thought") != "True" or field(ln, "raidHook") != "True":
        return 1, "the load lacks the hostile-maker thought or the raid-exit hook: " + ln
    return 0, "Player.log clean of Graffiti load errors | " + ln


WINDOW = 3
OUR_FRAME = re.compile(r"(?:^\s*at |^)RimMandrake\.Graffiti\.[\w.`<>+]+[:.][\w<>`]+ ?\(")


def _records(log_text):
    """Player.log split into records: a line plus the continuation lines (indented / stack frames) that follow it."""
    recs = []
    for l in log_text.splitlines():
        if recs and CONTINUATION.match(l):
            recs[-1].append(l)
        else:
            recs.append([l])
    return recs


def _reply(out):
    """The probe's own string out of a jawa/static_call reply: the dict's `result` when it is one (so a non-ASCII faction
    name is never JSON-escaped into a backslash that ends a field), else the whole reply as unescaped JSON text."""
    if isinstance(out, str):
        return out
    if isinstance(out, dict) and isinstance(out.get("result"), str):
        return out["result"]
    return json.dumps(out, ensure_ascii=False)


def _exit_factions(rb, R, faction_name, since):
    """' | factionOk N | sinceMarks M' read from a fresh save of this game, or ' | factionUnread <why>' (verdict A2 then
    says UNMEASURED)."""
    if not faction_name or not isinstance(since, int):
        return " | factionUnread no RAID faction or RaidStart tick"
    dirs = [os.path.join(os.path.dirname(p), "Saves") for p in R._player_log_candidates() if p]
    t0 = time.time() - 2
    r = rb.call("rimworld/save_game", {"saveName": SAVE_NAME})
    paths = ([r["path"]] if isinstance(r, dict) and isinstance(r.get("path"), str) else []) + \
        [os.path.join(d, SAVE_NAME + ".rws") for d in dirs]
    for _ in range(20):  # the write is not instant
        fresh = [p for p in paths if os.path.isfile(p) and os.path.getmtime(p) >= t0 and os.path.getsize(p) > 1000]
        if fresh:
            time.sleep(1.0)
            with open(fresh[0], encoding="utf-8", errors="replace") as fh:
                text = fh.read()
            try:
                os.remove(fresh[0])
            except OSError:
                pass
            ok, n, why = exit_faction_marks(text, faction_name, since)
            if ok is None:
                return " | factionUnread " + why.replace("|", "/")
            return " | factionOk %d | sinceMarks %d" % (ok, n)
        time.sleep(0.5)
    return " | factionUnread no fresh %s.rws in %s" % (SAVE_NAME, "; ".join(paths).replace("|", "/"))


def _read_log(R):
    for p in R._player_log_candidates():
        if p and os.path.isfile(p):
            with open(p, encoding="utf-8", errors="replace") as fh:
                return fh.read()
    return ""


def _until(rb, call, method, done, limit):
    """Step the clock in STEP-tick slices up to `limit`, reading `method` after each; -> (last reply, ticks stepped)."""
    read, stepped = call(method), 0
    while not done(read) and stepped < limit:
        rb.call("rimworld/step_game_ticks", {"ticks": STEP})
        stepped += STEP
        read = call(method)
    return read, stepped


def run(clause, rb, R):
    last = {}

    def call(m, a="x"):  # static_call reads "" as ZERO params; every probe method takes one string
        last["out"] = rb.call("jawa/static_call", {"type": PROBE, "method": m, "args": a})
        return _reply(last["out"])

    if clause == "A1":
        s = call("SpreeStart")
        sp = line(s, "SPREE")
        if not sp or "REFUSED" in s:
            return verdict("A1", s) if "REFUSED" in s else (2, "no SPREE line: " + s[:300])
        if field(sp, "started") != "True":
            return 1, "the spree did not start: " + sp
        read, ticks = _until(rb, call, "SpreeRead", lambda r: (_int(line(r, "READ") or "", "marks") or 0) >= 1, 3000)
        code, why = verdict("A1", read)
        return code, "%s (after %d ticks)" % (why, ticks)
    if clause == "A2":
        raid = call("RaidStart")
        if "REFUSED" in raid:
            return verdict("A2", raid)
        since = last["out"].get("ticksGame") if isinstance(last["out"], dict) else None
        rb.call("rimworld/step_game_ticks", {"ticks": 120})
        ex = call("RaidExit")
        ln = line(ex, "EXIT")
        if ln and "REFUSED" not in ex:
            ex = ln + _exit_factions(rb, R, field(line(raid, "RAID") or "", "faction"), since)
        return verdict("A2", ex, extra=raid)
    if clause in ("A3", "A4", "A5"):
        return verdict(clause, call({"A3": "Sigil", "A4": "GoingOver", "A5": "HostileThought"}[clause]))
    if clause == "A6":
        s = call("CleanSetup")
        if "REFUSED" in s:
            return verdict("A6", s)
        rb.call("rimworld/step_game_ticks", {"ticks": 700})
        clean = call("CleanRead")
        cl = line(clean, "CLEAN")
        if not cl or _match(cl, WANT["A6"]):
            return verdict("A6", clean, extra="")
        done, ticks = _until(rb, call, "CleanDone",
                             lambda r: field(r, "ownGone") == "True" and field(r, "devotionalGone") == "True", 4000)
        code, why = verdict("A6", clean, extra=done)
        return code, "%s (after %d ticks)" % (why, ticks)
    if clause == "A7":
        s = call("DesignateSetup")
        d = line(s, "DESIGNATED")
        if not d:
            return verdict("A7", s)
        if _int(d, "ordered") != 3:
            return 1, "3 designated cells did not each become a colonist's job: " + d
        read, ticks = _until(rb, call, "DesignateRead", lambda r: _int(line(r, "READ") or "", "pending") == 0, 6000)
        code, why = verdict("A7", read)
        return code, "%s (after %d ticks; %s)" % (why, ticks, d[:160])
    return log_verdict(_read_log(R), call("Loaded"))


def main(argv):
    if len(argv) != 2 or argv[1] not in CLAUSES:
        print(__doc__)
        return 2
    clause = argv[1]
    sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "Utils"))
    try:
        import rimbridge_client as R
        host, port, token = R.resolve_endpoint()
        if not token:
            print("UNMEASURED: no bridge token")
            return 2
        with R.RimBridge(host, port, token, timeout=180) as rb:
            code, why = run(clause, rb, R)
    except Exception as ex:  # any transport failure means the proof could not see
        print("UNMEASURED: bridge call failed: %s" % str(ex)[:300])
        return 2
    print("%s %s: %s" % (clause, {0: "PASS", 1: "FAIL", 2: "UNMEASURED"}[code], why))
    return code


if __name__ == "__main__":
    sys.exit(main(sys.argv))

scripts.src/RimMandrake/Utils/live_def_check.py:
#!/usr/bin/env python3
"""live_def_check.py -- does the RUNNING game's def carry what a criterion says it must? One read-only jawa/get_defs call.

    python3 src/RimMandrake/Utils/live_def_check.py --has ThingDef/RM_Chittik=CompProperties_WoundLink [--has ...]

Each --has is DefType/defName=TOKEN: the def must resolve in the live game, and TOKEN must appear as a whole value in the
def's reported fields (a comp class, a field value). `--has DefType/defName` with no `=` asks only that it resolves.

Exit 0 every claim holds, 1 a claim is false (the game answered and said no: a real FAIL), 2 UNMEASURED (no bridge, an
answer that is not what get_defs returns, a def the reply never mentions). Callers hold the bridge lock; this never takes it.

A def that does not resolve is a FAIL only when the mod that defines it is in the RUNNING load. Its owners are the repo's
mods whose XML carries <defName>NAME</defName>; the running load is jawa/running_mods (ModsConfig.xml names the NEXT
load, so a mod enabled after launch is absent here). Owner not running, or the running list unreadable: UNMEASURED. A def
no repo mod defines (a typo, a vanilla or donor def) stays a FAIL: the game answered and nothing explains the no.
A mod folded into the composed biomes mod loads under the composed packageId, so an owner or a --needs naming the member
is also met by the composed id (biomes_compose.folded_ids); without that, a composed def that fails to resolve could only
ever read UNMEASURED.

--needs PACKAGEID / --without PACKAGEID state a criterion's load condition ("with Quarry loaded", "on a tier carrying
Warcasket", "with Alpha Biomes absent"): unmet, or the running list unread, is UNMEASURED before any def is judged. A donor
def no repo mod defines is a FAIL when it does not resolve, so a criterion about a donor's def needs its --needs.
RimBridge binds Windows loopback, so the call runs under Windows Python (python.exe), as rimbridge_client.py says.
"""
import argparse
import json
import os
import subprocess
import sys
import xml.etree.ElementTree as ET

HERE = os.path.dirname(os.path.abspath(__file__))
CLIENT = os.path.join(HERE, "rimbridge_client.py")
SRC = os.path.normpath(os.path.join(HERE, "..", ".."))      # the repo's src/: every mod we ship lives under it
PASS, FAIL, UNMEASURED = 0, 1, 2


def parse_claims(items):
    """-> [(defkey, token or None)]; ValueError on a claim that is not DefType/defName[=TOKEN]."""
    out = []
    for raw in items:
        key, _, token = raw.partition("=")
        key, token = key.strip(), token.strip()
        if "=" in raw and not token:
            raise ValueError("an empty TOKEN would weaken the claim to existence-only; drop the '=': %r" % raw)
        if key.count("/") != 1 or not all(key.split("/")):
            raise ValueError("not DefType/defName[=TOKEN]: %r" % raw)
        out.append((key, token or None))
    return out


def values(node):
    """Every scalar in a JSON tree, as strings: the token is matched against these whole, never as a substring."""
    if isinstance(node, dict):
        for v in node.values():
            yield from values(v)
    elif isinstance(node, list):
        for v in node:
            yield from values(v)
    elif node is not None:
        yield str(node)


def _no_duplicate_keys(pairs):
    """json keeps the LAST of a repeated key, so found:false,found:true would read as true: that is no answer."""
    keys = [k for k, _ in pairs]
    if len(set(keys)) != len(keys):
        raise ValueError("a JSON object repeats a key")
    return dict(pairs)


def _canon(d):
    """A record as the claim reads it: JSON text, so True and 1 stay different (python's == merges them)."""
    return json.dumps([d.get("found"), d.get("fields")], sort_keys=True, default=str)


def judge(claims, reply, owners=None, running=None):
    """-> (exit code, lines). `reply` is get_defs' JSON object. `owners` {defkey: set of lower-case packageIds defining
    it}; `running` the lower-case packageIds of the RUNNING load, or None when unread. With no `owners` an unresolved
    def is a FAIL, as before."""
    if not isinstance(reply, dict) or not isinstance(reply.get("defs"), list):
        return UNMEASURED, ["UNMEASURED: the reply is not a get_defs answer"]
    by_key, bad = {}, set()
    for d in reply["defs"]:
        if not isinstance(d, dict) or not isinstance(d.get("requested"), str) or not d["requested"]:
            return UNMEASURED, ["UNMEASURED: a def record without a string `requested`: %r" % (d,)]
        if d["requested"] in by_key and _canon(by_key[d["requested"]]) != _canon(d):
            bad.add(d["requested"])          # two records that disagree: neither is the answer
        by_key[d["requested"]] = d
    seen, lines = set(), []
    for key, token in claims:
        d = by_key.get(key)
        if d is None:
            seen.add(UNMEASURED)
            lines.append("UNMEASURED %s: the reply does not mention it" % key)
            continue
        if key in bad or not isinstance(d.get("found"), bool) or (
                token is not None and d.get("found") and not isinstance(d.get("fields"), (dict, list))):
            seen.add(UNMEASURED)
            lines.append("UNMEASURED %s: the record is malformed or contradicts another (found=%r)" % (key, d.get("found")))
            continue
        if not d.get("found"):
            if owners and key in owners and owners[key] is None:
                seen.add(UNMEASURED)
                lines.append("UNMEASURED %s: does not resolve, and the search for the mod that defines it failed" % key)
                continue
            mods = sorted((owners or {}).get(key) or ())
            if mods and running is None:
                seen.add(UNMEASURED)
                lines.append("UNMEASURED %s: does not resolve, and the running mod list is unread, so whether %s is "
                             "loaded is unknown" % (key, "/".join(mods)))
            elif mods and not set(mods) & set(running):
                seen.add(UNMEASURED)
                lines.append("UNMEASURED %s: does not resolve because %s is not in the RUNNING load (ModsConfig names "
                             "the next load)" % (key, "/".join(mods)))
            else:
                seen.add(FAIL)
                lines.append("FAIL %s: does not resolve in the live game%s" % (
                    key, " though %s is loaded" % "/".join(sorted(set(mods) & set(running))) if mods else ""))
            continue
        where = "%s from %s" % (key, d.get("packageId") or "?")
        if token is None:
            lines.append("PASS %s resolves" % where)
        elif token in set(values(d.get("fields"))):
            lines.append("PASS %s carries %s" % (where, token))
        else:
            seen.add(FAIL)
            lines.append("FAIL %s lacks %s" % (where, token))
    return (FAIL if FAIL in seen else UNMEASURED if UNMEASURED in seen else PASS), lines   # a real FAIL stands


def aliases(src=SRC):
    """-> {folded member packageId (lower): composed packageId}; None when the compose manifest cannot be read (then a
    member's absence cannot be established, so --without is UNMEASURED)."""
    try:
        sys.path.insert(0, HERE)
        import biomes_compose
        return biomes_compose.folded_ids(src)
    except Exception:
        return None


def loaded(pid, running, alias):
    """Is `pid` in the running load, directly or through the composed mod it is folded into?"""
    pid = pid.strip().lower()
    return pid in running or (pid in (alias or {}) and alias[pid] in running)


def condition(needs, without, running, alias):
    """-> (UNMEASURED, lines) when the criterion's load condition is unmet or unreadable, else (None, lines)."""
    if not needs and not without:
        return None, []
    if not all(p.strip() for p in list(needs) + list(without)):
        return UNMEASURED, ["UNMEASURED: an empty --needs/--without names no mod"]
    if alias is None and without:
        return UNMEASURED, ["UNMEASURED: the compose manifest is unread, so a mod folded into the composed one may be "
                            "loaded unseen: --without cannot be checked"]
    if running is None:
        return UNMEASURED, ["UNMEASURED: the running mod list is unread, so the load condition cannot be checked"]
    miss = [p for p in needs if not loaded(p, running, alias)]
    extra = [p for p in without if loaded(p, running, alias)]
    if miss or extra:
        return UNMEASURED, ["UNMEASURED: the running load %s; the criterion is about another load" % "; ".join(
            (["lacks %s" % ", ".join(miss)] if miss else []) + (["holds %s" % ", ".join(extra)] if extra else []))]
    return None, ["load condition met: %s" % ", ".join(["has %s" % p for p in needs] + ["lacks %s" % p for p in without])]


def with_aliases(owners, alias):
    """owners with each folded member's composed packageId added beside it."""
    alias = alias or {}
    return {k: (None if v is None else set(v) | {alias[p] for p in v if p in alias}) for k, v in owners.items()}


def defs_param(keys):
    """get_defs' `defs` argument: SEMICOLON-separated DefType/defName pairs (JawaBenchTerrainTools.cs GetDefs).
    A comma-joined list reads as one unknown key and every claim comes back unmentioned."""
    return ";".join(keys)


def mod_package_id(path, src=SRC):
    """-> the lower-case packageId of the mod holding `path` (nearest ancestor with About/About.xml), or None."""
    d = os.path.dirname(os.path.abspath(path))
    while d.startswith(os.path.abspath(src)) and len(d) >= len(os.path.abspath(src)):
        about = os.path.join(d, "About", "About.xml")
        if os.path.isfile(about):
            try:
                pid = ET.parse(about).getroot().findtext("packageId")
            except (ET.ParseError, OSError):
                return None
            return pid.strip().lower() if pid and pid.strip() else None
        d = os.path.dirname(d)
    return None


def def_owners(keys, src=SRC):
    """-> {defkey: set of packageIds} for the repo mods whose XML names <defName>NAME</defName>. Missing keys own nothing;
    a key whose search failed maps to None (owner unknown, so an unresolved def cannot be called a FAIL)."""
    out = {}
    for key in keys:
        name = key.split("/", 1)[1]
        try:
            r = subprocess.run(["grep", "-rlF", "--include=*.xml", "<defName>%s</defName>" % name, src],
                               capture_output=True, text=True, timeout=60)
        except (OSError, subprocess.TimeoutExpired):
            out[key] = None
            continue
        if r.returncode not in (0, 1):          # 1 is grep's "no match"; 2 is an error, matches or not
            out[key] = None
            continue
        pids = {p for p in (mod_package_id(f, src) for f in r.stdout.splitlines() if f) if p}
        if pids:
            out[key] = pids
    return out


def running_ids(reply):
    """jawa/running_mods' reply -> lower-case packageIds, or None when it is not that answer."""
    rm = reply.get("result", reply) if isinstance(reply, dict) else None
    if not isinstance(rm, dict):
        return None
    ids = rm.get("packageIds")
    if not isinstance(ids, list) or not ids or not all(isinstance(x, str) and x for x in ids):
        return None
    return {x.lower() for x in ids}


def _bridge(tool, params, timeout, read_only_static=False):
    """-> (reply or None, why). Read-only; runs the client under Windows Python. read_only_static: declare a jawa/static_call
    a read (the client accepts it only for its reviewed READ_ONLY_STATIC_CALLS, else refuses with exit 3)."""
    try:
        path = subprocess.run(["wslpath", "-w", CLIENT], capture_output=True, text=True, timeout=20).stdout.strip()
        r = subprocess.run(["python.exe", path, "--timeout", str(timeout), "--call", tool, "--json", json.dumps(params)]
                           + (["--read-only-static"] if read_only_static else []),
                           capture_output=True, text=True, timeout=timeout + 30, stdin=subprocess.DEVNULL)
    except (OSError, ValueError, subprocess.TimeoutExpired) as e:      # ValueError: UnicodeDecodeError on the reply bytes
        return None, "the bridge call did not finish: %s" % str(e)[:200]
    if r.returncode:
        return None, "bridge call exit %d: %s" % (r.returncode, (r.stderr or r.stdout)[-300:])
    try:
        return json.loads(r.stdout, object_pairs_hook=_no_duplicate_keys), None
    except (ValueError, RecursionError):
        return None, "the bridge answered something that is not JSON: %s" % r.stdout[:200]


