#!/usr/bin/env python3
"""northstar_driver CLI.  LIVE work runs under Windows Python, repo-relative paths:

  python.exe src/RimMandrake/Utils/northstar_driver/cli.py preflight --mod Graffiti
  python.exe src/RimMandrake/Utils/northstar_driver/cli.py run --mod Graffiti --plan <plan.py> [--pipeline]
  python.exe src/RimMandrake/Utils/northstar_driver/cli.py run ... --config full [--list <ModsConfig>]   # full list
  python.exe src/RimMandrake/Utils/northstar_driver/cli.py needs-mods --mod Graffiti [--id <packageId>]  # tier-aware
  python.exe src/RimMandrake/Utils/northstar_driver/cli.py running-list [--list <ModsConfig>]  # FINAL verification

TIERS (PROOF_TIERS_WIDEN_SMALL_LIST_FIRST_ALWAYS, owner 2026-11-02: "small mod lists should always be the way to test
until a final verification pass on the whole huge mod list"): `needs-mods` is how a proof says which game it can run
on: exit 0 when the RUNNING game (jawa/running_mods) holds the mod, its About.xml modDependencies, Core and every DLC,
whatever else is loaded; exit 2 (UNMEASURED, "not in the running load") when it does not. `running-list` and
`run --config full` compare against the whole full list: they are the final verification (rimflow level GREEN-FULL),
never a small-tier proof; a running list holding under half the full list is another tier, exit 2, never a FAIL.
  python3    src/RimMandrake/Utils/northstar_driver/cli.py run --mock --plan <plan.py>   # offline
  python3    src/RimMandrake/Utils/northstar_driver/judge_cli.py <results.json>           # visual half, WSL

Suite bars (`shows=`) are visual: a state PASS reads UNMEASURED until judge_cli.py writes a verdict.

Never touches ModsConfig.xml (read-only fingerprint), never launches the game, never takes the
bridge lock (you hold it: `rimflow bridge who`). Output is JSON (LF) at --out, default
Transient/northstar/<Mod>_<utc>.json, shaped for modcheck: {mod, mode, preflight[], bars[], summary,
expected, all_green, timing, mod_hash}. A LIVE run is then recorded through
modcheck.status.record_run (`modcheck status` shows it); --no-record skips that. Exit 0 = ran and all_green, 1 = ran not green, 2 = refused (dirty site).
A suite plan runs one chain at a time and REWRITES --out after every chain with `partial: true` (chains_done,
chains_pending), so a killed run still leaves its finished rows; the final write sets `partial: false`.
--chains a,b runs only those chains, --skip-chains a,b drops them (a long-wait chain split into its own run);
a chain not run reads UNMEASURED 'chain not run', never absent.
"""
import argparse
import copy
import importlib.util
import json
import os
import sys
import time

_HERE = os.path.dirname(os.path.abspath(__file__))
_UTILS = os.path.dirname(_HERE)
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(_UTILS)))
for p in (_UTILS, os.path.join(_UTILS, "modcheck")):
    if p not in sys.path:
        sys.path.insert(0, p)

from northstar_driver import PASS, FAIL, UNMEASURED                       # noqa: E402
from northstar_driver import preflight as pf, bars as B                   # noqa: E402
from northstar_driver.session import FastSession                          # noqa: E402
from northstar_driver.transport import MockTransport, MockGame            # noqa: E402


def _rel(*parts):
    return os.path.join(ROOT, *parts)


def load_plan(path):
    spec = importlib.util.spec_from_file_location("ns_plan_" + os.path.basename(path)[:-3], path)
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m


def expected_bars(mod):
    """Must-show + cannot-show ids from the mod's walk, ONLY when VALIDATED (else binds nothing)."""
    try:
        import northstar
        w = northstar.find_walk(ROOT, mod)
        if not w:
            return [], "no walk"
        ns = northstar.parse(w)
        if ns["state"] != northstar.VALIDATED:
            return [], "walk is DRAFT (%s)" % ns["reason"]
        return list(ns["must_show"]) + list(ns["cannot_show"]), "VALIDATED walk %s" % os.path.basename(w)
    except Exception as ex:
        return [], "walk unreadable: %s" % ex


def _folded_into_composed(src_dir):
    try:
        import biomes_compose
        return os.path.basename(os.path.abspath(src_dir)) in biomes_compose.folded_sources(_rel("src"))
    except Exception:
        return False


def mod_dirs_for(mod):
    if not mod:
        return []
    import game_paths
    out = []
    for tier in ("RimMandrake", "RimStarWars", "RimUtinni"):
        d = _rel("src", tier, mod)
        if _folded_into_composed(d):
            continue            # deployed inside RimMandrake.Biomes; that composed deploy is gated by the mod's own preflight
        if os.path.isfile(os.path.join(d, "About", "About.xml")):
            # the deployed folder is named like the repo folder (deploy_custom_mods.py is the authority)
            out.append((d, os.path.join(game_paths.STEAM, "common", "RimWorld", "Mods", mod)))
    return out


def mock_config(ids):
    """Hermetic ModsConfig for mock runs -- the real one is never read or written."""
    import tempfile
    d = tempfile.mkdtemp(prefix="ns_mock_")
    p = os.path.join(d, "ModsConfig.xml")
    with open(p, "w") as f:
        f.write("<ModsConfigData><activeMods>%s</activeMods></ModsConfigData>" %
                "".join("<li>%s</li>" % i for i in ["ludeon.rimworld"] + list(ids)))
    return p


def running_list_for(args):
    """Full-list mode: the list file the RUNNING game must equal (--list, default FULL.LATEST); None otherwise."""
    if getattr(args, "config", "current") != "full":
        return None
    return getattr(args, "list", None) or pf.FULL_LATEST


def open_session(args, plan=None):
    if args.mock:
        game = MockGame(faults=[f for f in (args.fault or "").split(",") if f])
        game.ext = getattr(plan, "mock_extension", None)   # a plan may bring its own in-memory mod model
        return FastSession(transport=MockTransport(game), strict=False), game
    return FastSession(pipeline=args.pipeline, strict=False), None


def cmd_preflight(args):
    s, _ = open_session(args)
    with s:
        cs = pf.run_preflight(s, mod_dirs=[] if args.mock and not args.mod else mod_dirs_for(args.mod),
                              expect_ids=args.expect_id or (), need_god=args.god, rect=args.rect,
                              fix=args.fix, extra_tools=(),
                              config_path=mock_config(args.expect_id or ()) if args.mock else None,
                              running_list=running_list_for(args))
    ok, bad, unk = pf.verdict(cs, args.allow_unmeasured)
    for c in cs:
        print("%-11s %-24s %s" % (c.status, c.name, c.evidence))
    print("PREFLIGHT %s" % ("OK" if ok else "REFUSED: %d FAIL, %d UNMEASURED" % (len(bad), len(unk))))
    return 0 if ok else 2


def exit_code(status):
    """PASS 0, FAIL 1, UNMEASURED 2: a game of another tier is unmeasured, never a FAIL of the item."""
    return {PASS: 0, FAIL: 1}.get(status, 2)


def cmd_running_list(args):
    """READ-ONLY FINAL VERIFICATION: the RUNNING list (jawa/running_mods) against --list (default FULL.LATEST).
    Exit 0 iff identical, 1 differs, 2 unmeasured (no reply, or another tier is up)."""
    s, _ = open_session(args)
    with s:
        c = pf.check_running_list(s, getattr(args, "list", None) or pf.FULL_LATEST)
    print("%-11s %-24s %s" % (c.status, c.name, c.evidence))
    return exit_code(c.status)


def about_xml_for(mod):
    """The repo About.xml of mod folder `mod` (any tier, folded into the composed biomes or not)."""
    for tier in ("RimMandrake", "RimStarWars", "RimUtinni"):
        p = _rel("src", tier, mod, "About", "About.xml")
        if os.path.isfile(p):
            return p
    raise ValueError("no src/<tier>/%s/About/About.xml" % mod)


def needs_for(mods=(), ids=()):
    return pf.needed_ids([about_xml_for(m) for m in mods or ()], ids or ())


def cmd_needs_mods(args):
    """READ-ONLY, TIER-AWARE: exit 0 iff the RUNNING game holds what the proof needs; 2 when it does not."""
    try:
        need = needs_for(args.mod, args.id)
    except (OSError, ValueError) as ex:
        print("UNMEASURED  needed_mods              %s" % ex)
        return 2
    s, _ = open_session(args)
    with s:
        c = pf.check_needed_mods(s, need)
    print("%-11s %-24s %s" % (c.status, c.name, c.evidence))
    return exit_code(c.status)


def cmd_run(args):
    plan = load_plan(args.plan) if args.plan else None
    s, game = open_session(args, plan)
    mod = args.mod or (getattr(plan, "MOD", None) if plan else None) or "adhoc"
    exp, why = expected_bars(mod)
    mod_dir, start_hash = mod_hash_now(mod)
    doc = {"mod": mod, "mode": "mock" if args.mock else "live", "started_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
           "expected": exp, "expected_source": why, "bars": [], "preflight": [], "compat": [],
           "config": args.config, "config_list": running_list_for(args)}
    out = args.out or _rel("Transient", "northstar", "%s%s_%s.json" % (
        mod, "_full" if args.config == "full" else "", time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())))
    with s:
        cs = pf.run_preflight(s, mod_dirs=[] if args.mock else mod_dirs_for(mod),
                              expect_ids=getattr(plan, "EXPECT_MODS", ()) or args.expect_id or (),
                              need_god=args.god or getattr(plan, "NEED_GOD", False),
                              rect=args.rect or getattr(plan, "RECT", None), fix=args.fix,
                              config_path=mock_config(getattr(plan, "EXPECT_MODS", ()) or args.expect_id or ()) if args.mock else None,
                              running_list=running_list_for(args))
        if args.config == "full" and getattr(plan, "full_list_differences", None):
            try:
                doc["full_list_differences"] = plan.full_list_differences(running_list_for(args))
            except Exception as ex:   # noqa: BLE001 - the sheet section says it could not be built; never silent
                doc["full_list_differences"] = {"error": "%s: %s" % (type(ex).__name__, ex)}
        # mod-supplied site check: plan.preflight(s) -> [failed precondition, ...] (plan 3.13)
        if getattr(plan, "preflight", None) and not args.mock_skip_site:
            try:
                for msg in call_plan_preflight(plan, s, _csv(args.chains)) or []:
                    cs.append(pf.Check("site:" + msg.split(":")[0][:40], FAIL, msg))
            except Exception as ex:
                cs.append(pf.Check("site_preflight", UNMEASURED, "%s: %s" % (type(ex).__name__, ex)))
        # cannot-show enforcement (plan 6.10): a VALIDATED walk's cannot-show id that no component claims
        if getattr(plan, "USE_SUITE", False):
            miss = unclaimed_cannot_show(mod)
            if miss:
                cs.append(pf.Check("cannot_show_claimed", FAIL,
                                   "cannot-show id(s) no component claims via shows=: %s" % miss))
        doc["preflight"] = [c.as_dict() for c in cs]
        ok, bad, unk = pf.verdict(cs, args.allow_unmeasured)
        if not ok:
            doc.update(refused="; ".join("%s %s" % (c.name, c.status) for c in bad + unk),
                       all_green=False, summary=B.summarize([]))
            code = 2
        else:
            wanted = [b for b in B.REGISTRY.values() if b.mod in (None, mod)]
            rows = [B.run_bar(b, s) for b in wanted]
            if getattr(plan, "USE_SUITE", False):
                rows += _suite_rows(s, mod, exp, doc, only=_csv(args.chains), skip=_csv(args.skip_chains),
                                    progress=lambda d: B.write_results(out, d), pre_rows=rows)
            doc["bars"] = rows
            doc["summary"] = B.summarize(rows)
            doc["all_green"] = run_all_green(rows, exp)
            if args.mock and getattr(plan, "MOCK_LIVE_ONLY", None):
                # a row the plan DECLARES unmeasurable offline (it needs a live map) reads UNMEASURED in every mock run;
                # a mock run is judged without those rows and names them. Only UNMEASURED is set aside: a FAIL fails.
                lo = set(plan.MOCK_LIVE_ONLY)
                skip = [r["id"] for r in rows if r["id"] in lo and r["status"] == UNMEASURED]
                if skip:
                    doc["mock_live_only_unmeasured"] = skip
                    doc["all_green"] = run_all_green([r for r in rows if r["id"] not in skip], exp)
                    print("mock: %d live-only row(s) set aside, UNMEASURED offline by declaration: %s"
                          % (len(skip), ", ".join(skip)))
            code = 0 if doc["all_green"] else 1
        doc["timing"] = s.timing
    doc["partial"] = False
    if mod_dir:
        doc["mod_hash"] = start_hash
    B.write_results(out, doc)
    if not args.mock and not args.no_record:
        _entry, msg = record_result(doc, mod, out, start_hash, mod_dir)
        print(msg)
    print("%s: %s  PASS=%s FAIL=%s UNMEASURED=%s  calls=%d mean=%.3fms  -> %s" % (
        mod, "REFUSED" if code == 2 else ("GREEN" if code == 0 else "NOT GREEN"),
        doc["summary"][PASS], doc["summary"][FAIL], doc["summary"][UNMEASURED],
        doc["timing"]["n"], doc["timing"]["mean_ms"], out))
    return code


def mod_hash_now(mod):
    """(mod_dir, modcheck.status.mod_hash) for a repo mod, or (None, None) for an ad-hoc run."""
    try:
        import runner
        import status
        d = runner.find_mod_dir(mod)
        return d, status.mod_hash(d)
    except Exception:
        return None, None


def record_result(doc, mod, out, start_hash, mod_dir, _record=None):
    """Record a finished run through modcheck.status.record_run (the only writer of
    modcheck_status.json), as runner.py does after `modcheck run`. Returns (entry|None, message).
    Not recorded, by design: a mock run (cmd_run never calls this for one), a preflight refusal
    (the SITE was refused, the mod never ran), a run with no rows, an ad-hoc mod with no repo
    folder, and a run during which the mod's files changed (its verdict would describe neither
    hash). The verdict is the run's own all_green: any FAIL or UNMEASURED row is not GREEN."""
    import northstar
    import status
    if not mod_dir or not start_hash:
        return None, "not recorded: %s has no repo mod folder" % mod
    if doc.get("refused"):
        return None, "not recorded: refused at preflight (%s) -- a site verdict, not the mod's" % doc["refused"][:160]
    rows = doc.get("bars") or []
    if not rows:
        return None, "not recorded: the run produced no rows"
    now = status.mod_hash(mod_dir)
    if now != start_hash:
        return None, "not recorded: %s changed during the run (%s -> %s)" % (mod, start_hash[:12], now[:12])
    rel = result_path(out)
    by = {}
    for r in rows:
        by.setdefault(r["status"], []).append(r["id"])
    extra = {"components": {"counts": {k: len(v) for k, v in by.items()},
                            "not_ok": [i for k, v in by.items() if k != PASS for i in v]},
             "bars": {r["id"]: r["status"] for r in rows},
             "source": {"verb": "northstar_driver run", "result": rel, "mode": doc.get("mode"),
                        "started": doc.get("started_utc"), "expected_source": doc.get("expected_source"),
                        "config": doc.get("config") or "current"},
             "config": doc.get("config") or "current"}
    if doc.get("compat"):
        extra["compat"] = {r["id"]: r["status"] for r in doc["compat"]}
    run_id = "%s/northstar_driver[%s]@%s" % (mod, doc.get("config") or "current", os.path.basename(out))
    entry = (_record or status.record_run)(mod, mod_dir, run_id, bool(doc.get("all_green")),
                                           walk=northstar.find_walk(ROOT, mod), extra=extra)
    return entry, "recorded %s: %s at %s (%s)" % (mod, entry["status"], entry["hash"][:12], run_id)


def result_path(out, root=None):
    """`out` relative to the repo, or absolute when it lies on another drive: Windows relpath raises ValueError for a
    D:\\ --out under a \\\\wsl.localhost repo (live 2026-11-03, after the run had already been written)."""
    try:
        return os.path.relpath(os.path.abspath(out), root or ROOT).replace(os.sep, "/")
    except ValueError:
        return os.path.abspath(out).replace(os.sep, "/")


def unclaimed_cannot_show(mod):
    """Cannot-show ids of a VALIDATED walk that no component's `shows=` claims. [] when no walk."""
    try:
        import northstar
        import runner
        w = northstar.find_walk(ROOT, mod)
        ns = northstar.parse(w) if w else None
        if not ns or ns["state"] != northstar.VALIDATED:
            return []
        claimed = set()
        for c in runner.load_validation(runner.find_mod_dir(mod)).components_declared():
            claimed.update(c.get("shows") or ())
        return [i for i in ns["cannot_show"] if i not in claimed]
    except Exception as ex:
        return ["(unreadable: %s)" % ex]


def _csv(v):
    return [x.strip() for x in (v or "").split(",") if x.strip()] or None


def call_plan_preflight(plan, s, chains):
    """plan.preflight(s), or plan.preflight(s, chains=[...]) when the plan accepts it: a site precondition only some
    chains need (ExplosiveGrowth's plant temperature) may then be skipped for a --chains run that needs none of them.
    chains None = every chain."""
    import inspect
    try:
        takes = "chains" in inspect.signature(plan.preflight).parameters
    except (TypeError, ValueError):
        takes = False
    return plan.preflight(s, chains=chains) if takes else plan.preflight(s)


def select_chains(chains, only=None, skip=None):
    """(run, skipped) from the suite's [(name, fn)] in suite order. `only` keeps just those names, `skip` drops
    those names; a name that matches no chain raises, so a typo can never silently run (or skip) nothing."""
    names = [n for n, _ in chains]
    unknown = [n for n in (only or []) + (skip or []) if n not in names]
    if unknown:
        raise SystemExit("unknown chain name(s) %s; the suite has: %s" % (unknown, ", ".join(names)))
    run, skipped = [], []
    for n, fn in chains:
        (skipped if (only and n not in only) or (skip and n in skip) else run).append((n, fn))
    return run, skipped


def skipped_chain_records(suite, skipped, why):
    """One UNMEASURED component per DECLARED component of each skipped chain (the offline declaration probe), so
    its bars read 'not run: <why>' rather than 'no component claims' and a split run is never mistaken for green."""
    out = []
    for name, fn in skipped:
        sub = copy.copy(suite)
        sub.chains = [(name, fn)]
        try:
            decl = sub.components_declared()
        except Exception as ex:   # noqa: BLE001 - a declaration that cannot be probed still records the skip
            decl = [{"shows": [], "error": "%s: %s" % (type(ex).__name__, ex)}]
        out.append({"name": name, "skipped": True, "components": [
            {"name": "skipped#%d" % i, "verdict": UNMEASURED, "shows": list(d.get("shows") or ()),
             "toggle": d.get("toggle"), "detail": "UNMEASURED: chain not run (%s)" % why}
            for i, d in enumerate(decl or [{"shows": []}])]})
    return out


def _rows_from(chains, expected, texts):
    """Compat components are partitioned out FIRST: a `compat_*` row never reaches the bar rollup, even if it
    (wrongly) claims a `shows=` bar."""
    own = [dict(ch, components=[c for c in ch["components"] if not is_compat(c)]) for ch in chains]
    return mark_visual(B.rollup_components(own, expected), texts) + functional_rows(own)


COMPAT_PREFIX = "compat_"


def is_compat(c):
    """A compatibility component (Graffiti plan: foreign mark defs of SacredGraffiti / GraffitiImperial on the
    full list): named `compat_*` (the prefix alone decides; a `shows=` claim on one is ignored). Reported in
    doc["compat"], never in the mod's bars, its summary or its verdict."""
    return str(c.get("name", "")).startswith(COMPAT_PREFIX)


def compat_rows(chains):
    out = []
    for ch in chains:
        for c in ch["components"]:
            if not is_compat(c):
                continue
            v = str(c.get("verdict", ""))
            st = PASS if v.startswith("PASS") else (FAIL if v == "FAIL" else UNMEASURED)
            out.append({"id": "%s.%s" % (ch.get("name"), c.get("name")), "status": st, "compat": True,
                        "evidence": str(c.get("detail") or v)})
    return out


def _suite_rows(s, mod, expected, doc, only=None, skip=None, progress=None, pre_rows=(), suite=None):
    """Run the suite ONE CHAIN AT A TIME and hand `progress` a partial results doc after every chain, so a run
    killed mid-suite (2026-10-12: a 50-min shell timeout inside embergrass_regrow left no JSON at all) still
    leaves every finished row on disk. Each chain gets runner.run_suite on a one-chain copy of the suite with the
    same anchor, which is what one whole-suite call did per chain (mod=None, situational off)."""
    import runner
    suite = suite or runner.load_validation(runner.find_mod_dir(mod))
    run, skipped = select_chains(suite.chains, only, skip)
    why = "--chains %s" % ",".join(only) if only else ""
    why = (why + " " if why else "") + ("--skip-chains %s" % ",".join(skip) if skip else "")
    skipped_out = skipped_chain_records(suite, skipped, why.strip())
    doc["chains_selected"] = [n for n, _ in run]
    doc["chains_skipped"] = [n for n, _ in skipped]
    doc["bar_text"], doc["bar_text_source"] = bar_text(mod)
    anchor = runner._default_anchor(s)
    done = []
    for i, (name, fn) in enumerate(run):
        sub = copy.copy(suite)
        sub.chains = [(name, fn)]
        res = runner.run_suite(sub, s, anchor=anchor, mod=None)   # visual half: judge_cli.py, after the run
        done.extend(res["chains"])
        if progress is not None:
            part = dict(doc, partial=True, chains_done=[c.get("name") for c in done],
                        chains_pending=[n for n, _ in run[i + 1:]], components=component_records(done))
            part["bars"] = list(pre_rows) + _rows_from(done + skipped_out, expected, doc["bar_text"])
            part["summary"] = B.summarize(part["bars"])
            part["compat"] = compat_rows(done)
            part["all_green"] = False
            progress(part)
    chains = done + skipped_out
    for ch in chains:
        for c in ch["components"]:
            if not str(c.get("verdict", "")).startswith("PASS"):
                print("component %s/%s: %s" % (ch.get("name"), c.get("name"),
                                               json.dumps({k: v for k, v in c.items() if k != "name"}, default=str)[:600]))
    doc["components"] = component_records(chains)
    doc["compat"] = compat_rows(chains)
    return _rows_from(chains, expected, doc["bar_text"])


def functional_rows(chains):
    """One row per suite component that claims no `shows=` bar: the mod's functional script
    (debug_process.md section 2). Without these a suite FAIL never reached the summary or the verdict,
    and a mod with no north star could never be GREEN (zero rows). Status is the component's own."""
    out = []
    for ch in chains:
        for c in ch["components"]:
            if c.get("shows") or is_compat(c):
                continue
            v = str(c.get("verdict", ""))
            st = PASS if v.startswith("PASS") else (FAIL if v == "FAIL" else UNMEASURED)
            out.append({"id": "%s.%s" % (ch.get("name"), c.get("name")), "status": st, "functional": True,
                        "evidence": str(c.get("detail") or v)[:300],
                        "evidenceFull": str(c.get("detail") or v)})
    return out


def run_all_green(rows, expected):
    """Every expected north-star bar PASS (bars.all_green) AND every functional row PASS."""
    return B.all_green(rows, expected or None) and all(r["status"] == PASS for r in rows if r.get("functional"))


def to_wsl(p):
    """`C:\\x\\y.png` -> `/mnt/c/x/y.png`; a POSIX path is returned unchanged."""
    p = str(p or "")
    if len(p) > 2 and p[1] == ":" and p[0].isalpha():
        return "/mnt/%s/%s" % (p[0].lower(), p[2:].replace("\\", "/").lstrip("/"))
    return p


def to_win(p):
    """`/mnt/c/x/y.png` -> `C:\\x\\y.png`; a Windows path is returned unchanged."""
    p = str(p or "")
    if p.startswith("/mnt/") and len(p) > 6 and p[6] == "/":
        return "%s:\\%s" % (p[5].upper(), p[7:].replace("/", "\\"))
    return p


def component_records(chains):
    """Every component, with each screenshot as {path (as the bridge returned it), win, wsl}, so the
    WSL-side judge can find the image without re-deriving anything."""
    out = []
    for ch in chains:
        for c in ch["components"]:
            # evidenceFull: a component whose `shows=` bar is not a driver bar (every pyre_* north-star bar) reaches the
            # result JSON ONLY here; without it a FAIL's reason survived only as a 600-char console line (2026-10-12c).
            out.append({"chain": ch.get("name"), "name": c.get("name"), "verdict": c.get("verdict"),
                        "evidenceFull": str(c.get("detail") or c.get("verdict") or ""),
                        "shows": list(c.get("shows") or ()),
                        "screenshots": [{"path": p, "win": to_win(p), "wsl": to_wsl(p)}
                                        for p in (c.get("screenshots") or ()) if p]})
    return out


def bar_text(mod):
    """{bar id: {polarity, text}} from the VALIDATED walk -- the narrow question the judge asks."""
    try:
        import northstar
        w = northstar.find_walk(ROOT, mod)
        ns = northstar.parse(w) if w else None
        if not ns or ns["state"] != northstar.VALIDATED:
            return {}, "no VALIDATED walk"
        out = {i: {"polarity": "must", "text": ns["must_show_text"].get(i, "")} for i in ns["must_show"]}
        out.update({i: {"polarity": "cannot", "text": ns["cannot_show_text"].get(i, "")}
                    for i in ns["cannot_show"]})
        return out, "%s (hash %s)" % (os.path.relpath(w, ROOT), ns.get("recorded_hash", ""))
    except Exception as ex:
        return {}, "walk unreadable: %s" % ex


def mark_visual(rows, texts):
    """Every `shows=` bar is judged on its screenshots, so state alone cannot PASS it: a state PASS
    reads UNMEASURED until judge_cli.py writes a verdict. The state result is kept in `state_status`."""
    for r in rows:
        r["visual"] = True
        r["polarity"] = (texts.get(r["id"]) or {}).get("polarity", "must")
        r["state_status"], r["state_evidence"] = r["status"], r["evidence"]
        if r["status"] == PASS:
            r["status"] = UNMEASURED
            r["evidence"] = "visual bar: state PASS, not yet judged (run judge_cli.py) [%s]" % r["evidence"]
    return rows


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = ap.add_subparsers(dest="cmd", required=True)
    for name, fn in (("preflight", cmd_preflight), ("run", cmd_run)):
        p = sub.add_parser(name)
        p.set_defaults(fn=fn)
        p.add_argument("--mod")
        p.add_argument("--mock", action="store_true", help="in-memory game; no bridge")
        p.add_argument("--fault", help="mock faults, comma list: zombie,modal,pause_lies,dev_off,god_off,dirty,unfrozen")
        p.add_argument("--god", action="store_true", help="require god mode")
        p.add_argument("--rect", help="x,z,w,h test area that must be empty")
        p.add_argument("--fix", action="store_true", help="pause / enable god, each proved by re-read")
        p.add_argument("--expect-id", action="append", help="packageId that must be active (repeat)")
        p.add_argument("--allow-unmeasured", action="store_true")
        p.add_argument("--mock-skip-site", action="store_true", help="skip plan.preflight (offline selftests)")
        p.add_argument("--pipeline", action="store_true", help="pipelined call_many (correct but no faster: 1 reply/frame, pipecheck.py 2026-10-21)")
        p.add_argument("--config", choices=("current", "full"), default="current",
                       help="full = full-list mode (plan 6.8): no list swap; the RUNNING list (jawa/running_mods) must "
                            "equal --list (default FULL.LATEST) or the run refuses; recorded with config 'full'")
        p.add_argument("--list", help="full-list mode: the ModsConfig-shaped file the running list must equal")
        if name == "run":
            p.add_argument("--plan", help="python plan module registering @bar functions")
            p.add_argument("--out")
            p.add_argument("--no-record", action="store_true",
                           help="live run only: do not record it in modcheck_status.json")
            p.add_argument("--chains", help="suite plans: run ONLY these chains (comma list); the rest read "
                                            "UNMEASURED 'chain not run'")
            p.add_argument("--skip-chains", help="suite plans: skip these chains (comma list), e.g. a long-wait "
                                                 "chain split into its own run")
    p = sub.add_parser("running-list", help="READ-ONLY FINAL VERIFICATION: running list vs --list (default "
                                            "FULL.LATEST); exit 0 equal, 1 differs, 2 unmeasured or another tier")
    p.set_defaults(fn=cmd_running_list, mock=False, pipeline=False)
    p.add_argument("--list")
    p = sub.add_parser("needs-mods", help="READ-ONLY, tier-aware: exit 0 iff the running game holds each --mod (its "
                                          "About.xml packageId + modDependencies), each --id, Core and every DLC; 2 if not")
    p.set_defaults(fn=cmd_needs_mods, mock=False, pipeline=False)
    p.add_argument("--mod", action="append", help="repo mod folder, e.g. Graffiti (repeat)")
    p.add_argument("--id", action="append", help="extra packageId the proof needs (repeat)")
    a = ap.parse_args(argv)
    return a.fn(a)


if __name__ == "__main__":
    sys.exit(main())

scripts.src/RimMandrake/Utils/live_def_check.py:
#!/usr/bin/env python3
"""live_def_check.py -- does the RUNNING game's def carry what a criterion says it must? One read-only jawa/get_defs call.

    python3 src/RimMandrake/Utils/live_def_check.py --has ThingDef/RM_Chittik=CompProperties_WoundLink [--has ...]

Each --has is DefType/defName=TOKEN: the def must resolve in the live game, and TOKEN must appear as a whole value in the
def's reported fields (a comp class, a field value). `--has DefType/defName` with no `=` asks only that it resolves.

Exit 0 every claim holds, 1 a claim is false (the game answered and said no: a real FAIL), 2 UNMEASURED (no bridge, an
answer that is not what get_defs returns, a def the reply never mentions). Callers hold the bridge lock; this never takes it.

A def that does not resolve is a FAIL only when the mod that defines it is in the RUNNING load. Its owners are the repo's
mods whose XML carries <defName>NAME</defName>; the running load is jawa/running_mods (ModsConfig.xml names the NEXT
load, so a mod enabled after launch is absent here). Owner not running, or the running list unreadable: UNMEASURED. A def
no repo mod defines (a typo, a vanilla or donor def) stays a FAIL: the game answered and nothing explains the no.
A mod folded into the composed biomes mod loads under the composed packageId, so an owner or a --needs naming the member
is also met by the composed id (biomes_compose.folded_ids); without that, a composed def that fails to resolve could only
ever read UNMEASURED.

--needs PACKAGEID / --without PACKAGEID state a criterion's load condition ("with Quarry loaded", "on a tier carrying
Warcasket", "with Alpha Biomes absent"): unmet, or the running list unread, is UNMEASURED before any def is judged. A donor
def no repo mod defines is a FAIL when it does not resolve, so a criterion about a donor's def needs its --needs.
RimBridge binds Windows loopback, so the call runs under Windows Python (python.exe), as rimbridge_client.py says.
"""
import argparse
import json
import os
import subprocess
import sys
import xml.etree.ElementTree as ET

HERE = os.path.dirname(os.path.abspath(__file__))
CLIENT = os.path.join(HERE, "rimbridge_client.py")
SRC = os.path.normpath(os.path.join(HERE, "..", ".."))      # the repo's src/: every mod we ship lives under it
PASS, FAIL, UNMEASURED = 0, 1, 2


def parse_claims(items):
    """-> [(defkey, token or None)]; ValueError on a claim that is not DefType/defName[=TOKEN]."""
    out = []
    for raw in items:
        key, _, token = raw.partition("=")
        key, token = key.strip(), token.strip()
        if "=" in raw and not token:
            raise ValueError("an empty TOKEN would weaken the claim to existence-only; drop the '=': %r" % raw)
        if key.count("/") != 1 or not all(key.split("/")):
            raise ValueError("not DefType/defName[=TOKEN]: %r" % raw)
        out.append((key, token or None))
    return out


def values(node):
    """Every scalar in a JSON tree, as strings: the token is matched against these whole, never as a substring."""
    if isinstance(node, dict):
        for v in node.values():
            yield from values(v)
    elif isinstance(node, list):
        for v in node:
            yield from values(v)
    elif node is not None:
        yield str(node)


def _no_duplicate_keys(pairs):
    """json keeps the LAST of a repeated key, so found:false,found:true would read as true: that is no answer."""
    keys = [k for k, _ in pairs]
    if len(set(keys)) != len(keys):
        raise ValueError("a JSON object repeats a key")
    return dict(pairs)


def _canon(d):
    """A record as the claim reads it: JSON text, so True and 1 stay different (python's == merges them)."""
    return json.dumps([d.get("found"), d.get("fields")], sort_keys=True, default=str)


def judge(claims, reply, owners=None, running=None):
    """-> (exit code, lines). `reply` is get_defs' JSON object. `owners` {defkey: set of lower-case packageIds defining
    it}; `running` the lower-case packageIds of the RUNNING load, or None when unread. With no `owners` an unresolved
    def is a FAIL, as before."""
    if not isinstance(reply, dict) or not isinstance(reply.get("defs"), list):
        return UNMEASURED, ["UNMEASURED: the reply is not a get_defs answer"]
    by_key, bad = {}, set()
    for d in reply["defs"]:
        if not isinstance(d, dict) or not isinstance(d.get("requested"), str) or not d["requested"]:
            return UNMEASURED, ["UNMEASURED: a def record without a string `requested`: %r" % (d,)]
        if d["requested"] in by_key and _canon(by_key[d["requested"]]) != _canon(d):
            bad.add(d["requested"])          # two records that disagree: neither is the answer
        by_key[d["requested"]] = d
    seen, lines = set(), []
    for key, token in claims:
        d = by_key.get(key)
        if d is None:
            seen.add(UNMEASURED)
            lines.append("UNMEASURED %s: the reply does not mention it" % key)
            continue
        if key in bad or not isinstance(d.get("found"), bool) or (
                token is not None and d.get("found") and not isinstance(d.get("fields"), (dict, list))):
            seen.add(UNMEASURED)
            lines.append("UNMEASURED %s: the record is malformed or contradicts another (found=%r)" % (key, d.get("found")))
            continue
        if not d.get("found"):
            if owners and key in owners and owners[key] is None:
                seen.add(UNMEASURED)
                lines.append("UNMEASURED %s: does not resolve, and the search for the mod that defines it failed" % key)
                continue
            mods = sorted((owners or {}).get(key) or ())
            if mods and running is None:
                seen.add(UNMEASURED)
                lines.append("UNMEASURED %s: does not resolve, and the running mod list is unread, so whether %s is "
                             "loaded is unknown" % (key, "/".join(mods)))
            elif mods and not set(mods) & set(running):
                seen.add(UNMEASURED)
                lines.append("UNMEASURED %s: does not resolve because %s is not in the RUNNING load (ModsConfig names "
                             "the next load)" % (key, "/".join(mods)))
            else:
                seen.add(FAIL)
                lines.append("FAIL %s: does not resolve in the live game%s" % (
                    key, " though %s is loaded" % "/".join(sorted(set(mods) & set(running))) if mods else ""))
            continue
        where = "%s from %s" % (key, d.get("packageId") or "?")
        if token is None:
            lines.append("PASS %s resolves" % where)
        elif token in set(values(d.get("fields"))):
            lines.append("PASS %s carries %s" % (where, token))
        else:
            seen.add(FAIL)
            lines.append("FAIL %s lacks %s" % (where, token))
    return (FAIL if FAIL in seen else UNMEASURED if UNMEASURED in seen else PASS), lines   # a real FAIL stands


def aliases(src=SRC):
    """-> {folded member packageId (lower): composed packageId}; None when the compose manifest cannot be read (then a
    member's absence cannot be established, so --without is UNMEASURED)."""
    try:
        sys.path.insert(0, HERE)
        import biomes_compose
        return biomes_compose.folded_ids(src)
    except Exception:
        return None


def loaded(pid, running, alias):
    """Is `pid` in the running load, directly or through the composed mod it is folded into?"""
    pid = pid.strip().lower()
    return pid in running or (pid in (alias or {}) and alias[pid] in running)


def condition(needs, without, running, alias):
    """-> (UNMEASURED, lines) when the criterion's load condition is unmet or unreadable, else (None, lines)."""
    if not needs and not without:
        return None, []
    if not all(p.strip() for p in list(needs) + list(without)):
        return UNMEASURED, ["UNMEASURED: an empty --needs/--without names no mod"]
    if alias is None and without:
        return UNMEASURED, ["UNMEASURED: the compose manifest is unread, so a mod folded into the composed one may be "
                            "loaded unseen: --without cannot be checked"]
    if running is None:
        return UNMEASURED, ["UNMEASURED: the running mod list is unread, so the load condition cannot be checked"]
    miss = [p for p in needs if not loaded(p, running, alias)]
    extra = [p for p in without if loaded(p, running, alias)]
    if miss or extra:
        return UNMEASURED, ["UNMEASURED: the running load %s; the criterion is about another load" % "; ".join(
            (["lacks %s" % ", ".join(miss)] if miss else []) + (["holds %s" % ", ".join(extra)] if extra else []))]
    return None, ["load condition met: %s" % ", ".join(["has %s" % p for p in needs] + ["lacks %s" % p for p in without])]


def with_aliases(owners, alias):
    """owners with each folded member's composed packageId added beside it."""
    alias = alias or {}
    return {k: (None if v is None else set(v) | {alias[p] for p in v if p in alias}) for k, v in owners.items()}


def defs_param(keys):
    """get_defs' `defs` argument: SEMICOLON-separated DefType/defName pairs (JawaBenchTerrainTools.cs GetDefs).
    A comma-joined list reads as one unknown key and every claim comes back unmentioned."""
    return ";".join(keys)


def mod_package_id(path, src=SRC):
    """-> the lower-case packageId of the mod holding `path` (nearest ancestor with About/About.xml), or None."""
    d = os.path.dirname(os.path.abspath(path))
    while d.startswith(os.path.abspath(src)) and len(d) >= len(os.path.abspath(src)):
        about = os.path.join(d, "About", "About.xml")
        if os.path.isfile(about):
            try:
                pid = ET.parse(about).getroot().findtext("packageId")
            except (ET.ParseError, OSError):
                return None
            return pid.strip().lower() if pid and pid.strip() else None
        d = os.path.dirname(d)
    return None


def def_owners(keys, src=SRC):
    """-> {defkey: set of packageIds} for the repo mods whose XML names <defName>NAME</defName>. Missing keys own nothing;
    a key whose search failed maps to None (owner unknown, so an unresolved def cannot be called a FAIL)."""
    out = {}
    for key in keys:
        name = key.split("/", 1)[1]
        try:
            r = subprocess.run(["grep", "-rlF", "--include=*.xml", "<defName>%s</defName>" % name, src],
                               capture_output=True, text=True, timeout=60)
        except (OSError, subprocess.TimeoutExpired):
            out[key] = None
            continue
        if r.returncode not in (0, 1):          # 1 is grep's "no match"; 2 is an error, matches or not
            out[key] = None
            continue
        pids = {p for p in (mod_package_id(f, src) for f in r.stdout.splitlines() if f) if p}
        if pids:
            out[key] = pids
    return out


def running_ids(reply):
    """jawa/running_mods' reply -> lower-case packageIds, or None when it is not that answer."""
    rm = reply.get("result", reply) if isinstance(reply, dict) else None
    if not isinstance(rm, dict):
        return None
    ids = rm.get("packageIds")
    if not isinstance(ids, list) or not ids or not all(isinstance(x, str) and x for x in ids):
        return None
    return {x.lower() for x in ids}


def _bridge(tool, params, timeout, read_only_static=False):
    """-> (reply or None, why). Read-only; runs the client under Windows Python. read_only_static: declare a jawa/static_call
    a read (the client accepts it only for its reviewed READ_ONLY_STATIC_CALLS, else refuses with exit 3)."""
    try:
        path = subprocess.run(["wslpath", "-w", CLIENT], capture_output=True, text=True, timeout=20).stdout.strip()
        r = subprocess.run(["python.exe", path, "--timeout", str(timeout), "--call", tool, "--json", json.dumps(params)]
                           + (["--read-only-static"] if read_only_static else []),
                           capture_output=True, text=True, timeout=timeout + 30, stdin=subprocess.DEVNULL)
    except (OSError, ValueError, subprocess.TimeoutExpired) as e:      # ValueError: UnicodeDecodeError on the reply bytes
        return None, "the bridge call did not finish: %s" % str(e)[:200]
    if r.returncode:
        return None, "bridge call exit %d: %s" % (r.returncode, (r.stderr or r.stdout)[-300:])
    try:
        return json.loads(r.stdout, object_pairs_hook=_no_duplicate_keys), None
    except (ValueError, RecursionError):
        return None, "the bridge answered something that is not JSON: %s" % r.stdout[:200]


def call_running_mods(timeout):
    """-> set of lower-case packageIds the RUNNING game loaded, or None."""
    reply, _ = _bridge("jawa/running_mods", {"details": False, "assembly": ""}, timeout)
    return running_ids(reply)


def call_get_defs(keys, timeout):
    """-> (reply dict or None, why). Read-only; runs the client under Windows Python."""
    return _bridge("jawa/get_defs", {"defs": defs_param(keys)}, timeout)


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--has", action="append", required=True, metavar="DefType/defName[=TOKEN]")
    ap.add_argument("--needs", action="append", default=[], metavar="PACKAGEID",
                    help="the criterion's load holds this mod: UNMEASURED unless the RUNNING load has it")
    ap.add_argument("--without", action="append", default=[], metavar="PACKAGEID",
                    help="the criterion's load lacks this mod: UNMEASURED when the RUNNING load has it")
    ap.add_argument("--timeout", type=int, default=60)
    a = ap.parse_args(argv)
    try:
        claims = parse_claims(a.has)
    except ValueError as e:
        print("UNMEASURED: %s" % e)
        return UNMEASURED
    alias, running, pre = aliases(), None, []
    if a.needs or a.without:
        running = call_running_mods(a.timeout)
        code, pre = condition(a.needs, a.without, running, alias)
        if code is not None:
            print("\n".join(pre))
            print("VERDICT UNMEASURED")
            return code
    reply, why = call_get_defs(sorted({k for k, _ in claims}), a.timeout)
    if reply is None:
        print("UNMEASURED: %s" % why)
        return UNMEASURED
    try:
        owners = {}
        if isinstance(reply, dict) and isinstance(reply.get("defs"), list) and any(
                isinstance(d, dict) and d.get("found") is False for d in reply["defs"]):
            owners = with_aliases(def_owners(sorted({k for k, _ in claims})), alias)
            if owners and running is None:
                running = call_running_mods(a.timeout)
        code, lines = judge(claims, reply, owners, running)
        lines = pre + lines
    except Exception as e:      # an uncaught crash would exit 1, which the runner records as a FAIL
        print("UNMEASURED: the reply could not be judged: %s: %s" % (type(e).__name__, str(e)[:200]))
        return UNMEASURED
    print("\n".join(lines))
    print({PASS: "VERDICT PASS", FAIL: "VERDICT FAIL", UNMEASURED: "VERDICT UNMEASURED"}[code])
    return code


def safe_main(argv=None):
    """main(), where nothing may escape: an uncaught exception exits 1 and the runner would record it as a FAIL."""
    try:
        return main(argv)
    except SystemExit:
        raise
    except BaseException as e:
        sys.stdout.write("UNMEASURED: " + ascii("%s: %s" % (type(e).__name__, str(e)[:200])) + "\n")
        return UNMEASURED


if __name__ == "__main__":
    sys.exit(safe_main())

scripts.src/RimMandrake/Utils/northstar_driver/c:
#!/usr/bin/env python3
"""northstar_driver CLI.  LIVE work runs under Windows Python, repo-relative paths:

  python.exe src/RimMandrake/Utils/northstar_driver/cli.py preflight --mod Graffiti
  python.exe src/RimMandrake/Utils/northstar_driver/cli.py run --mod Graffiti --plan <plan.py> [--pipeline]
  python.exe src/RimMandrake/Utils/northstar_driver/cli.py run ... --config full [--list <ModsConfig>]   # full list
  python.exe src/RimMandrake/Utils/northstar_driver/cli.py needs-mods --mod Graffiti [--id <packageId>]  # tier-aware
  python.exe src/RimMandrake/Utils/northstar_driver/cli.py running-list [--list <ModsConfig>]  # FINAL verification

TIERS (PROOF_TIERS_WIDEN_SMALL_LIST_FIRST_ALWAYS, owner 2026-11-02: "small mod lists should always be the way to test
until a final verification pass on the whole huge mod list"): `needs-mods` is how a proof says which game it can run
on: exit 0 when the RUNNING game (jawa/running_mods) holds the mod, its About.xml modDependencies, Core and every DLC,
whatever else is loaded; exit 2 (UNMEASURED, "not in the running load") when it does not. `running-list` and
`run --config full` compare against the whole full list: they are the final verification (rimflow level GREEN-FULL),
never a small-tier proof; a running list holding under half the full list is another tier, exit 2, never a FAIL.
  python3    src/RimMandrake/Utils/northstar_driver/cli.py run --mock --plan <plan.py>   # offline
  python3    src/RimMandrake/Utils/northstar_driver/judge_cli.py <results.json>           # visual half, WSL

Suite bars (`shows=`) are visual: a state PASS reads UNMEASURED until judge_cli.py writes a verdict.

Never touches ModsConfig.xml (read-only fingerprint), never launches the game, never takes the
bridge lock (you hold it: `rimflow bridge who`). Output is JSON (LF) at --out, default
Transient/northstar/<Mod>_<utc>.json, shaped for modcheck: {mod, mode, preflight[], bars[], summary,
expected, all_green, timing, mod_hash}. A LIVE run is then recorded through
modcheck.status.record_run (`modcheck status` shows it); --no-record skips that. Exit 0 = ran and all_green, 1 = ran not green, 2 = refused (dirty site).
A suite plan runs one chain at a time and REWRITES --out after every chain with `partial: true` (chains_done,
chains_pending), so a killed run still leaves its finished rows; the final write sets `partial: false`.
--chains a,b runs only those chains, --skip-chains a,b drops them (a long-wait chain split into its own run);
a chain not run reads UNMEASURED 'chain not run', never absent.
"""
import argparse
import copy
import importlib.util
import json
import os
import sys
import time

_HERE = os.path.dirname(os.path.abspath(__file__))
_UTILS = os.path.dirname(_HERE)
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(_UTILS)))
for p in (_UTILS, os.path.join(_UTILS, "modcheck")):
    if p not in sys.path:
        sys.path.insert(0, p)

from northstar_driver import PASS, FAIL, UNMEASURED                       # noqa: E402
from northstar_driver import preflight as pf, bars as B                   # noqa: E402
from northstar_driver.session import FastSession                          # noqa: E402
from northstar_driver.transport import MockTransport, MockGame            # noqa: E402


def _rel(*parts):
    return os.path.join(ROOT, *parts)


def load_plan(path):
    spec = importlib.util.spec_from_file_location("ns_plan_" + os.path.basename(path)[:-3], path)
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m


def expected_bars(mod):
    """Must-show + cannot-show ids from the mod's walk, ONLY when VALIDATED (else binds nothing)."""
    try:
        import northstar
        w = northstar.find_walk(ROOT, mod)
        if not w:
            return [], "no walk"
        ns = northstar.parse(w)
        if ns["state"] != northstar.VALIDATED:
            return [], "walk is DRAFT (%s)" % ns["reason"]
        return list(ns["must_show"]) + list(ns["cannot_show"]), "VALIDATED walk %s" % os.path.basename(w)
    except Exception as ex:
        return [], "walk unreadable: %s" % ex


def _folded_into_composed(src_dir):
    try:
        import biomes_compose
        return os.path.basename(os.path.abspath(src_dir)) in biomes_compose.folded_sources(_rel("src"))
    except Exception:
        return False


def mod_dirs_for(mod):
    if not mod:
        return []
    import game_paths
    out = []
    for tier in ("RimMandrake", "RimStarWars", "RimUtinni"):
        d = _rel("src", tier, mod)
        if _folded_into_composed(d):
            continue            # deployed inside RimMandrake.Biomes; that composed deploy is gated by the mod's own preflight
        if os.path.isfile(os.path.join(d, "About", "About.xml")):
            # the deployed folder is named like the repo folder (deploy_custom_mods.py is the authority)
            out.append((d, os.path.join(game_paths.STEAM, "common", "RimWorld", "Mods", mod)))
    return out


def mock_config(ids):
    """Hermetic ModsConfig for mock runs -- the real one is never read or written."""
    import tempfile
    d = tempfile.mkdtemp(prefix="ns_mock_")
    p = os.path.join(d, "ModsConfig.xml")
    with open(p, "w") as f:
        f.write("<ModsConfigData><activeMods>%s</activeMods></ModsConfigData>" %
                "".join("<li>%s</li>" % i for i in ["ludeon.rimworld"] + list(ids)))
    return p


def running_list_for(args):
    """Full-list mode: the list file the RUNNING game must equal (--list, default FULL.LATEST); None otherwise."""
    if getattr(args, "config", "current") != "full":
        return None
    return getattr(args, "list", None) or pf.FULL_LATEST


def open_session(args, plan=None):
    if args.mock:
        game = MockGame(faults=[f for f in (args.fault or "").split(",") if f])
        game.ext = getattr(plan, "mock_extension", None)   # a plan may bring its own in-memory mod model
        return FastSession(transport=MockTransport(game), strict=False), game
    return FastSession(pipeline=args.pipeline, strict=False), None


def cmd_preflight(args):
    s, _ = open_session(args)
    with s:
        cs = pf.run_preflight(s, mod_dirs=[] if args.mock and not args.mod else mod_dirs_for(args.mod),
                              expect_ids=args.expect_id or (), need_god=args.god, rect=args.rect,
                              fix=args.fix, extra_tools=(),
                              config_path=mock_config(args.expect_id or ()) if args.mock else None,
                              running_list=running_list_for(args))
    ok, bad, unk = pf.verdict(cs, args.allow_unmeasured)
    for c in cs:
        print("%-11s %-24s %s" % (c.status, c.name, c.evidence))
    print("PREFLIGHT %s" % ("OK" if ok else "REFUSED: %d FAIL, %d UNMEASURED" % (len(bad), len(unk))))
    return 0 if ok else 2


def exit_code(status):
    """PASS 0, FAIL 1, UNMEASURED 2: a game of another tier is unmeasured, never a FAIL of the item."""
    return {PASS: 0, FAIL: 1}.get(status, 2)


def cmd_running_list(args):
    """READ-ONLY FINAL VERIFICATION: the RUNNING list (jawa/running_mods) against --list (default FULL.LATEST).
    Exit 0 iff identical, 1 differs, 2 unmeasured (no reply, or another tier is up)."""
    s, _ = open_session(args)
    with s:
        c = pf.check_running_list(s, getattr(args, "list", None) or pf.FULL_LATEST)
    print("%-11s %-24s %s" % (c.status, c.name, c.evidence))
    return exit_code(c.status)


def about_xml_for(mod):
    """The repo About.xml of mod folder `mod` (any tier, folded into the composed biomes or not)."""
    for tier in ("RimMandrake", "RimStarWars", "RimUtinni"):
        p = _rel("src", tier, mod, "About", "About.xml")
        if os.path.isfile(p):
            return p
    raise ValueError("no src/<tier>/%s/About/About.xml" % mod)


def needs_for(mods=(), ids=()):
    return pf.needed_ids([about_xml_for(m) for m in mods or ()], ids or ())


def cmd_needs_mods(args):
    """READ-ONLY, TIER-AWARE: exit 0 iff the RUNNING game holds what the proof needs; 2 when it does not."""
    try:
        need = needs_for(args.mod, args.id)
    except (OSError, ValueError) as ex:
        print("UNMEASURED  needed_mods              %s" % ex)
        return 2
    s, _ = open_session(args)
    with s:
        c = pf.check_needed_mods(s, need)
    print("%-11s %-24s %s" % (c.status, c.name, c.evidence))
    return exit_code(c.status)


def cmd_run(args):
    plan = load_plan(args.plan) if args.plan else None
    s, game = open_session(args, plan)
    mod = args.mod or (getattr(plan, "MOD", None) if plan else None) or "adhoc"
    exp, why = expected_bars(mod)
    mod_dir, start_hash = mod_hash_now(mod)
    doc = {"mod": mod, "mode": "mock" if args.mock else "live", "started_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
           "expected": exp, "expected_source": why, "bars": [], "preflight": [], "compat": [],
           "config": args.config, "config_list": running_list_for(args)}
    out = args.out or _rel("Transient", "northstar", "%s%s_%s.json" % (
        mod, "_full" if args.config == "full" else "", time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())))
    with s:
        cs = pf.run_preflight(s, mod_dirs=[] if args.mock else mod_dirs_for(mod),
                              expect_ids=getattr(plan, "EXPECT_MODS", ()) or args.expect_id or (),
                              need_god=args.god or getattr(plan, "NEED_GOD", False),
                              rect=args.rect or getattr(plan, "RECT", None), fix=args.fix,
                              config_path=mock_config(getattr(plan, "EXPECT_MODS", ()) or args.expect_id or ()) if args.mock else None,
                              running_list=running_list_for(args))
        if args.config == "full" and getattr(plan, "full_list_differences", None):
            try:
                doc["full_list_differences"] = plan.full_list_differences(running_list_for(args))
            except Exception as ex:   # noqa: BLE001 - the sheet section says it could not be built; never silent
                doc["full_list_differences"] = {"error": "%s: %s" % (type(ex).__name__, ex)}
        # mod-supplied site check: plan.preflight(s) -> [failed precondition, ...] (plan 3.13)
        if getattr(plan, "preflight", None) and not args.mock_skip_site:
            try:
                for msg in call_plan_preflight(plan, s, _csv(args.chains)) or []:
                    cs.append(pf.Check("site:" + msg.split(":")[0][:40], FAIL, msg))
            except Exception as ex:
                cs.append(pf.Check("site_preflight", UNMEASURED, "%s: %s" % (type(ex).__name__, ex)))
        # cannot-show enforcement (plan 6.10): a VALIDATED walk's cannot-show id that no component claims
        if getattr(plan, "USE_SUITE", False):
            miss = unclaimed_cannot_show(mod)
            if miss:
                cs.append(pf.Check("cannot_show_claimed", FAIL,
                                   "cannot-show id(s) no component claims via shows=: %s" % miss))
        doc["preflight"] = [c.as_dict() for c in cs]
        ok, bad, unk = pf.verdict(cs, args.allow_unmeasured)
        if not ok:
            doc.update(refused="; ".join("%s %s" % (c.name, c.status) for c in bad + unk),
                       all_green=False, summary=B.summarize([]))
            code = 2
        else:
            wanted = [b for b in B.REGISTRY.values() if b.mod in (None, mod)]
            rows = [B.run_bar(b, s) for b in wanted]
            if getattr(plan, "USE_SUITE", False):
                rows += _suite_rows(s, mod, exp, doc, only=_csv(args.chains), skip=_csv(args.skip_chains),
                                    progress=lambda d: B.write_results(out, d), pre_rows=rows)
            doc["bars"] = rows
            doc["summary"] = B.summarize(rows)
            doc["all_green"] = run_all_green(rows, exp)
            if args.mock and getattr(plan, "MOCK_LIVE_ONLY", None):
                # a row the plan DECLARES unmeasurable offline (it needs a live map) reads UNMEASURED in every mock run;
                # a mock run is judged without those rows and names them. Only UNMEASURED is set aside: a FAIL fails.
                lo = set(plan.MOCK_LIVE_ONLY)
                skip = [r["id"] for r in rows if r["id"] in lo and r["status"] == UNMEASURED]
                if skip:
                    doc["mock_live_only_unmeasured"] = skip
                    doc["all_green"] = run_all_green([r for r in rows if r["id"] not in skip], exp)
                    print("mock: %d live-only row(s) set aside, UNMEASURED offline by declaration: %s"
                          % (len(skip), ", ".join(skip)))
            code = 0 if doc["all_green"] else 1
        doc["timing"] = s.timing
    doc["partial"] = False
    if mod_dir:
        doc["mod_hash"] = start_hash
    B.write_results(out, doc)
    if not args.mock and not args.no_record:
        _entry, msg = record_result(doc, mod, out, start_hash, mod_dir)
        print(msg)
    print("%s: %s  PASS=%s FAIL=%s UNMEASURED=%s  calls=%d mean=%.3fms  -> %s" % (
        mod, "REFUSED" if code == 2 else ("GREEN" if code == 0 else "NOT GREEN"),
        doc["summary"][PASS], doc["summary"][FAIL], doc["summary"][UNMEASURED],
        doc["timing"]["n"], doc["timing"]["mean_ms"], out))
    return code


def mod_hash_now(mod):
    """(mod_dir, modcheck.status.mod_hash) for a repo mod, or (None, None) for an ad-hoc run."""
    try:
        import runner
        import status
        d = runner.find_mod_dir(mod)
        return d, status.mod_hash(d)
    except Exception:
        return None, None


def record_result(doc, mod, out, start_hash, mod_dir, _record=None):
    """Record a finished run through modcheck.status.record_run (the only writer of
    modcheck_status.json), as runner.py does after `modcheck run`. Returns (entry|None, message).
    Not recorded, by design: a mock run (cmd_run never calls this for one), a preflight refusal
    (the SITE was refused, the mod never ran), a run with no rows, an ad-hoc mod with no repo
    folder, and a run during which the mod's files changed (its verdict would describe neither
    hash). The verdict is the run's own all_green: any FAIL or UNMEASURED row is not GREEN."""
    import northstar
    import status
    if not mod_dir or not start_hash:
        return None, "not recorded: %s has no repo mod folder" % mod
    if doc.get("refused"):
        return None, "not recorded: refused at preflight (%s) -- a site verdict, not the mod's" % doc["refused"][:160]
    rows = doc.get("bars") or []
    if not rows:
        return None, "not recorded: the run produced no rows"
    now = status.mod_hash(mod_dir)
    if now != start_hash:
        return None, "not recorded: %s changed during the run (%s -> %s)" % (mod, start_hash[:12], now[:12])
    rel = result_path(out)
    by = {}
    for r in rows:
        by.setdefault(r["status"], []).append(r["id"])
    extra = {"components": {"counts": {k: len(v) for k, v in by.items()},
                            "not_ok": [i for k, v in by.items() if k != PASS for i in v]},
             "bars": {r["id"]: r["status"] for r in rows},
             "source": {"verb": "northstar_driver run", "result": rel, "mode": doc.get("mode"),
                        "started": doc.get("started_utc"), "expected_source": doc.get("expected_source"),
                        "config": doc.get("config") or "current"},
             "config": doc.get("config") or "current"}
    if doc.get("compat"):
        extra["compat"] = {r["id"]: r["status"] for r in doc["compat"]}
    run_id = "%s/northstar_driver[%s]@%s" % (mod, doc.get("config") or "current", os.path.basename(out))
    entry = (_record or status.record_run)(mod, mod_dir, run_id, bool(doc.get("all_green")),
                                           walk=northstar.find_walk(ROOT, mod), extra=extra)
    return entry, "recorded %s: %s at %s (%s)" % (mod, entry["status"], entry["hash"][:12], run_id)


def result_path(out, root=None):
    """`out` relative to the repo, or absolute when it lies on another drive: Windows relpath raises ValueError for a
    D:\\ --out under a \\\\wsl.localhost repo (live 2026-11-03, after the run had already been written)."""
    try:
        return os.path.relpath(os.path.abspath(out), root or ROOT).replace(os.sep, "/")
    except ValueError:
        return os.path.abspath(out).replace(os.sep, "/")


def unclaimed_cannot_show(mod):
    """Cannot-show ids of a VALIDATED walk that no component's `shows=` claims. [] when no walk."""
    try:
        import northstar
        import runner
        w = northstar.find_walk(ROOT, mod)
        ns = northstar.parse(w) if w else None
        if not ns or ns["state"] != northstar.VALIDATED:
            return []
        claimed = set()
        for c in runner.load_validation(runner.find_mod_dir(mod)).components_declared():
            claimed.update(c.get("shows") or ())
        return [i for i in ns["cannot_show"] if i not in claimed]
    except Exception as ex:
        return ["(unreadable: %s)" % ex]


def _csv(v):
    return [x.strip() for x in (v or "").split(",") if x.strip()] or None


def call_plan_preflight(plan, s, chains):
    """plan.preflight(s), or plan.preflight(s, chains=[...]) when the plan accepts it: a site precondition only some
    chains need (ExplosiveGrowth's plant temperature) may then be skipped for a --chains run that needs none of them.
    chains None = every chain."""
    import inspect
    try:
        takes = "chains" in inspect.signature(plan.preflight).parameters
    except (TypeError, ValueError):
        takes = False
    return plan.preflight(s, chains=chains) if takes else plan.preflight(s)


def select_chains(chains, only=None, skip=None):
    """(run, skipped) from the suite's [(name, fn)] in suite order. `only` keeps just those names, `skip` drops
    those names; a name that matches no chain raises, so a typo can never silently run (or skip) nothing."""
    names = [n for n, _ in chains]
    unknown = [n for n in (only or []) + (skip or []) if n not in names]
    if unknown:
        raise SystemExit("unknown chain name(s) %s; the suite has: %s" % (unknown, ", ".join(names)))
    run, skipped = [], []
    for n, fn in chains:
        (skipped if (only and n not in only) or (skip and n in skip) else run).append((n, fn))
    return run, skipped


def skipped_chain_records(suite, skipped, why):
    """One UNMEASURED component per DECLARED component of each skipped chain (the offline declaration probe), so
    its bars read 'not run: <why>' rather than 'no component claims' and a split run is never mistaken for green."""
    out = []
    for name, fn in skipped:
        sub = copy.copy(suite)
        sub.chains = [(name, fn)]
        try:
            decl = sub.components_declared()
        except Exception as ex:   # noqa: BLE001 - a declaration that cannot be probed still records the skip
            decl = [{"shows": [], "error": "%s: %s" % (type(ex).__name__, ex)}]
        out.append({"name": name, "skipped": True, "components": [
            {"name": "skipped#%d" % i, "verdict": UNMEASURED, "shows": list(d.get("shows") or ()),
             "toggle": d.get("toggle"), "detail": "UNMEASURED: chain not run (%s)" % why}
            for i, d in enumerate(decl or [{"shows": []}])]})
    return out


def _rows_from(chains, expected, texts):
    """Compat components are partitioned out FIRST: a `compat_*` row never reaches the bar rollup, even if it
    (wrongly) claims a `shows=` bar."""
    own = [dict(ch, components=[c for c in ch["components"] if not is_compat(c)]) for ch in chains]
    return mark_visual(B.rollup_components(own, expected), texts) + functional_rows(own)


COMPAT_PREFIX = "compat_"


def is_compat(c):
    """A compatibility component (Graffiti plan: foreign mark defs of SacredGraffiti / GraffitiImperial on the
    full list): named `compat_*` (the prefix alone decides; a `shows=` claim on one is ignored). Reported in
    doc["compat"], never in the mod's bars, its summary or its verdict."""
    return str(c.get("name", "")).startswith(COMPAT_PREFIX)


def compat_rows(chains):
    out = []
    for ch in chains:
        for c in ch["components"]:
            if not is_compat(c):
                continue
            v = str(c.get("verdict", ""))
            st = PASS if v.startswith("PASS") else (FAIL if v == "FAIL" else UNMEASURED)
            out.append({"id": "%s.%s" % (ch.get("name"), c.get("name")), "status": st, "compat": True,
                        "evidence": str(c.get("detail") or v)})
    return out


def _suite_rows(s, mod, expected, doc, only=None, skip=None, progress=None, pre_rows=(), suite=None):
    """Run the suite ONE CHAIN AT A TIME and hand `progress` a partial results doc after every chain, so a run
    killed mid-suite (2026-10-12: a 50-min shell timeout inside embergrass_regrow left no JSON at all) still
    leaves every finished row on disk. Each chain gets runner.run_suite on a one-chain copy of the suite with the
    same anchor, which is what one whole-suite call did per chain (mod=None, situational off)."""
    import runner
    suite = suite or runner.load_validation(runner.find_mod_dir(mod))
    run, skipped = select_chains(suite.chains, only, skip)
    why = "--chains %s" % ",".join(only) if only else ""
    why = (why + " " if why else "") + ("--skip-chains %s" % ",".join(skip) if skip else "")
    skipped_out = skipped_chain_records(suite, skipped, why.strip())
    doc["chains_selected"] = [n for n, _ in run]
    doc["chains_skipped"] = [n for n, _ in skipped]
    doc["bar_text"], doc["bar_text_source"] = bar_text(mod)
    anchor = runner._default_anchor(s)
    done = []
    for i, (name, fn) in enumerate(run):
        sub = copy.copy(suite)
        sub.chains = [(name, fn)]
        res = runner.run_suite(sub, s, anchor=anchor, mod=None)   # visual half: judge_cli.py, after the run
        done.extend(res["chains"])
        if progress is not None:
            part = dict(doc, partial=True, chains_done=[c.get("name") for c in done],
                        chains_pending=[n for n, _ in run[i + 1:]], components=component_records(done))
            part["bars"] = list(pre_rows) + _rows_from(done + skipped_out, expected, doc["bar_text"])
            part["summary"] = B.summarize(part["bars"])
            part["compat"] = compat_rows(done)
            part["all_green"] = False
            progress(part)
    chains = done + skipped_out
    for ch in chains:
        for c in ch["components"]:
            if not str(c.get("verdict", "")).startswith("PASS"):
                print("component %s/%s: %s" % (ch.get("name"), c.get("name"),
                                               json.dumps({k: v for k, v in c.items() if k != "name"}, default=str)[:600]))
    doc["components"] = component_records(chains)
    doc["compat"] = compat_rows(chains)
    return _rows_from(chains, expected, doc["bar_text"])


def functional_rows(chains):
    """One row per suite component that claims no `shows=` bar: the mod's functional script
    (debug_process.md section 2). Without these a suite FAIL never reached the summary or the verdict,
    and a mod with no north star could never be GREEN (zero rows). Status is the component's own."""
    out = []
    for ch in chains:
        for c in ch["components"]:
            if c.get("shows") or is_compat(c):
                continue
            v = str(c.get("verdict", ""))
            st = PASS if v.startswith("PASS") else (FAIL if v == "FAIL" else UNMEASURED)
            out.append({"id": "%s.%s" % (ch.get("name"), c.get("name")), "status": st, "functional": True,
                        "evidence": str(c.get("detail") or v)[:300],
                        "evidenceFull": str(c.get("detail") or v)})
    return out


def run_all_green(rows, expected):
    """Every expected north-star bar PASS (bars.all_green) AND every functional row PASS."""
    return B.all_green(rows, expected or None) and all(r["status"] == PASS for r in rows if r.get("functional"))


def to_wsl(p):
    """`C:\\x\\y.png` -> `/mnt/c/x/y.png`; a POSIX path is returned unchanged."""
    p = str(p or "")
    if len(p) > 2 and p[1] == ":" and p[0].isalpha():
        return "/mnt/%s/%s" % (p[0].lower(), p[2:].replace("\\", "/").lstrip("/"))
    return p


def to_win(p):
    """`/mnt/c/x/y.png` -> `C:\\x\\y.png`; a Windows path is returned unchanged."""
    p = str(p or "")
    if p.startswith("/mnt/") and len(p) > 6 and p[6] == "/":
        return "%s:\\%s" % (p[5].upper(), p[7:].replace("/", "\\"))
    return p


def component_records(chains):
    """Every component, with each screenshot as {path (as the bridge returned it), win, wsl}, so the
    WSL-side judge can find the image without re-deriving anything."""
    out = []
    for ch in chains:
        for c in ch["components"]:
            # evidenceFull: a component whose `shows=` bar is not a driver bar (every pyre_* north-star bar) reaches the
            # result JSON ONLY here; without it a FAIL's reason survived only as a 600-char console line (2026-10-12c).
            out.append({"chain": ch.get("name"), "name": c.get("name"), "verdict": c.get("verdict"),
                        "evidenceFull": str(c.get("detail") or c.get("verdict") or ""),
                        "shows": list(c.get("shows") or ()),
                        "screenshots": [{"path": p, "win": to_win(p), "wsl": to_wsl(p)}
                                        for p in (c.get("screenshots") or ()) if p]})
    return out


def bar_text(mod):
    """{bar id: {polarity, text}} from the VALIDATED walk -- the narrow question the judge asks."""
    try:
        import northstar
        w = northstar.find_walk(ROOT, mod)
        ns = northstar.parse(w) if w else None
        if not ns or ns["state"] != northstar.VALIDATED:
            return {}, "no VALIDATED walk"
        out = {i: {"polarity": "must", "text": ns["must_show_text"].get(i, "")} for i in ns["must_show"]}
        out.update({i: {"polarity": "cannot", "text": ns["cannot_show_text"].get(i, "")}
                    for i in ns["cannot_show"]})
        return out, "%s (hash %s)" % (os.path.relpath(w, ROOT), ns.get("recorded_hash", ""))
    except Exception as ex:
        return {}, "walk unreadable: %s" % ex


def mark_visual(rows, texts):
    """Every `shows=` bar is judged on its screenshots, so state alone cannot PASS it: a state PASS
    reads UNMEASURED until judge_cli.py writes a verdict. The state result is kept in `state_status`."""
    for r in rows:
        r["visual"] = True
        r["polarity"] = (texts.get(r["id"]) or {}).get("polarity", "must")
        r["state_status"], r["state_evidence"] = r["status"], r["evidence"]
        if r["status"] == PASS:
            r["status"] = UNMEASURED
            r["evidence"] = "visual bar: state PASS, not yet judged (run judge_cli.py) [%s]" % r["evidence"]
    return rows


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = ap.add_subparsers(dest="cmd", required=True)
    for name, fn in (("preflight", cmd_preflight), ("run", cmd_run)):
        p = sub.add_parser(name)
        p.set_defaults(fn=fn)
        p.add_argument("--mod")
        p.add_argument("--mock", action="store_true", help="in-memory game; no bridge")
        p.add_argument("--fault", help="mock faults, comma list: zombie,modal,pause_lies,dev_off,god_off,dirty,unfrozen")
        p.add_argument("--god", action="store_true", help="require god mode")
        p.add_argument("--rect", help="x,z,w,h test area that must be empty")
        p.add_argument("--fix", action="store_true", help="pause / enable god, each proved by re-read")
        p.add_argument("--expect-id", action="append", help="packageId that must be active (repeat)")
        p.add_argument("--allow-unmeasured", action="store_true")
        p.add_argument("--mock-skip-site", action="store_true", help="skip plan.preflight (offline selftests)")
        p.add_argument("--pipeline", action="store_true", help="pipelined call_many (correct but no faster: 1 reply/frame, pipecheck.py 2026-10-21)")
        p.add_argument("--config", choices=("current", "full"), default="current",
                       help="full = full-list mode (plan 6.8): no list swap; the RUNNING list (jawa/running_mods) must "
                            "equal --list (default FULL.LATEST) or the run refuses; recorded with config 'full'")
        p.add_argument("--list", help="full-list mode: the ModsConfig-shaped file the running list must equal")
        if name == "run":
            p.add_argument("--plan", help="python plan module registering @bar functions")
            p.add_argument("--out")
            p.add_argument("--no-record", action="store_true",
                           help="live run only: do not record it in modcheck_status.json")
            p.add_argument("--chains", help="suite plans: run ONLY these chains (comma list); the rest read "
                                            "UNMEASURED 'chain not run'")
            p.add_argument("--skip-chains", help="suite plans: skip these chains (comma list), e.g. a long-wait "
                                                 "chain split into its own run")
    p = sub.add_parser("running-list", help="READ-ONLY FINAL VERIFICATION: running list vs --list (default "
                                            "FULL.LATEST); exit 0 equal, 1 differs, 2 unmeasured or another tier")
    p.set_defaults(fn=cmd_running_list, mock=False, pipeline=False)
    p.add_argument("--list")
    p = sub.add_parser("needs-mods", help="READ-ONLY, tier-aware: exit 0 iff the running game holds each --mod (its "
                                          "About.xml packageId + modDependencies), each --id, Core and every DLC; 2 if not")
    p.set_defaults(fn=cmd_needs_mods, mock=False, pipeline=False)
    p.add_argument("--mod", action="append", help="repo mod folder, e.g. Graffiti (repeat)")
    p.add_argument("--id", action="append", help="extra packageId the proof needs (repeat)")
    a = ap.parse_args(argv)
    return a.fn(a)


if __name__ == "__main__":
    sys.exit(main())

