#!/usr/bin/env python3
"""Live proof of STILLSAND_SAND_SWIM_REMAINDER_1 §7: the sand-swim kit on a Stillsand quicktest map, each clause a state
read through validation.py's sandswim chain (never a screenshot hunt).

  A1  submerged and surfaced: a vekka is RM_SandSubmerged on Sand and not on Gravel; struck, it surfaces, and
      re-submerges after its window (sandswim.vekka_submerges_on_sand, sandswim.vekka_surfaces_when_struck)
  A2  the take: a kill on sand lays the RM_Filth_DisturbedSand funnel and sends the 'Taken under' letter
      (sandswim.vekka_take_leaves_funnel)
  A3  mech immunity: a submerged vekka ordered six times onto a Mech_Militor leaves it unhurt
      (sandswim.vekka_spares_a_mech)
  A4  a catch: painted RM_DeepSand is a water body whose catch list holds RM_DuneCrawler, and one Fish job there
      lands a Stillsand catch (sandswim.stillsand_catch)
  A5  the wake trough: a submerged vekka's 20-cell swim raises its own count in RM_TrackGridDiag.WakeTroughReport
      (sandswim.vekka_wake_trough_record)

    python3 src/RimMandrake/Stillsand/prove_sandswim.py --clause A1|A2|A3|A4|A5
    python3 src/RimMandrake/Stillsand/prove_sandswim.py --selftest        # offline, against selftest_stillsand's fake

Exit 0 = the clause holds, 1 = it does not, 2 = UNMEASURED (no game, a tool missing, an arm that could not be read).
The clauses share one run of the site, sandswim and log chains, cached 30 min beside validation.py's hash
(agent storage scratch/prove_sandswim.json).
"""
import argparse
import hashlib
import json
import os
import sys
import time

HERE = os.path.dirname(os.path.abspath(__file__))
UTILS = os.path.join(os.path.dirname(HERE), "Utils")
for _p in (UTILS, os.path.join(UTILS, "modcheck")):
    if _p not in sys.path:
        sys.path.insert(0, _p)

CHAINS = ("site", "sandswim", "log")
CLAUSES = {
    "A1": ("sandswim.vekka_submerges_on_sand", "sandswim.vekka_surfaces_when_struck"),
    "A2": ("sandswim.vekka_take_leaves_funnel",),
    "A3": ("sandswim.vekka_spares_a_mech",),
    "A4": ("sandswim.stillsand_catch",),
    "A5": ("sandswim.vekka_wake_trough_record",),
}
CACHE_S = 30 * 60


def _load_validation():
    import importlib.util
    spec = importlib.util.spec_from_file_location("stillsand_validation", os.path.join(HERE, "validation.py"))
    v = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(v)
    return v


def run_chains(V, session, anchor):
    """{chain.component: [verdict, detail]} for CHAINS."""
    from suite import TestContext
    V._STATE.clear()
    out = {}
    for name, fn in V.suite.chains:
        if name not in CHAINS:
            continue
        t = TestContext(session, anchor=anchor)
        try:
            fn(t)
        except Exception as ex:
            out[name + ".<CRASH>"] = ["CRASH", "%s: %s" % (type(ex).__name__, ex)]
            continue
        for c in t.components:
            out["%s.%s" % (name, c.name)] = [c.verdict, c.detail]
    return out


def judge(res, clause):
    keys = CLAUSES[clause]
    crash = dict((k, v[1]) for k, v in res.items() if k.endswith(".<CRASH>") and k.split(".")[0] in ("site", "sandswim"))
    if crash:
        return 2, "UNMEASURED: a chain crashed: %s" % crash
    miss = [k for k in keys if k not in res]
    if miss:
        return 2, "UNMEASURED: components missing from the run: %s" % miss
    red = dict((k, res[k]) for k in keys if res[k][0] in ("FAIL", "CRASH"))
    if red:
        return 1, "%s fails: %s" % (clause, red)
    if any(res[k][0] != "PASS" for k in keys):
        return 2, "UNMEASURED: %s" % dict((k, res[k]) for k in keys if res[k][0] != "PASS")
    return 0, "%s holds: %s PASS" % (clause, ", ".join(k.split(".")[1] for k in keys))


def _vhash():
    h = hashlib.sha256()
    for f in ("validation.py", "prove_sandswim.py"):
        with open(os.path.join(HERE, f), "rb") as fh:
            h.update(fh.read())
    return h.hexdigest()[:16]


def live_result():
    import rmpaths
    path = str(rmpaths.rm_path("scratch", "prove_sandswim.json"))
    try:
        with open(path, encoding="utf-8") as fh:
            c = json.load(fh)
        if c.get("vhash") == _vhash() and time.time() - c.get("at", 0) < CACHE_S:
            print("[prove] reusing the run of %s (%s)" % (time.ctime(c["at"]), path), file=sys.stderr)
            return c["res"]
    except (OSError, ValueError):
        pass
    V = _load_validation()
    import runner
    from rimdrive import Session
    runner.ensure_playing_map()
    with Session(lock=None, focus=False) as s:
        res = run_chains(V, s, runner._default_anchor(s))
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        json.dump({"vhash": _vhash(), "at": time.time(), "res": res}, fh, indent=1, default=str)
    return res


def selftest():
    """Every clause reads 0 on the healthy fake, 1 when its own arm is broken, 2 on a missing or crashed run."""
    import selftest_stillsand as S
    bad = []

    def run(broken=()):
        S.V._STATE.clear()
        return run_chains(S.V, S.Fake(broken), (125, 125))

    healthy = run()
    for c in sorted(CLAUSES):
        got = judge(healthy, c)
        if got[0] != 0:
            bad.append("healthy %s: %s" % (c, got[1]))
    breaks = {"A1": ("no_surface", "submerge_on_rock"), "A2": ("no_funnel",), "A3": ("mech_hurt",),
              "A4": ("no_catch", "wrong_fish"), "A5": ("no_trough",)}
    for c, bs in sorted(breaks.items()):
        for b in bs:
            res = run([b])
            if judge(res, c)[0] != 1:
                bad.append("break %s: %s did not read 1: %s" % (b, c, judge(res, c)[1]))
            for other in CLAUSES:
                if other != c and other not in [k for k, v in breaks.items() if b in v] and judge(res, other)[0] == 1:
                    bad.append("break %s also turned %s red" % (b, other))
    res = run(["no_submerge"])
    if judge(res, "A5")[0] != 2 or judge(res, "A3")[0] != 2:
        bad.append("a vekka that never submerges must leave A3/A5 UNMEASURED, not red or green")
    if judge({}, "A4")[0] != 2 or judge({"sandswim.<CRASH>": ["CRASH", "x"]}, "A1")[0] != 2:
        bad.append("a missing or crashed run did not read 2")
    for b in bad:
        print("  BAD:", b)
    print("prove_sandswim selftest: %d clauses, %s" % (len(CLAUSES), "FAIL" if bad else "ok"))
    return 1 if bad else 0


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    g = ap.add_mutually_exclusive_group(required=True)
    g.add_argument("--clause", choices=sorted(CLAUSES))
    g.add_argument("--selftest", action="store_true")
    a = ap.parse_args(argv)
    if a.selftest:
        err, sys.stderr = sys.stderr, open(os.devnull, "w")
        try:
            return selftest()
        finally:
            sys.stderr = err
    try:
        res = live_result()
    except Exception as ex:
        print("UNMEASURED: %s: %s" % (type(ex).__name__, ex))
        return 2
    code, line = judge(res, a.clause)
    print(line)
    return code


if __name__ == "__main__":
    sys.exit(main())

scripts.src/RimMandrake/Utils/northstar_driver/c:
#!/usr/bin/env python3
"""northstar_driver CLI.  LIVE work runs under Windows Python, repo-relative paths:

  python.exe src/RimMandrake/Utils/northstar_driver/cli.py preflight --mod Graffiti
  python.exe src/RimMandrake/Utils/northstar_driver/cli.py run --mod Graffiti --plan <plan.py> [--pipeline]
  python.exe src/RimMandrake/Utils/northstar_driver/cli.py run ... --config full [--list <ModsConfig>]   # full list
  python.exe src/RimMandrake/Utils/northstar_driver/cli.py needs-mods --mod Graffiti [--id <packageId>]  # tier-aware
  python.exe src/RimMandrake/Utils/northstar_driver/cli.py running-list [--list <ModsConfig>]  # FINAL verification

TIERS (PROOF_TIERS_WIDEN_SMALL_LIST_FIRST_ALWAYS, owner 2026-11-02: "small mod lists should always be the way to test
until a final verification pass on the whole huge mod list"): `needs-mods` is how a proof says which game it can run
on: exit 0 when the RUNNING game (jawa/running_mods) holds the mod, its About.xml modDependencies, Core and every DLC,
whatever else is loaded; exit 2 (UNMEASURED, "not in the running load") when it does not. `running-list` and
`run --config full` compare against the whole full list: they are the final verification (rimflow level GREEN-FULL),
never a small-tier proof; a running list holding under half the full list is another tier, exit 2, never a FAIL.
  python3    src/RimMandrake/Utils/northstar_driver/cli.py run --mock --plan <plan.py>   # offline
  python3    src/RimMandrake/Utils/northstar_driver/judge_cli.py <results.json>           # visual half, WSL

Suite bars (`shows=`) are visual: a state PASS reads UNMEASURED until judge_cli.py writes a verdict.

Never touches ModsConfig.xml (read-only fingerprint), never launches the game, never takes the
bridge lock (you hold it: `rimflow bridge who`). Output is JSON (LF) at --out, default
Transient/northstar/<Mod>_<utc>.json, shaped for modcheck: {mod, mode, preflight[], bars[], summary,
expected, all_green, timing, mod_hash}. A LIVE run is then recorded through
modcheck.status.record_run (`modcheck status` shows it); --no-record skips that. Exit 0 = ran and all_green, 1 = ran not green, 2 = refused (dirty site).
A suite plan runs one chain at a time and REWRITES --out after every chain with `partial: true` (chains_done,
chains_pending), so a killed run still leaves its finished rows; the final write sets `partial: false`.
--chains a,b runs only those chains, --skip-chains a,b drops them (a long-wait chain split into its own run);
a chain not run reads UNMEASURED 'chain not run', never absent.
"""
import argparse
import copy
import importlib.util
import json
import os
import sys
import time

_HERE = os.path.dirname(os.path.abspath(__file__))
_UTILS = os.path.dirname(_HERE)
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(_UTILS)))
for p in (_UTILS, os.path.join(_UTILS, "modcheck")):
    if p not in sys.path:
        sys.path.insert(0, p)

from northstar_driver import PASS, FAIL, UNMEASURED                       # noqa: E402
from northstar_driver import preflight as pf, bars as B                   # noqa: E402
from northstar_driver.session import FastSession                          # noqa: E402
from northstar_driver.transport import MockTransport, MockGame            # noqa: E402


def _rel(*parts):
    return os.path.join(ROOT, *parts)


def load_plan(path):
    spec = importlib.util.spec_from_file_location("ns_plan_" + os.path.basename(path)[:-3], path)
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m


def expected_bars(mod):
    """Must-show + cannot-show ids from the mod's walk, ONLY when VALIDATED (else binds nothing)."""
    try:
        import northstar
        w = northstar.find_walk(ROOT, mod)
        if not w:
            return [], "no walk"
        ns = northstar.parse(w)
        if ns["state"] != northstar.VALIDATED:
            return [], "walk is DRAFT (%s)" % ns["reason"]
        return list(ns["must_show"]) + list(ns["cannot_show"]), "VALIDATED walk %s" % os.path.basename(w)
    except Exception as ex:
        return [], "walk unreadable: %s" % ex


def _folded_into_composed(src_dir):
    try:
        import biomes_compose
        return os.path.basename(os.path.abspath(src_dir)) in biomes_compose.folded_sources(_rel("src"))
    except Exception:
        return False


def mod_dirs_for(mod):
    if not mod:
        return []
    import game_paths
    out = []
    for tier in ("RimMandrake", "RimStarWars", "RimUtinni"):
        d = _rel("src", tier, mod)
        if _folded_into_composed(d):
            continue            # deployed inside RimMandrake.Biomes; that composed deploy is gated by the mod's own preflight
        if os.path.isfile(os.path.join(d, "About", "About.xml")):
            # the deployed folder is named like the repo folder (deploy_custom_mods.py is the authority)
            out.append((d, os.path.join(game_paths.STEAM, "common", "RimWorld", "Mods", mod)))
    return out


def mock_config(ids):
    """Hermetic ModsConfig for mock runs -- the real one is never read or written."""
    import tempfile
    d = tempfile.mkdtemp(prefix="ns_mock_")
    p = os.path.join(d, "ModsConfig.xml")
    with open(p, "w") as f:
        f.write("<ModsConfigData><activeMods>%s</activeMods></ModsConfigData>" %
                "".join("<li>%s</li>" % i for i in ["ludeon.rimworld"] + list(ids)))
    return p


def running_list_for(args):
    """Full-list mode: the list file the RUNNING game must equal (--list, default FULL.LATEST); None otherwise."""
    if getattr(args, "config", "current") != "full":
        return None
    return getattr(args, "list", None) or pf.FULL_LATEST


def open_session(args, plan=None):
    if args.mock:
        game = MockGame(faults=[f for f in (args.fault or "").split(",") if f])
        game.ext = getattr(plan, "mock_extension", None)   # a plan may bring its own in-memory mod model
        return FastSession(transport=MockTransport(game), strict=False), game
    return FastSession(pipeline=args.pipeline, strict=False), None


def cmd_preflight(args):
    s, _ = open_session(args)
    with s:
        cs = pf.run_preflight(s, mod_dirs=[] if args.mock and not args.mod else mod_dirs_for(args.mod),
                              expect_ids=args.expect_id or (), need_god=args.god, rect=args.rect,
                              fix=args.fix, extra_tools=(),
                              config_path=mock_config(args.expect_id or ()) if args.mock else None,
                              running_list=running_list_for(args))
    ok, bad, unk = pf.verdict(cs, args.allow_unmeasured)
    for c in cs:
        print("%-11s %-24s %s" % (c.status, c.name, c.evidence))
    print("PREFLIGHT %s" % ("OK" if ok else "REFUSED: %d FAIL, %d UNMEASURED" % (len(bad), len(unk))))
    return 0 if ok else 2


def exit_code(status):
    """PASS 0, FAIL 1, UNMEASURED 2: a game of another tier is unmeasured, never a FAIL of the item."""
    return {PASS: 0, FAIL: 1}.get(status, 2)


def cmd_running_list(args):
    """READ-ONLY FINAL VERIFICATION: the RUNNING list (jawa/running_mods) against --list (default FULL.LATEST).
    Exit 0 iff identical, 1 differs, 2 unmeasured (no reply, or another tier is up)."""
    s, _ = open_session(args)
    with s:
        c = pf.check_running_list(s, getattr(args, "list", None) or pf.FULL_LATEST)
    print("%-11s %-24s %s" % (c.status, c.name, c.evidence))
    return exit_code(c.status)


def about_xml_for(mod):
    """The repo About.xml of mod folder `mod` (any tier, folded into the composed biomes or not)."""
    for tier in ("RimMandrake", "RimStarWars", "RimUtinni"):
        p = _rel("src", tier, mod, "About", "About.xml")
        if os.path.isfile(p):
            return p
    raise ValueError("no src/<tier>/%s/About/About.xml" % mod)


def needs_for(mods=(), ids=()):
    return pf.needed_ids([about_xml_for(m) for m in mods or ()], ids or ())


def cmd_needs_mods(args):
    """READ-ONLY, TIER-AWARE: exit 0 iff the RUNNING game holds what the proof needs; 2 when it does not."""
    try:
        need = needs_for(args.mod, args.id)
    except (OSError, ValueError) as ex:
        print("UNMEASURED  needed_mods              %s" % ex)
        return 2
    s, _ = open_session(args)
    with s:
        c = pf.check_needed_mods(s, need)
    print("%-11s %-24s %s" % (c.status, c.name, c.evidence))
    return exit_code(c.status)


def cmd_run(args):
    plan = load_plan(args.plan) if args.plan else None
    s, game = open_session(args, plan)
    mod = args.mod or (getattr(plan, "MOD", None) if plan else None) or "adhoc"
    exp, why = expected_bars(mod)
    mod_dir, start_hash = mod_hash_now(mod)
    doc = {"mod": mod, "mode": "mock" if args.mock else "live", "started_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
           "expected": exp, "expected_source": why, "bars": [], "preflight": [], "compat": [],
           "config": args.config, "config_list": running_list_for(args)}
    out = args.out or _rel("Transient", "northstar", "%s%s_%s.json" % (
        mod, "_full" if args.config == "full" else "", time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())))
    with s:
        cs = pf.run_preflight(s, mod_dirs=[] if args.mock else mod_dirs_for(mod),
                              expect_ids=getattr(plan, "EXPECT_MODS", ()) or args.expect_id or (),
                              need_god=args.god or getattr(plan, "NEED_GOD", False),
                              rect=args.rect or getattr(plan, "RECT", None), fix=args.fix,
                              config_path=mock_config(getattr(plan, "EXPECT_MODS", ()) or args.expect_id or ()) if args.mock else None,
                              running_list=running_list_for(args))
        if args.config == "full" and getattr(plan, "full_list_differences", None):
            try:
                doc["full_list_differences"] = plan.full_list_differences(running_list_for(args))
            except Exception as ex:   # noqa: BLE001 - the sheet section says it could not be built; never silent
                doc["full_list_differences"] = {"error": "%s: %s" % (type(ex).__name__, ex)}
        # mod-supplied site check: plan.preflight(s) -> [failed precondition, ...] (plan 3.13)
        if getattr(plan, "preflight", None) and not args.mock_skip_site:
            try:
                for msg in call_plan_preflight(plan, s, _csv(args.chains)) or []:
                    cs.append(pf.Check("site:" + msg.split(":")[0][:40], FAIL, msg))
            except Exception as ex:
                cs.append(pf.Check("site_preflight", UNMEASURED, "%s: %s" % (type(ex).__name__, ex)))
        # cannot-show enforcement (plan 6.10): a VALIDATED walk's cannot-show id that no component claims
        if getattr(plan, "USE_SUITE", False):
            miss = unclaimed_cannot_show(mod)
            if miss:
                cs.append(pf.Check("cannot_show_claimed", FAIL,
                                   "cannot-show id(s) no component claims via shows=: %s" % miss))
        doc["preflight"] = [c.as_dict() for c in cs]
        ok, bad, unk = pf.verdict(cs, args.allow_unmeasured)
        if not ok:
            doc.update(refused="; ".join("%s %s" % (c.name, c.status) for c in bad + unk),
                       all_green=False, summary=B.summarize([]))
            code = 2
        else:
            wanted = [b for b in B.REGISTRY.values() if b.mod in (None, mod)]
            rows = [B.run_bar(b, s) for b in wanted]
            if getattr(plan, "USE_SUITE", False):
                rows += _suite_rows(s, mod, exp, doc, only=_csv(args.chains), skip=_csv(args.skip_chains),
                                    progress=lambda d: B.write_results(out, d), pre_rows=rows)
            doc["bars"] = rows
            doc["summary"] = B.summarize(rows)
            doc["all_green"] = run_all_green(rows, exp)
            if args.mock and getattr(plan, "MOCK_LIVE_ONLY", None):
                # a row the plan DECLARES unmeasurable offline (it needs a live map) reads UNMEASURED in every mock run;
                # a mock run is judged without those rows and names them. Only UNMEASURED is set aside: a FAIL fails.
                lo = set(plan.MOCK_LIVE_ONLY)
                skip = [r["id"] for r in rows if r["id"] in lo and r["status"] == UNMEASURED]
                if skip:
                    doc["mock_live_only_unmeasured"] = skip
                    doc["all_green"] = run_all_green([r for r in rows if r["id"] not in skip], exp)
                    print("mock: %d live-only row(s) set aside, UNMEASURED offline by declaration: %s"
                          % (len(skip), ", ".join(skip)))
            code = 0 if doc["all_green"] else 1
        doc["timing"] = s.timing
    doc["partial"] = False
    if mod_dir:
        doc["mod_hash"] = start_hash
    B.write_results(out, doc)
    if not args.mock and not args.no_record:
        _entry, msg = record_result(doc, mod, out, start_hash, mod_dir)
        print(msg)
    print("%s: %s  PASS=%s FAIL=%s UNMEASURED=%s  calls=%d mean=%.3fms  -> %s" % (
        mod, "REFUSED" if code == 2 else ("GREEN" if code == 0 else "NOT GREEN"),
        doc["summary"][PASS], doc["summary"][FAIL], doc["summary"][UNMEASURED],
        doc["timing"]["n"], doc["timing"]["mean_ms"], out))
    return code


def mod_hash_now(mod):
    """(mod_dir, modcheck.status.mod_hash) for a repo mod, or (None, None) for an ad-hoc run."""
    try:
        import runner
        import status
        d = runner.find_mod_dir(mod)
        return d, status.mod_hash(d)
    except Exception:
        return None, None


def record_result(doc, mod, out, start_hash, mod_dir, _record=None):
    """Record a finished run through modcheck.status.record_run (the only writer of
    modcheck_status.json), as runner.py does after `modcheck run`. Returns (entry|None, message).
    Not recorded, by design: a mock run (cmd_run never calls this for one), a preflight refusal
    (the SITE was refused, the mod never ran), a run with no rows, an ad-hoc mod with no repo
    folder, and a run during which the mod's files changed (its verdict would describe neither
    hash). The verdict is the run's own all_green: any FAIL or UNMEASURED row is not GREEN."""
    import northstar
    import status
    if not mod_dir or not start_hash:
        return None, "not recorded: %s has no repo mod folder" % mod
    if doc.get("refused"):
        return None, "not recorded: refused at preflight (%s) -- a site verdict, not the mod's" % doc["refused"][:160]
    rows = doc.get("bars") or []
    if not rows:
        return None, "not recorded: the run produced no rows"
    now = status.mod_hash(mod_dir)
    if now != start_hash:
        return None, "not recorded: %s changed during the run (%s -> %s)" % (mod, start_hash[:12], now[:12])
    rel = result_path(out)
    by = {}
    for r in rows:
        by.setdefault(r["status"], []).append(r["id"])
    extra = {"components": {"counts": {k: len(v) for k, v in by.items()},
                            "not_ok": [i for k, v in by.items() if k != PASS for i in v]},
             "bars": {r["id"]: r["status"] for r in rows},
             "source": {"verb": "northstar_driver run", "result": rel, "mode": doc.get("mode"),
                        "started": doc.get("started_utc"), "expected_source": doc.get("expected_source"),
                        "config": doc.get("config") or "current"},
             "config": doc.get("config") or "current"}
    if doc.get("compat"):
        extra["compat"] = {r["id"]: r["status"] for r in doc["compat"]}
    run_id = "%s/northstar_driver[%s]@%s" % (mod, doc.get("config") or "current", os.path.basename(out))
    entry = (_record or status.record_run)(mod, mod_dir, run_id, bool(doc.get("all_green")),
                                           walk=northstar.find_walk(ROOT, mod), extra=extra)
    return entry, "recorded %s: %s at %s (%s)" % (mod, entry["status"], entry["hash"][:12], run_id)


def result_path(out, root=None):
    """`out` relative to the repo, or absolute when it lies on another drive: Windows relpath raises ValueError for a
    D:\\ --out under a \\\\wsl.localhost repo (live 2026-11-03, after the run had already been written)."""
    try:
        return os.path.relpath(os.path.abspath(out), root or ROOT).replace(os.sep, "/")
    except ValueError:
        return os.path.abspath(out).replace(os.sep, "/")


def unclaimed_cannot_show(mod):
    """Cannot-show ids of a VALIDATED walk that no component's `shows=` claims. [] when no walk."""
    try:
        import northstar
        import runner
        w = northstar.find_walk(ROOT, mod)
        ns = northstar.parse(w) if w else None
        if not ns or ns["state"] != northstar.VALIDATED:
            return []
        claimed = set()
        for c in runner.load_validation(runner.find_mod_dir(mod)).components_declared():
            claimed.update(c.get("shows") or ())
        return [i for i in ns["cannot_show"] if i not in claimed]
    except Exception as ex:
        return ["(unreadable: %s)" % ex]


def _csv(v):
    return [x.strip() for x in (v or "").split(",") if x.strip()] or None


def call_plan_preflight(plan, s, chains):
    """plan.preflight(s), or plan.preflight(s, chains=[...]) when the plan accepts it: a site precondition only some
    chains need (ExplosiveGrowth's plant temperature) may then be skipped for a --chains run that needs none of them.
    chains None = every chain."""
    import inspect
    try:
        takes = "chains" in inspect.signature(plan.preflight).parameters
    except (TypeError, ValueError):
        takes = False
    return plan.preflight(s, chains=chains) if takes else plan.preflight(s)


def select_chains(chains, only=None, skip=None):
    """(run, skipped) from the suite's [(name, fn)] in suite order. `only` keeps just those names, `skip` drops
    those names; a name that matches no chain raises, so a typo can never silently run (or skip) nothing."""
    names = [n for n, _ in chains]
    unknown = [n for n in (only or []) + (skip or []) if n not in names]
    if unknown:
        raise SystemExit("unknown chain name(s) %s; the suite has: %s" % (unknown, ", ".join(names)))
    run, skipped = [], []
    for n, fn in chains:
        (skipped if (only and n not in only) or (skip and n in skip) else run).append((n, fn))
    return run, skipped


def skipped_chain_records(suite, skipped, why):
    """One UNMEASURED component per DECLARED component of each skipped chain (the offline declaration probe), so
    its bars read 'not run: <why>' rather than 'no component claims' and a split run is never mistaken for green."""
    out = []
    for name, fn in skipped:
        sub = copy.copy(suite)
        sub.chains = [(name, fn)]
        try:
            decl = sub.components_declared()
        except Exception as ex:   # noqa: BLE001 - a declaration that cannot be probed still records the skip
            decl = [{"shows": [], "error": "%s: %s" % (type(ex).__name__, ex)}]
        out.append({"name": name, "skipped": True, "components": [
            {"name": "skipped#%d" % i, "verdict": UNMEASURED, "shows": list(d.get("shows") or ()),
             "toggle": d.get("toggle"), "detail": "UNMEASURED: chain not run (%s)" % why}
            for i, d in enumerate(decl or [{"shows": []}])]})
    return out


def _rows_from(chains, expected, texts):
    """Compat components are partitioned out FIRST: a `compat_*` row never reaches the bar rollup, even if it
    (wrongly) claims a `shows=` bar."""
    own = [dict(ch, components=[c for c in ch["components"] if not is_compat(c)]) for ch in chains]
    return mark_visual(B.rollup_components(own, expected), texts) + functional_rows(own)


COMPAT_PREFIX = "compat_"


def is_compat(c):
    """A compatibility component (Graffiti plan: foreign mark defs of SacredGraffiti / GraffitiImperial on the
    full list): named `compat_*` (the prefix alone decides; a `shows=` claim on one is ignored). Reported in
    doc["compat"], never in the mod's bars, its summary or its verdict."""
    return str(c.get("name", "")).startswith(COMPAT_PREFIX)


def compat_rows(chains):
    out = []
    for ch in chains:
        for c in ch["components"]:
            if not is_compat(c):
                continue
            v = str(c.get("verdict", ""))
            st = PASS if v.startswith("PASS") else (FAIL if v == "FAIL" else UNMEASURED)
            out.append({"id": "%s.%s" % (ch.get("name"), c.get("name")), "status": st, "compat": True,
                        "evidence": str(c.get("detail") or v)})
    return out


def _suite_rows(s, mod, expected, doc, only=None, skip=None, progress=None, pre_rows=(), suite=None):
    """Run the suite ONE CHAIN AT A TIME and hand `progress` a partial results doc after every chain, so a run
    killed mid-suite (2026-10-12: a 50-min shell timeout inside embergrass_regrow left no JSON at all) still
    leaves every finished row on disk. Each chain gets runner.run_suite on a one-chain copy of the suite with the
    same anchor, which is what one whole-suite call did per chain (mod=None, situational off)."""
    import runner
    suite = suite or runner.load_validation(runner.find_mod_dir(mod))
    run, skipped = select_chains(suite.chains, only, skip)
    why = "--chains %s" % ",".join(only) if only else ""
    why = (why + " " if why else "") + ("--skip-chains %s" % ",".join(skip) if skip else "")
    skipped_out = skipped_chain_records(suite, skipped, why.strip())
    doc["chains_selected"] = [n for n, _ in run]
    doc["chains_skipped"] = [n for n, _ in skipped]
    doc["bar_text"], doc["bar_text_source"] = bar_text(mod)
    anchor = runner._default_anchor(s)
    done = []
    for i, (name, fn) in enumerate(run):
        sub = copy.copy(suite)
        sub.chains = [(name, fn)]
        res = runner.run_suite(sub, s, anchor=anchor, mod=None)   # visual half: judge_cli.py, after the run
        done.extend(res["chains"])
        if progress is not None:
            part = dict(doc, partial=True, chains_done=[c.get("name") for c in done],
                        chains_pending=[n for n, _ in run[i + 1:]], components=component_records(done))
            part["bars"] = list(pre_rows) + _rows_from(done + skipped_out, expected, doc["bar_text"])
            part["summary"] = B.summarize(part["bars"])
            part["compat"] = compat_rows(done)
            part["all_green"] = False
            progress(part)
    chains = done + skipped_out
    for ch in chains:
        for c in ch["components"]:
            if not str(c.get("verdict", "")).startswith("PASS"):
                print("component %s/%s: %s" % (ch.get("name"), c.get("name"),
                                               json.dumps({k: v for k, v in c.items() if k != "name"}, default=str)[:600]))
    doc["components"] = component_records(chains)
    doc["compat"] = compat_rows(chains)
    return _rows_from(chains, expected, doc["bar_text"])


def functional_rows(chains):
    """One row per suite component that claims no `shows=` bar: the mod's functional script
    (debug_process.md section 2). Without these a suite FAIL never reached the summary or the verdict,
    and a mod with no north star could never be GREEN (zero rows). Status is the component's own."""
    out = []
    for ch in chains:
        for c in ch["components"]:
            if c.get("shows") or is_compat(c):
                continue
            v = str(c.get("verdict", ""))
            st = PASS if v.startswith("PASS") else (FAIL if v == "FAIL" else UNMEASURED)
            out.append({"id": "%s.%s" % (ch.get("name"), c.get("name")), "status": st, "functional": True,
                        "evidence": str(c.get("detail") or v)[:300],
                        "evidenceFull": str(c.get("detail") or v)})
    return out


def run_all_green(rows, expected):
    """Every expected north-star bar PASS (bars.all_green) AND every functional row PASS."""
    return B.all_green(rows, expected or None) and all(r["status"] == PASS for r in rows if r.get("functional"))


def to_wsl(p):
    """`C:\\x\\y.png` -> `/mnt/c/x/y.png`; a POSIX path is returned unchanged."""
    p = str(p or "")
    if len(p) > 2 and p[1] == ":" and p[0].isalpha():
        return "/mnt/%s/%s" % (p[0].lower(), p[2:].replace("\\", "/").lstrip("/"))
    return p


def to_win(p):
    """`/mnt/c/x/y.png` -> `C:\\x\\y.png`; a Windows path is returned unchanged."""
    p = str(p or "")
    if p.startswith("/mnt/") and len(p) > 6 and p[6] == "/":
        return "%s:\\%s" % (p[5].upper(), p[7:].replace("/", "\\"))
    return p


def component_records(chains):
    """Every component, with each screenshot as {path (as the bridge returned it), win, wsl}, so the
    WSL-side judge can find the image without re-deriving anything."""
    out = []
    for ch in chains:
        for c in ch["components"]:
            # evidenceFull: a component whose `shows=` bar is not a driver bar (every pyre_* north-star bar) reaches the
            # result JSON ONLY here; without it a FAIL's reason survived only as a 600-char console line (2026-10-12c).
            out.append({"chain": ch.get("name"), "name": c.get("name"), "verdict": c.get("verdict"),
                        "evidenceFull": str(c.get("detail") or c.get("verdict") or ""),
                        "shows": list(c.get("shows") or ()),
                        "screenshots": [{"path": p, "win": to_win(p), "wsl": to_wsl(p)}
                                        for p in (c.get("screenshots") or ()) if p]})
    return out


def bar_text(mod):
    """{bar id: {polarity, text}} from the VALIDATED walk -- the narrow question the judge asks."""
    try:
        import northstar
        w = northstar.find_walk(ROOT, mod)
        ns = northstar.parse(w) if w else None
        if not ns or ns["state"] != northstar.VALIDATED:
            return {}, "no VALIDATED walk"
        out = {i: {"polarity": "must", "text": ns["must_show_text"].get(i, "")} for i in ns["must_show"]}
        out.update({i: {"polarity": "cannot", "text": ns["cannot_show_text"].get(i, "")}
                    for i in ns["cannot_show"]})
        return out, "%s (hash %s)" % (os.path.relpath(w, ROOT), ns.get("recorded_hash", ""))
    except Exception as ex:
        return {}, "walk unreadable: %s" % ex


def mark_visual(rows, texts):
    """Every `shows=` bar is judged on its screenshots, so state alone cannot PASS it: a state PASS
    reads UNMEASURED until judge_cli.py writes a verdict. The state result is kept in `state_status`."""
    for r in rows:
        r["visual"] = True
        r["polarity"] = (texts.get(r["id"]) or {}).get("polarity", "must")
        r["state_status"], r["state_evidence"] = r["status"], r["evidence"]
        if r["status"] == PASS:
            r["status"] = UNMEASURED
            r["evidence"] = "visual bar: state PASS, not yet judged (run judge_cli.py) [%s]" % r["evidence"]
    return rows


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = ap.add_subparsers(dest="cmd", required=True)
    for name, fn in (("preflight", cmd_preflight), ("run", cmd_run)):
        p = sub.add_parser(name)
        p.set_defaults(fn=fn)
        p.add_argument("--mod")
        p.add_argument("--mock", action="store_true", help="in-memory game; no bridge")
        p.add_argument("--fault", help="mock faults, comma list: zombie,modal,pause_lies,dev_off,god_off,dirty,unfrozen")
        p.add_argument("--god", action="store_true", help="require god mode")
        p.add_argument("--rect", help="x,z,w,h test area that must be empty")
        p.add_argument("--fix", action="store_true", help="pause / enable god, each proved by re-read")
        p.add_argument("--expect-id", action="append", help="packageId that must be active (repeat)")
        p.add_argument("--allow-unmeasured", action="store_true")
        p.add_argument("--mock-skip-site", action="store_true", help="skip plan.preflight (offline selftests)")
        p.add_argument("--pipeline", action="store_true", help="pipelined call_many (correct but no faster: 1 reply/frame, pipecheck.py 2026-10-21)")
        p.add_argument("--config", choices=("current", "full"), default="current",
                       help="full = full-list mode (plan 6.8): no list swap; the RUNNING list (jawa/running_mods) must "
                            "equal --list (default FULL.LATEST) or the run refuses; recorded with config 'full'")
        p.add_argument("--list", help="full-list mode: the ModsConfig-shaped file the running list must equal")
        if name == "run":
            p.add_argument("--plan", help="python plan module registering @bar functions")
            p.add_argument("--out")
            p.add_argument("--no-record", action="store_true",
                           help="live run only: do not record it in modcheck_status.json")
            p.add_argument("--chains", help="suite plans: run ONLY these chains (comma list); the rest read "
                                            "UNMEASURED 'chain not run'")
            p.add_argument("--skip-chains", help="suite plans: skip these chains (comma list), e.g. a long-wait "
                                                 "chain split into its own run")
    p = sub.add_parser("running-list", help="READ-ONLY FINAL VERIFICATION: running list vs --list (default "
                                            "FULL.LATEST); exit 0 equal, 1 differs, 2 unmeasured or another tier")
    p.set_defaults(fn=cmd_running_list, mock=False, pipeline=False)
    p.add_argument("--list")
    p = sub.add_parser("needs-mods", help="READ-ONLY, tier-aware: exit 0 iff the running game holds each --mod (its "
                                          "About.xml packageId + modDependencies), each --id, Core and every DLC; 2 if not")
    p.set_defaults(fn=cmd_needs_mods, mock=False, pipeline=False)
    p.add_argument("--mod", action="append", help="repo mod folder, e.g. Graffiti (repeat)")
    p.add_argument("--id", action="append", help="extra packageId the proof needs (repeat)")
    a = ap.parse_args(argv)
    return a.fn(a)


if __name__ == "__main__":
    sys.exit(main())

scripts.src/RimMandrake/Miasma/tests/warden_moth:
#!/usr/bin/env python3
"""Live proof L2 of MIASMA_WARDEN_MOTHER_ART_1: a debug-aged warden mother draws the aged graphic.

    python.exe src/RimMandrake/Miasma/tests/warden_mother_live_proof.py L2

On the CURRENT map of a quicktest colony that loads RM_WardenMother (Miasma, standalone or folded into the biome
composite), through the JawaBench bridge:
  1. jawa/spawn_pawn RM_WardenMother, faction none, at the map centre.
  2. If she generated at or past ELDER_MIN_AGE, age her DOWN to ADULT_AGE (raw setter), so step 3 crosses the boundary.
  3. Read her life stage and body texPath (jawa/thing_explain): must be an adult stage drawing ADULT_TEX.
  4. jawa/set_pawn_age biologicalYears=AGED_AGE (DebugSetAge: birthdays fire, the life stage recalculates).
  5. Jump the camera to her, wait for a draw, read again: the life stage must be RM_WardenMotherElder, the body
     texPath AGED_TEX (not ADULT_TEX), a running mod must hold that path, and the RENDERED body texture must be
     that pack's texture (thing_explain label OBSERVED). A resolved render tree drawing anything else is a FAIL.
Exit 0 = the clause holds, 1 = a reading refutes it, 2 = no reading (no bridge, no map, the render tree never
resolved): never a verdict. It writes only a wild pawn onto the quicktest map (every save but the canonical world
saves is disposable) and never the world. Not a flyer: no flight is touched.

verdict() is pure and offline-tested by test_warden_mother_live_verdict.py, including the gen-1 checker's mutant
(elder texPath set back to the adult art), which must exit 1.
"""
import os
import sys
import time

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, "..", "..", "Utils"))

KIND = "RM_WardenMother"
ELDER_STAGE = "RM_WardenMotherElder"
ADULT_TEX = "Things/Pawn/Animal/Miasma/WardenMother/WardenMother"
AGED_TEX = "Things/Pawn/Animal/Miasma/WardenMother/WardenMotherAged"
ELDER_MIN_AGE = 38.0    # RM_WardenMother.xml lifeStageAges, last entry (the offline test pins it)
ADULT_AGE = 20.0
AGED_AGE = 40.0
DRAW_WAITS = 6          # x 0.5 s for the render tree to resolve after the jump


def body_row(explain):
    """The 'body' appearance row of a thing_explain reply, or None."""
    for row in ((explain or {}).get("appearance") or {}).get("paths") or []:
        if row.get("role") == "body":
            return row
    return None


def verdict(pre_stage, pre_explain, post_stage, post_explain):
    """(code, line). code 0 PASS, 1 FAIL, 2 UNMEASURED. Pure: readings in, verdict out."""
    pre, post = body_row(pre_explain), body_row(post_explain)
    if pre is None or post is None:
        return 2, "UNMEASURED: no body appearance row (pre=%r post=%r)" % (pre, post)
    if pre_stage == ELDER_STAGE:
        return 2, "UNMEASURED: she was still %s before ageing; the boundary was not crossed" % ELDER_STAGE
    if pre.get("texPath") != ADULT_TEX:
        return 1, "FAIL adult stage %s draws %r, expected %r" % (pre_stage, pre.get("texPath"), ADULT_TEX)
    if post_stage != ELDER_STAGE:
        return 1, "FAIL aged to %s years she is in stage %r, expected %s" % (AGED_AGE, post_stage, ELDER_STAGE)
    tex = post.get("texPath")
    if tex != AGED_TEX:
        return 1, "FAIL elder stage draws %r, expected %r (adult art is %r)" % (tex, AGED_TEX, ADULT_TEX)
    if not post.get("packsHoldingPath"):
        return 1, "FAIL no running mod holds %r: she would draw magenta" % tex
    limits = ((post_explain or {}).get("appearance") or {}).get("limits") or ""
    if post.get("label") != "OBSERVED":
        if "not resolved" in limits or "unreadable" in limits:
            return 2, "UNMEASURED: elder texPath right, but the rendered texture was not readable (%s)" % limits
        return 1, "FAIL the rendered body texture is not the %s texture (label %r, %s)" % (
            AGED_TEX, post.get("label"), post.get("note"))
    return 0, "PASS %s -> %s: draws %s from %s (OBSERVED)" % (pre_stage, post_stage, tex, post.get("provider"))


def _ok(r, what):
    if not isinstance(r, dict) or r.get("success") is False:
        raise RuntimeError("%s refused: %r" % (what, r))
    return r


def run(c):
    mi = _ok(c.call("jawa/map_info", {}), "map_info")
    size = mi.get("mapSize") or {}
    sx = mi.get("sizeX") or size.get("x")
    sz = mi.get("sizeZ") or size.get("z")
    if not sx or not sz:
        return 2, "UNMEASURED: map_info gave no size: %r" % sorted(mi)
    cx, cz = int(sx) // 2, int(sz) // 2
    sp = _ok(c.call("jawa/spawn_pawn", {"kindDef": KIND, "x": cx, "z": cz, "faction": "none"}), "spawn_pawn")
    rows = sp.get("pawns") or []
    if not rows or not rows[0].get("ok"):
        return 2, "UNMEASURED: spawn_pawn landed no %s: %r" % (KIND, sp.get("message"))
    pid = rows[0]["id"]
    print("  spawned %s at %s,%s" % (pid, rows[0].get("x"), rows[0].get("z")), flush=True)
    age = _ok(c.call("jawa/set_pawn_age", {"pawn": pid, "biologicalYears": ADULT_AGE, "allowBackwards": True}),
              "set_pawn_age down")
    pre_stage = (age.get("after") or {}).get("lifeStage")
    pre_explain = _ok(c.call("jawa/thing_explain", {"id": pid}), "thing_explain pre")
    print("  pre: stage %s body %s" % (pre_stage, (body_row(pre_explain) or {}).get("texPath")), flush=True)
    age = _ok(c.call("jawa/set_pawn_age", {"pawn": pid, "biologicalYears": AGED_AGE}), "set_pawn_age up")
    post_stage = (age.get("after") or {}).get("lifeStage")
    post_explain = None
    for _ in range(DRAW_WAITS):
        x = (post_explain or {}).get("what") or {}
        c.call("rimworld/jump_camera_to_cell", {"x": x.get("x", cx), "z": x.get("z", cz)})
        time.sleep(0.5)
        post_explain = _ok(c.call("jawa/thing_explain", {"id": pid}), "thing_explain post")
        if (body_row(post_explain) or {}).get("label") == "OBSERVED":
            break
    print("  post: stage %s body %r" % (post_stage, body_row(post_explain)), flush=True)
    return verdict(pre_stage, pre_explain, post_stage, post_explain)


def main(argv):
    if len(argv) != 2 or argv[1] != "L2":
        print(__doc__)
        return 2
    try:
        import rimbridge_client as rb
        h, p, tok = rb.resolve_endpoint()
        c = rb.RimBridge(host=h, port=p, token=tok, timeout=120.0)
        c.connect()
        code, line = run(c)
    except Exception as e:  # noqa: BLE001 -- any bridge failure is an instrument error, never a verdict
        print("L2 UNMEASURED: %s: %s" % (type(e).__name__, e))
        return 2
    print("L2 " + line)
    return code


if __name__ == "__main__":
    sys.exit(main(sys.argv))

scripts.src/RimMandrake/Utils/live_def_check.py:
#!/usr/bin/env python3
"""live_def_check.py -- does the RUNNING game's def carry what a criterion says it must? One read-only jawa/get_defs call.

    python3 src/RimMandrake/Utils/live_def_check.py --has ThingDef/RM_Chittik=CompProperties_WoundLink [--has ...]

Each --has is DefType/defName=TOKEN: the def must resolve in the live game, and TOKEN must appear as a whole value in the
def's reported fields (a comp class, a field value). `--has DefType/defName` with no `=` asks only that it resolves.

Exit 0 every claim holds, 1 a claim is false (the game answered and said no: a real FAIL), 2 UNMEASURED (no bridge, an
answer that is not what get_defs returns, a def the reply never mentions). Callers hold the bridge lock; this never takes it.

A def that does not resolve is a FAIL only when the mod that defines it is in the RUNNING load. Its owners are the repo's
mods whose XML carries <defName>NAME</defName>; the running load is jawa/running_mods (ModsConfig.xml names the NEXT
load, so a mod enabled after launch is absent here). Owner not running, or the running list unreadable: UNMEASURED. A def
no repo mod defines (a typo, a vanilla or donor def) stays a FAIL: the game answered and nothing explains the no.
A mod folded into the composed biomes mod loads under the composed packageId, so an owner or a --needs naming the member
is also met by the composed id (biomes_compose.folded_ids); without that, a composed def that fails to resolve could only
ever read UNMEASURED.

--needs PACKAGEID / --without PACKAGEID state a criterion's load condition ("with Quarry loaded", "on a tier carrying
Warcasket", "with Alpha Biomes absent"): unmet, or the running list unread, is UNMEASURED before any def is judged. A donor
def no repo mod defines is a FAIL when it does not resolve, so a criterion about a donor's def needs its --needs.
RimBridge binds Windows loopback, so the call runs under Windows Python (python.exe), as rimbridge_client.py says.
"""
import argparse
import json
import os
import subprocess
import sys
import xml.etree.ElementTree as ET

HERE = os.path.dirname(os.path.abspath(__file__))
CLIENT = os.path.join(HERE, "rimbridge_client.py")
SRC = os.path.normpath(os.path.join(HERE, "..", ".."))      # the repo's src/: every mod we ship lives under it
PASS, FAIL, UNMEASURED = 0, 1, 2


def parse_claims(items):
    """-> [(defkey, token or None)]; ValueError on a claim that is not DefType/defName[=TOKEN]."""
    out = []
    for raw in items:
        key, _, token = raw.partition("=")
        key, token = key.strip(), token.strip()
        if "=" in raw and not token:
            raise ValueError("an empty TOKEN would weaken the claim to existence-only; drop the '=': %r" % raw)
        if key.count("/") != 1 or not all(key.split("/")):
            raise ValueError("not DefType/defName[=TOKEN]: %r" % raw)
        out.append((key, token or None))
    return out


def values(node):
    """Every scalar in a JSON tree, as strings: the token is matched against these whole, never as a substring."""
    if isinstance(node, dict):
        for v in node.values():
            yield from values(v)
    elif isinstance(node, list):
        for v in node:
            yield from values(v)
    elif node is not None:
        yield str(node)


def _no_duplicate_keys(pairs):
    """json keeps the LAST of a repeated key, so found:false,found:true would read as true: that is no answer."""
    keys = [k for k, _ in pairs]
    if len(set(keys)) != len(keys):
        raise ValueError("a JSON object repeats a key")
    return dict(pairs)


def _canon(d):
    """A record as the claim reads it: JSON text, so True and 1 stay different (python's == merges them)."""
    return json.dumps([d.get("found"), d.get("fields")], sort_keys=True, default=str)


def judge(claims, reply, owners=None, running=None):
    """-> (exit code, lines). `reply` is get_defs' JSON object. `owners` {defkey: set of lower-case packageIds defining
    it}; `running` the lower-case packageIds of the RUNNING load, or None when unread. With no `owners` an unresolved
    def is a FAIL, as before."""
    if not isinstance(reply, dict) or not isinstance(reply.get("defs"), list):
        return UNMEASURED, ["UNMEASURED: the reply is not a get_defs answer"]
    by_key, bad = {}, set()
    for d in reply["defs"]:
        if not isinstance(d, dict) or not isinstance(d.get("requested"), str) or not d["requested"]:
            return UNMEASURED, ["UNMEASURED: a def record without a string `requested`: %r" % (d,)]
        if d["requested"] in by_key and _canon(by_key[d["requested"]]) != _canon(d):
            bad.add(d["requested"])          # two records that disagree: neither is the answer
        by_key[d["requested"]] = d
    seen, lines = set(), []
    for key, token in claims:
        d = by_key.get(key)
        if d is None:
            seen.add(UNMEASURED)
            lines.append("UNMEASURED %s: the reply does not mention it" % key)
            continue
        if key in bad or not isinstance(d.get("found"), bool) or (
                token is not None and d.get("found") and not isinstance(d.get("fields"), (dict, list))):
            seen.add(UNMEASURED)
            lines.append("UNMEASURED %s: the record is malformed or contradicts another (found=%r)" % (key, d.get("found")))
            continue
        if not d.get("found"):
            if owners and key in owners and owners[key] is None:
                seen.add(UNMEASURED)
                lines.append("UNMEASURED %s: does not resolve, and the search for the mod that defines it failed" % key)
                continue
            mods = sorted((owners or {}).get(key) or ())
            if mods and running is None:
                seen.add(UNMEASURED)
                lines.append("UNMEASURED %s: does not resolve, and the running mod list is unread, so whether %s is "
                             "loaded is unknown" % (key, "/".join(mods)))
            elif mods and not set(mods) & set(running):
                seen.add(UNMEASURED)
                lines.append("UNMEASURED %s: does not resolve because %s is not in the RUNNING load (ModsConfig names "
                             "the next load)" % (key, "/".join(mods)))
            else:
                seen.add(FAIL)
                lines.append("FAIL %s: does not resolve in the live game%s" % (
                    key, " though %s is loaded" % "/".join(sorted(set(mods) & set(running))) if mods else ""))
            continue
        where = "%s from %s" % (key, d.get("packageId") or "?")
        if token is None:
            lines.append("PASS %s resolves" % where)
        elif token in set(values(d.get("fields"))):
            lines.append("PASS %s carries %s" % (where, token))
        else:
            seen.add(FAIL)
            lines.append("FAIL %s lacks %s" % (where, token))
    return (FAIL if FAIL in seen else UNMEASURED if UNMEASURED in seen else PASS), lines   # a real FAIL stands


def aliases(src=SRC):
    """-> {folded member packageId (lower): composed packageId}; None when the compose manifest cannot be read (then a
    member's absence cannot be established, so --without is UNMEASURED)."""
    try:
        sys.path.insert(0, HERE)
        import biomes_compose
        return biomes_compose.folded_ids(src)
    except Exception:
        return None


def loaded(pid, running, alias):
    """Is `pid` in the running load, directly or through the composed mod it is folded into?"""
    pid = pid.strip().lower()
    return pid in running or (pid in (alias or {}) and alias[pid] in running)


def condition(needs, without, running, alias):
    """-> (UNMEASURED, lines) when the criterion's load condition is unmet or unreadable, else (None, lines)."""
    if not needs and not without:
        return None, []
    if not all(p.strip() for p in list(needs) + list(without)):
        return UNMEASURED, ["UNMEASURED: an empty --needs/--without names no mod"]
    if alias is None and without:
        return UNMEASURED, ["UNMEASURED: the compose manifest is unread, so a mod folded into the composed one may be "
                            "loaded unseen: --without cannot be checked"]
    if running is None:
        return UNMEASURED, ["UNMEASURED: the running mod list is unread, so the load condition cannot be checked"]
    miss = [p for p in needs if not loaded(p, running, alias)]
    extra = [p for p in without if loaded(p, running, alias)]
    if miss or extra:
        return UNMEASURED, ["UNMEASURED: the running load %s; the criterion is about another load" % "; ".join(
            (["lacks %s" % ", ".join(miss)] if miss else []) + (["holds %s" % ", ".join(extra)] if extra else []))]
    return None, ["load condition met: %s" % ", ".join(["has %s" % p for p in needs] + ["lacks %s" % p for p in without])]


def with_aliases(owners, alias):
    """owners with each folded member's composed packageId added beside it."""
    alias = alias or {}
    return {k: (None if v is None else set(v) | {alias[p] for p in v if p in alias}) for k, v in owners.items()}


def defs_param(keys):
    """get_defs' `defs` argument: SEMICOLON-separated DefType/defName pairs (JawaBenchTerrainTools.cs GetDefs).
    A comma-joined list reads as one unknown key and every claim comes back unmentioned."""
    return ";".join(keys)


def mod_package_id(path, src=SRC):
    """-> the lower-case packageId of the mod holding `path` (nearest ancestor with About/About.xml), or None."""
    d = os.path.dirname(os.path.abspath(path))
    while d.startswith(os.path.abspath(src)) and len(d) >= len(os.path.abspath(src)):
        about = os.path.join(d, "About", "About.xml")
        if os.path.isfile(about):
            try:
                pid = ET.parse(about).getroot().findtext("packageId")
            except (ET.ParseError, OSError):
                return None
            return pid.strip().lower() if pid and pid.strip() else None
        d = os.path.dirname(d)
    return None


def def_owners(keys, src=SRC):
    """-> {defkey: set of packageIds} for the repo mods whose XML names <defName>NAME</defName>. Missing keys own nothing;
    a key whose search failed maps to None (owner unknown, so an unresolved def cannot be called a FAIL)."""
    out = {}
    for key in keys:
        name = key.split("/", 1)[1]
        try:
            r = subprocess.run(["grep", "-rlF", "--include=*.xml", "<defName>%s</defName>" % name, src],
                               capture_output=True, text=True, timeout=60)
        except (OSError, subprocess.TimeoutExpired):
            out[key] = None
            continue
        if r.returncode not in (0, 1):          # 1 is grep's "no match"; 2 is an error, matches or not
            out[key] = None
            continue
        pids = {p for p in (mod_package_id(f, src) for f in r.stdout.splitlines() if f) if p}
        if pids:
            out[key] = pids
    return out


def running_ids(reply):
    """jawa/running_mods' reply -> lower-case packageIds, or None when it is not that answer."""
    rm = reply.get("result", reply) if isinstance(reply, dict) else None
    if not isinstance(rm, dict):
        return None
    ids = rm.get("packageIds")
    if not isinstance(ids, list) or not ids or not all(isinstance(x, str) and x for x in ids):
        return None
    return {x.lower() for x in ids}


def _bridge(tool, params, timeout, read_only_static=False):
    """-> (reply or None, why). Read-only; runs the client under Windows Python. read_only_static: declare a jawa/static_call
    a read (the client accepts it only for its reviewed READ_ONLY_STATIC_CALLS, else refuses with exit 3)."""
    try:
        path = subprocess.run(["wslpath", "-w", CLIENT], capture_output=True, text=True, timeout=20).stdout.strip()
        r = subprocess.run(["python.exe", path, "--timeout", str(timeout), "--call", tool, "--json", json.dumps(params)]
                           + (["--read-only-static"] if read_only_static else []),
                           capture_output=True, text=True, timeout=timeout + 30, stdin=subprocess.DEVNULL)
    except (OSError, ValueError, subprocess.TimeoutExpired) as e:      # ValueError: UnicodeDecodeError on the reply bytes
        return None, "the bridge call did not finish: %s" % str(e)[:200]
    if r.returncode:
        return None, "bridge call exit %d: %s" % (r.returncode, (r.stderr or r.stdout)[-300:])
    try:
        return json.loads(r.stdout, object_pairs_hook=_no_duplicate_keys), None
    except (ValueError, RecursionError):
        return None, "the bridge answered something that is not JSON: %s" % r.stdout[:200]


def call_running_mods(timeout):
    """-> set of lower-case packageIds the RUNNING game loaded, or None."""
    reply, _ = _bridge("jawa/running_mods", {"details": False, "assembly": ""}, timeout)
    return running_ids(reply)


def call_get_defs(keys, timeout):
    """-> (reply dict or None, why). Read-only; runs the client under Windows Python."""
    return _bridge("jawa/get_defs", {"defs": defs_param(keys)}, timeout)


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--has", action="append", required=True, metavar="DefType/defName[=TOKEN]")
    ap.add_argument("--needs", action="append", default=[], metavar="PACKAGEID",
                    help="the criterion's load holds this mod: UNMEASURED unless the RUNNING load has it")
    ap.add_argument("--without", action="append", default=[], metavar="PACKAGEID",
                    help="the criterion's load lacks this mod: UNMEASURED when the RUNNING load has it")
    ap.add_argument("--timeout", type=int, default=60)
    a = ap.parse_args(argv)
    try:
        claims = parse_claims(a.has)
    except ValueError as e:
        print("UNMEASURED: %s" % e)
        return UNMEASURED
    alias, running, pre = aliases(), None, []
    if a.needs or a.without:
        running = call_running_mods(a.timeout)
        code, pre = condition(a.needs, a.without, running, alias)
        if code is not None:
            print("\n".join(pre))
            print("VERDICT UNMEASURED")
            return code
    reply, why = call_get_defs(sorted({k for k, _ in claims}), a.timeout)
    if reply is None:
        print("UNMEASURED: %s" % why)
        return UNMEASURED
    try:
        owners = {}
        if isinstance(reply, dict) and isinstance(reply.get("defs"), list) and any(
                isinstance(d, dict) and d.get("found") is False for d in reply["defs"]):
            owners = with_aliases(def_owners(sorted({k for k, _ in claims})), alias)
            if owners and running is None:
                running = call_running_mods(a.timeout)
        code, lines = judge(claims, reply, owners, running)
        lines = pre + lines
    except Exception as e:      # an uncaught crash would exit 1, which the runner records as a FAIL
        print("UNMEASURED: the reply could not be judged: %s: %s" % (type(e).__name__, str(e)[:200]))
        return UNMEASURED
    print("\n".join(lines))
    print({PASS: "VERDICT PASS", FAIL: "VERDICT FAIL", UNMEASURED: "VERDICT UNMEASURED"}[code])
    return code


def safe_main(argv=None):
    """main(), where nothing may escape: an uncaught exception exits 1 and the runner would record it as a FAIL."""
    try:
        return main(argv)
    except SystemExit:
        raise
    except BaseException as e:
        sys.stdout.write("UNMEASURED: " + ascii("%s: %s" % (type(e).__name__, str(e)[:200])) + "\n")
        return UNMEASURED


if __name__ == "__main__":
    sys.exit(safe_main())

scripts.src/RimMandrake/Utils/modcheck/live_queu:
"""Live proofs of MAP_AWARENESS_PROVE_ON_A_QUIET_MAP, one clause per call (design/RimMandrake/map_awareness.md):

    python.exe src/RimMandrake/Utils/modcheck/live_queue/map_awareness_proof.py A1 .. A13

Runs on the CURRENT quicktest map through the bridge (Session focus=False: never focuses the game), stages what the
clause needs near the anchor farthest from the colonists, reads the result, removes what it spawned (Vanish: no
death, no corpse) and prints one "<clause> PASS|FAIL|UNMEASURED: ..." line.
Exit 0 = the clause holds, 1 = it answered and something is wrong, 2 = UNMEASURED (no bridge, no map, recorder not
installed, a precondition the map does not meet).

  A1  substituted spawn receipt: a spawn whose kind changes after the tool returned (recruit -> Pawn.SetFaction ->
      ChangeKind, Pawn.cs:2734) gets a receipt whose INDEPENDENT read-back shows requested vs actual; an untouched
      control spawn's receipt stays clean
  A2  bounded condition contract: expect("condition", any, max_count=1) admits the first condition (Eclipse) and
      the second (Aurora) is still reported by condition_unexpected
  A3  player-faction joiner: an undeclared new player pawn -> player_joiner names its id; pawn_arrived and
      pawn_state_changed do not also claim it
  A4  stranger naming: a manhunter Warg and a player joiner -> the detectors name both ids, and scene_report prints
      both with decomposed hostility (no-faction + mental:Manhunter / player) and an origin it does not over-claim
  A5  recruit = state change: a factionless stranger already in the baseline turned player -> pawn_state_changed,
      never player_joiner / pawn_arrived
  A6  old-id arrival via set diff: a colonist taken off the map by caravan, a newer pawn spawned, the colonist
      brought back (JawaBenchAwarenessProof.CaravanBack) -> player_joiner names the OLD id (an id watermark misses it)
  A7  ambiguous thing_explain: two Muffalo, name selector -> resolved false, both ids listed, nothing picked; the id
      selector on one resolves
  A8  incident called-but-failed: a worker that returns false (ShortCircuit / CropBlight / SelfTame on a map with
      no conduit / crop / wild animal) -> journal row called, outer body ran, returned false, no 'fired' wording
  A9  forced raid chain: RaidEnemy via jawa/fire_incident -> journal chain bridge:jawa/fire_incident > incident:
      RaidEnemy, returned true, pawns generated > 0, and those pawns' pawn_origin generation chain says the same
  A10 drop-pod deferred delivery: a Mechanoid RaidEnemy whose pawns were generated during the call but spawned 0
      during it -> after the pods land, the new hostiles read generation chain incident:RaidEnemy (bridge-rooted)
      and spawn ticks later than the call
  A11 first-map mapgen recorded at startup: startedBy bridge-registration, GeneratePawn installed early, and the
      map's wildlife reads a generation chain with mapgen. Precondition at launch: test profile and
      "install.generation-early": true in <SaveData>/JawaBench/tps/awareness_settings.json
  A12 caravan transfer: a colonist out by caravan and back reads spawn observedRespawn or mapTransfer, never
      firstObservedSpawn
  A13 overflow counters: more TryExecute calls than the journal ring holds (512) -> retained stays 512, the
      overwritten counter rises by the overflow, status and journal agree, the oldest retained seq advances

verdict() is pure and is exercised offline by selftest_map_awareness_proof.py.
"""
import json
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
CLAUSES = tuple("A%d" % i for i in range(1, 14))
RING = 512                                    # JawaBenchAwarenessCore.IncidentCapacity
FAIL_CANDIDATES = ("ShortCircuit", "CropBlight", "SelfTame")   # Core Incidents_Map_Misc.xml; worker returns false
PROBE = "JawaBench.BridgeTools.JawaBenchAwarenessProof"         # on a map with nothing to act on
FORBIDDEN = ("caused by", "created by", "mapgen pawn", "generated before load", "newly created and intentionally",
             "no arrivals occurred", "this mod caused", "vanilla initiated", "intentionally spawned")


# ------------------------------------------------------------------------------------------------ pure verdicts
def _chain_kinds(chain):
    """'bridge:jawa/fire_incident#3 > incident:RaidEnemy#4' -> ['bridge:jawa/fire_incident', 'incident:RaidEnemy']"""
    return [re.sub(r"#\d+$", "", part.strip()) for part in (chain or "").split(">") if part.strip()]


def _num(pid):
    m = re.search(r"(\d+)$", pid or "")
    return int(m.group(1)) if m else None


def _ids(hits, det):
    out = []
    for h in hits or []:
        if h.get("detector") == det:
            out += list(h.get("ids") or [])
    return out


def _over_claims(text):
    t = (text or "").lower()
    return [w for w in FORBIDDEN if w in t]


def v_A1(d):
    sub, ctl = d.get("receipt"), d.get("control")
    if not sub or not ctl:
        return 2, "no receipts: %s" % d.get("why")
    f = []
    if sub.get("toolKinds") != [d["requested"]]:
        f.append("tool reported %s, want [%s] (the tool must not see the later change)" % (sub.get("toolKinds"), d["requested"]))
    rb = sub.get("readBackKinds") or [None]
    if rb[0] is None or rb[0] == d["requested"]:
        f.append("read-back kind %s: the substitution is not visible" % rb)
    if not sub.get("mismatch"):
        f.append("substituted receipt mismatch=False")
    if not any(d["requested"] in p and str(rb[0]) in p for p in d.get("problems") or []):
        f.append("receipt_problems %s do not name requested vs actual" % d.get("problems"))
    if ctl.get("mismatch") or ctl.get("missingOnReadBack") or ctl.get("toolKinds") != [d["requested"]] \
            or ctl.get("readBackKinds") != [d["requested"]]:
        f.append("control receipt not clean: %s" % ctl)
    return (1 if f else 0), "; ".join(f) or "asked %s, tool said %s, map reads %s; control clean" % (
        d["requested"], sub.get("toolKinds"), rb)


def v_A2(d):
    if d.get("why"):
        return 2, d["why"]
    first, second = d.get("first") or [], d.get("second") or []
    f = []
    if "Eclipse" in first or "Eclipse" in second:
        f.append("Eclipse reported although the bounded expectation admitted it (first %s, second %s)" % (first, second))
    if "Aurora" not in second:
        f.append("Aurora not reported once the bound (1) was used: %s" % second)
    return (1 if f else 0), "; ".join(f) or "Eclipse admitted (max_count=1), Aurora reported: %s" % second


def v_A3(d):
    pid, hits = d.get("id"), d.get("hits")
    if not pid or hits is None:
        return 2, "no joiner staged: %s" % d.get("why")
    f = []
    if pid not in _ids(hits, "player_joiner"):
        f.append("player_joiner did not name %s" % pid)
    for det in ("pawn_arrived", "pawn_state_changed"):
        if pid in _ids(hits, det):
            f.append("%s also claims %s" % (det, pid))
    return (1 if f else 0), "; ".join(f) or "player_joiner names %s; no double report" % pid


def v_A4(d):
    w, j, hits, rep = d.get("warg"), d.get("joiner"), d.get("hits"), d.get("rows")
    if not w or not j or hits is None or rep is None:
        return 2, "scene not staged: %s" % d.get("why")
    f = []
    named = set()
    for h in hits:
        named.update(h.get("ids") or [])
    for pid in (w, j):
        if pid not in named:
            f.append("no detector named %s" % pid)
    rows = dict((r["id"], r) for r in rep)
    rw, rj = rows.get(w), rows.get(j)
    if not rw or not rj:
        return 1, "scene_report rows missing (warg %s, joiner %s)" % (bool(rw), bool(rj))
    if rw.get("relation") != "no-faction" or not str(rw.get("aggression") or "").startswith("mental:Manhunter"):
        f.append("warg hostility not decomposed: relation %s aggression %s" % (rw.get("relation"), rw.get("aggression")))
    if rj.get("relation") != "player":
        f.append("joiner relation %s, want player" % rj.get("relation"))
    for r in (rw, rj):
        if r.get("involvement") not in ("unknown", "confirmedIndirectAction"):
            f.append("%s involvement %s" % (r["id"], r.get("involvement")))
        if _over_claims(r.get("statement")):
            f.append("%s statement over-claims %s" % (r["id"], _over_claims(r.get("statement"))))
    text = d.get("text") or ""
    lines = dict((pid, [ln for ln in text.splitlines() if ln.startswith(pid + " ")]) for pid in (w, j))
    for pid, r, need in ((w, rw, ("no-faction", "mental:Manhunter")), (j, rj, ("player",))):
        ln = (lines[pid] or [""])[0]
        if not ln:
            f.append("rendered text has no row for %s" % pid)
        elif not all(n in ln for n in need) or str(r.get("involvement")) not in ln:
            f.append("rendered row for %s lacks %s / involvement: %s" % (pid, need, ln.strip()[:120]))
        elif _over_claims(ln):
            f.append("rendered row for %s over-claims %s" % (pid, _over_claims(ln)))
    return (1 if f else 0), "; ".join(f) or "named %s (manhunter, no-faction) and %s (player joiner)" % (w, j)


def v_A5(d):
    pid, hits = d.get("id"), d.get("hits")
    if not pid or hits is None:
        return 2, "no stranger staged: %s" % d.get("why")
    f = []
    sc = [h for h in hits if h.get("detector") == "pawn_state_changed" and pid in (h.get("ids") or [])]
    if not sc:
        f.append("pawn_state_changed did not report %s" % pid)
    elif sc[0].get("isPlayerAfter") is not True or sc[0].get("isPlayerBefore") is not False:
        f.append("state change %s, want isPlayer False -> True" % sc[0])
    for det in ("player_joiner", "pawn_arrived"):
        if pid in _ids(hits, det):
            f.append("%s reports the recruit %s as an arrival" % (det, pid))
    return (1 if f else 0), "; ".join(f) or "%s recruited: pawn_state_changed only" % pid


def v_A6(d):
    pid, hits = d.get("id"), d.get("hits")
    if not pid or hits is None:
        return 2, "no round trip: %s" % d.get("why")
    if not d.get("back_ok"):
        return 2, "caravan did not come back: %s" % d.get("back")
    f = []
    if pid not in _ids(hits, "player_joiner"):
        f.append("player_joiner did not report the returning colonist %s" % pid)
    mx = d.get("baseline_max")
    if _num(pid) is None or mx is None or not _num(pid) < mx:
        f.append("not an old id: %s vs baseline max %s (the case is vacuous)" % (pid, mx))
    return (1 if f else 0), "; ".join(f) or "old id %s (< %s) reported on return" % (pid, mx)


def v_A7(d):
    amb, one, ids = d.get("ambiguous"), d.get("single"), d.get("ids") or []
    if amb is None or len(ids) < 2:
        return 2, "two muffalo not staged: %s" % d.get("why")
    f = []
    listed = [a.get("id") for a in amb.get("ambiguous") or []]
    if amb.get("resolved") is not False or amb.get("what"):
        f.append("name selector resolved=%s what=%s (picked one?)" % (amb.get("resolved"), amb.get("what")))
    if not set(ids) <= set(listed):
        f.append("ambiguous list %s lacks %s" % (listed, ids))
    if not (one or {}).get("success") or (one or {}).get("resolved") is not True \
            or ((one or {}).get("what") or {}).get("id") != ids[0]:
        f.append("id selector did not resolve: %s" % str(one)[:200])
    return (1 if f else 0), "; ".join(f) or "%d candidates listed, none picked; id resolves" % len(listed)


def v_A8(d):
    row = d.get("row")
    if not row:
        return 2, "no worker-false incident found among %s: %s" % (FAIL_CANDIDATES, d.get("why"))
    f = []
    if str(row.get("returned")).lower() != "false":
        f.append("returned %s" % row.get("returned"))
    if str(row.get("outerBodyRan")).lower() != "true":
        f.append("outerBodyRan %s" % row.get("outerBodyRan"))
    if row.get("called") is not True:
        f.append("called %s" % row.get("called"))
    st = (row.get("statement") or "").lower()
    if "fired" in st or _over_claims(st):
        f.append("statement claims more than a call: %s" % row.get("statement"))
    if (d.get("tool") or {}).get("fired") is not False:
        f.append("tool fired=%s" % (d.get("tool") or {}).get("fired"))
    return (1 if f else 0), "; ".join(f) or "%s called, returned false: %s" % (row.get("def"), row.get("statement"))


def _raid_chain_ok(chain):
    k = _chain_kinds(chain)
    return bool(k) and k[0] == "bridge:jawa/fire_incident" and "incident:RaidEnemy" in k   # bridge-ROOTED


def _same_call(pawn_chain, row_chain):
    """The pawn was generated inside THIS journal row's context: its chain is the row's chain, ids included, or
    nested under it (a different RaidEnemy#n is another call)."""
    pc, rc = (pawn_chain or "").strip(), (row_chain or "").strip()
    return bool(rc) and (pc == rc or pc.startswith(rc + " > "))


def v_A9(d):
    row = d.get("row")
    if not row and (d.get("tool") or {}).get("fired") is True:
        return 1, "the raid fired but the installed recorder journaled no RaidEnemy row"
    if not row:
        return 2, "no RaidEnemy row: %s" % d.get("why")
    if (d.get("tool") or {}).get("blockedByDialog"):
        return 2, "a dialog swallowed the raid (blockedByDialog): not this recorder's case"
    f = []
    if not _raid_chain_ok(row.get("chain")):
        f.append("journal chain %s" % row.get("chain"))
    if str(row.get("returned")).lower() != "true":
        f.append("returned %s" % row.get("returned"))
    if not (row.get("pawnsGeneratedDuring") or 0) > 0:
        f.append("pawnsGeneratedDuring %s" % row.get("pawnsGeneratedDuring"))
    origins = d.get("origins") or []
    bad = [o["id"] for o in origins if not _same_call((o.get("generation") or {}).get("chain"), row.get("chain"))]
    missing = sorted(set(d.get("new") or []) - set(o["id"] for o in origins))
    if missing:
        f.append("no pawn_origin row for raid pawns %s" % missing[:5])
    if not origins:
        f.append("no raid pawn on the map to read")
    elif bad:
        f.append("raid pawns without the chain: %s" % bad[:5])
    return (1 if f else 0), "; ".join(f) or "chain %s, %d pawn(s) carry it" % (row.get("chain"), len(origins))


def v_A10(d):
    row = d.get("row")
    if not row:
        return 2, "no deferred (drop-pod) raid in %s tries: %s" % (d.get("tries"), d.get("why"))
    f = []
    origins = d.get("origins") or []
    missing = sorted(set(d.get("new") or []) - set(o["id"] for o in origins))
    if missing:
        f.append("no pawn_origin row for landed pawns %s" % missing[:5])
    if not _raid_chain_ok(row.get("chain")):
        f.append("journal chain %s" % row.get("chain"))
    if not origins:
        return 1, "pods never delivered a pawn after %s ticks (row %s)" % (d.get("waited"), row.get("aseq"))
    for o in origins:
        g, s = o.get("generation") or {}, o.get("spawn") or {}
        if not _same_call(g.get("chain"), row.get("chain")):
            f.append("%s generation chain %s, not this call's %s" % (o["id"], g.get("chain"), row.get("chain")))
        if not (s.get("tick") or 0) > (row.get("tick") or 0):
            f.append("%s spawned at %s, not after the call at %s" % (o["id"], s.get("tick"), row.get("tick")))
        if o.get("ourInvolvement") != "confirmedIndirectAction":
            f.append("%s involvement %s" % (o["id"], o.get("ourInvolvement")))
    return (1 if f else 0), "; ".join(f[:5]) or "%d pawn(s) landed after tick %s and read %s" % (
        len(origins), row.get("tick"), (origins[0].get("generation") or {}).get("chain"))


def v_A11(d):
    st = d.get("status") or {}
    if not st.get("success"):
        return 2, "no awareness status: %s" % str(st)[:200]
    if not (st.get("options") or {}).get("install.generation-early"):
        return 2, "precondition: awareness_settings.json lacks \"install.generation-early\": true at launch"
    f = []
    if st.get("startedBy") != "bridge-registration":
        f.append("startedBy %s" % st.get("startedBy"))
    if not str(st.get("generationHook") or "").startswith("installed early"):
        f.append("generationHook %s" % st.get("generationHook"))
    animals = d.get("animals") or []
    if not animals:
        return 2, "no factionless animal on the map to read (quiet prep removed them?)"
    mg = [a["id"] for a in animals if "mapgen" in [k.split(":")[0] for k in _chain_kinds((a.get("generation") or {}).get("chain"))]]
    if not mg:
        f.append("none of %d animals reads a mapgen chain (e.g. %s)" % (len(animals), (animals[0].get("generation") or {}).get("chain")))
    return (1 if f else 0), "; ".join(f) or "%d/%d animals read mapgen (%s)" % (
        len(mg), len(animals), [(a.get("generation") or {}).get("chain") for a in animals if a["id"] == mg[0]][0])


def v_A12(d):
    o = d.get("origin")
    if not d.get("back_ok"):
        return 2, "caravan did not come back: %s" % d.get("back")
    if not o:
        return 1, "no pawn_origin row for %s" % d.get("id")
    c = (o.get("spawn") or {}).get("classification")
    if c not in ("observedRespawn", "mapTransfer"):
        return 1, "%s spawn classification %s after the round trip" % (o.get("id"), c)
    return 0, "%s reads %s: %s" % (o.get("id"), c, o.get("statement"))


def v_A13(d):
    b, a = d.get("before") or {}, d.get("after") or {}
    if not b.get("success") or not a.get("success"):
        return 2, "status unreadable: %s" % d.get("why")
    f = []
    over_b = (b.get("evictions") or {}).get("incidents") or 0
    over_a = (a.get("evictions") or {}).get("incidents") or 0
    ret_b = (b.get("retained") or {}).get("incidents") or 0
    ret_a = (a.get("retained") or {}).get("incidents")
    want = max(0, ret_b + d["calls"] - RING)
    if ret_a != RING:
        f.append("retained %s after %d calls, want %d" % (ret_a, d["calls"], RING))
    if over_a - over_b != want:
        f.append("overwritten rose %d, want exactly %d (paused: only our calls)" % (over_a - over_b, want))
    j = d.get("journal") or {}
    if j.get("overwritten") != over_a:
        f.append("journal overwritten %s != status %s" % (j.get("overwritten"), over_a))
    if not (j.get("oldestRetainedSeq") or -1) > (d.get("oldest_before") or -1):
        f.append("oldest retained seq %s did not advance past %s" % (j.get("oldestRetainedSeq"), d.get("oldest_before")))
    return (1 if f else 0), "; ".join(f) or "retained %d, overwritten %d -> %d (+%d == %d)" % (
        ret_a, over_b, over_a, over_a - over_b, want)


VERDICTS = dict(("A%d" % i, globals()["v_A%d" % i]) for i in range(1, 14))


def verdict(clause, d):
    try:
        return VERDICTS[clause](d)
    except Exception as e:                                      # noqa: BLE001 - a malformed read is not a pass
        return 2, "verdict could not read the data: %s: %s" % (type(e).__name__, e)


# ------------------------------------------------------------------------------------------------ live gathering
def _setup_path():
    sys.path.insert(0, HERE)
    import common  # noqa: F401  (puts modcheck, Utils on sys.path)


class Live(object):
    def __init__(self, s):
        from common import call
        self.s, self._call, self.spawned = s, call, []

    def call(self, tool, **p):
        return self._call(self.s, tool, **p)

    def anchor(self):
        import helpers as H
        ax, az, _ = H.safe_anchor(self.s)
        return ax, az

    def spawn(self, kind, faction, x, z, count=1):
        r = self.call("jawa/spawn_pawn", kindDef=kind, x=x, z=z, faction=faction, count=count)
        ids = [p.get("id") for p in r.get("pawns") or [] if p.get("id")]
        self.spawned += ids
        return r, ids

    def rows(self):
        import helpers as H
        return H.read_pawns(self.s, health=False)

    def snap(self):
        import snapshot
        return snapshot.take_snapshot(self.s, tier="full", companion=True)

    def baseline(self):
        import snapshot
        return snapshot.Baseline(self.snap())

    def hits(self, base, exps=None, anchor=None):
        import detectors
        out = []
        for h in detectors.sweep(self.snap(), base, exps, anchor):
            ev = h.evidence or {}
            ids = list(ev.get("ids") or ([ev["id"]] if ev.get("id") else []))
            ids += [q.get("id") for q in ev.get("pawns") or [] if isinstance(q, dict) and q.get("id") not in ids]
            out.append({"detector": h.detector, "summary": h.summary, "ids": ids,
                        "isPlayerBefore": ev.get("isPlayerBefore"), "isPlayerAfter": ev.get("isPlayerAfter"),
                        "def": ev.get("def")})
        return out

    def status(self):
        return self.call("jawa/awareness")

    def origin(self, ids):
        r = self.call("jawa/pawn_origin", ids=",".join(ids))
        return dict((o["id"], o) for o in r.get("pawns") or [])

    def journal_since(self, seq):
        return self.call("jawa/incident_journal", sinceSeq=seq, limit=RING).get("rows") or []

    def advance(self, n):
        import helpers as H
        H.fast_advance(self.s, n, margin=0)

    def cleanup(self):
        import helpers as H
        if self.spawned:
            try:
                H.remove_visitors(self.s, self.spawned)
            except Exception:                                   # noqa: BLE001 - housekeeping, never a verdict
                pass


def g_A1(L):
    ax, az = L.anchor()
    want = "Tribal_Warrior"
    r, ids = L.spawn(want, "none", ax, az)
    rc, cids = L.spawn(want, "none", ax + 3, az)
    if not ids or not cids:
        return {"why": "spawn failed: %s" % r.get("message")}
    L.call("jawa/set_pawn_faction", pawn=ids[0], faction="player")
    import contract
    rows = L.rows()
    sub = contract.spawn_receipt("A1", "jawa/spawn_pawn", want, r, rows)
    ctl = contract.spawn_receipt("A1-control", "jawa/spawn_pawn", want, rc, rows)
    return {"requested": want, "receipt": sub, "control": ctl, "problems": contract.receipt_problems([sub])}


def g_A2(L):
    import detectors
    base = L.baseline()
    if base.snap["sources"].get("weather_get", {}).get("complete") is False:
        return {"why": "weather_get unreadable: conditions cannot be judged"}
    if {"Eclipse", "Aurora"} & base.conditions:
        return {"why": "Eclipse/Aurora already active at baseline: %s" % sorted(base.conditions)}
    exps = detectors.Expectations()
    exps.expect("condition", lambda c: True, max_count=1)
    try:
        L.call("jawa/game_condition", action="start", condition="Eclipse", durationTicks=2500)
        first = [h["def"] for h in L.hits(base, exps) if h["detector"] == "condition_unexpected"]
        L.call("jawa/game_condition", action="start", condition="Aurora", durationTicks=2500)
        second = [h["def"] for h in L.hits(base, exps) if h["detector"] == "condition_unexpected"]
    finally:
        for c in ("Eclipse", "Aurora"):
            L.call("jawa/game_condition", action="end", condition=c)
    return {"first": first, "second": second}


def g_A3(L):
    ax, az = L.anchor()
    base = L.baseline()
    r, ids = L.spawn("Colonist", "player", ax, az)
    if not ids:
        return {"why": r.get("message")}
    return {"id": ids[0], "hits": L.hits(base, anchor=(ax, az))}


def _statement(org):
    return org.get("statement") if isinstance(org, dict) else str(org)


def g_A4(L):
    import scene_report
    ax, az = L.anchor()
    base = L.baseline()
    rw, w = L.spawn("Warg", "none", ax + 5, az)
    rj, j = L.spawn("Colonist", "player", ax - 5, az)
    if not w or not j:
        return {"why": "spawn failed: %s / %s" % (rw.get("message"), rj.get("message"))}
    m = L.call("jawa/pawn_mental", pawn=w[0], action="start", state="Manhunter")
    if not m.get("success"):
        return {"why": "Manhunter did not start: %s" % m.get("message")}
    hits = L.hits(base, anchor=(ax, az))
    rep = scene_report.collect(L.s, anchor=(ax, az))
    rows = [{"id": p["id"], "relation": p["threat"]["factionRelationToPlayer"],
             "aggression": p["threat"]["aggressionReason"], "involvement": p["ourInvolvement"],
             "statement": _statement(p["evidence"]["origin"])} for p in rep["pawns"]]
    return {"warg": w[0], "joiner": j[0], "hits": hits, "rows": rows, "text": scene_report.render_text(rep)}


def g_A5(L):
    ax, az = L.anchor()
    r, ids = L.spawn("Tribal_Warrior", "none", ax, az)
    if not ids:
        return {"why": r.get("message")}
    base = L.baseline()
    f = L.call("jawa/set_pawn_faction", pawn=ids[0], faction="player")
    if not f.get("success"):
        return {"why": "set_pawn_faction: %s" % f.get("message")}
    return {"id": ids[0], "hits": L.hits(base, anchor=(ax, az))}


def _round_trip(L, between=None):
    ax, az = L.anchor()
    r, ids = L.spawn("Colonist", "player", ax, az)
    if not ids:
        return None, {"why": r.get("message")}
    out = L.call("jawa/caravan_create", pawns=ids[0])
    if not out.get("success"):
        return ids[0], {"why": "caravan_create: %s" % out.get("message")}
    extra = between() if between else None
    back = L.call("jawa/static_call", type=PROBE, method="CaravanBack", args=ids[0])
    text = json.dumps(back)
    return ids[0], {"back": text[:300], "back_ok": "AWAREPROOF back ok=True" in text, "extra": extra}


def g_A6(L):
    state = {}

    def between():
        ax, az = L.anchor()
        L.spawn("Tribal_Warrior", "none", ax + 4, az)        # a NEWER id than the travelling colonist
        state["base"] = L.baseline()
    pid, d = _round_trip(L, between)
    if not pid or "base" not in state:
        return d
    base = state["base"]
    d.update({"id": pid, "hits": L.hits(base), "baseline_max": max([_num(i) or 0 for i in base.pawn_ids] or [0])})
    return d


def g_A7(L):
    ax, az = L.anchor()
    r, ids = L.spawn("Muffalo", "none", ax, az, count=2)
    if len(ids) < 2:
        return {"why": r.get("message"), "ids": ids}
    label = (r.get("pawns") or [{}])[0].get("name") or "Muffalo"
    return {"ids": ids, "ambiguous": L.call("jawa/thing_explain", name=label),
            "single": L.call("jawa/thing_explain", id=ids[0])}


def _seq(L):
    return L.status().get("seq") or -1


def g_A8(L):
    tried = []
    for cand in FAIL_CANDIDATES:
        seq = _seq(L)
        t = L.call("jawa/fire_incident", incidentDef=cand)
        tried.append("%s fired=%s" % (cand, t.get("fired")))
        if t.get("fired") is False:
            rows = [r for r in L.journal_since(seq) if r.get("def") == cand]
            if rows:
                return {"row": rows[-1], "tool": t}
            return {"why": "%s did not fire but has no journal row" % cand, "row": None}
    return {"why": "; ".join(tried)}


def _raid(L, faction=None):
    seq = _seq(L)
    p = {"incidentDef": "RaidEnemy", "points": 100.0}
    if faction:
        p["faction"] = faction
    t = L.call("jawa/fire_incident", **p)
    rows = [r for r in L.journal_since(seq) if r.get("def") == "RaidEnemy"]
    return t, (rows[-1] if rows else None)


def _hostiles(L, before):
    return [p["id"] for p in L.rows() if p.get("hostile") and not p.get("dead") and p["id"] not in before]


def g_A9(L):
    before = set(p["id"] for p in L.rows())
    try:
        t, row = _raid(L)
        if row is None:
            return {"why": "no journal row: %s" % t.get("message"), "tool": t}
        if not (row.get("pawnsSpawnedDuring") or 0):
            L.advance(600)                                     # drop pods: let them land before reading
        new = _hostiles(L, before)
        o = L.origin(new) if new else {}
        return {"row": row, "tool": t, "origins": list(o.values()), "new": new}
    finally:
        import helpers as H
        H.kill_hostiles(L.s)


def g_A10(L):
    import helpers as H
    tries = 0
    try:
        for tries in range(1, 4):
            before = set(p["id"] for p in L.rows())
            t, row = _raid(L, "Mechanoid")
            if row and (row.get("pawnsGeneratedDuring") or 0) > 0 and not (row.get("pawnsSpawnedDuring") or 0):
                L.advance(600)
                new = _hostiles(L, before)
                o = L.origin(new) if new else {}
                return {"row": row, "origins": list(o.values()), "new": new, "waited": 600, "tries": tries}
            H.kill_hostiles(L.s)
        return {"tries": tries, "why": "every raid delivered during the call (walk-in)"}
    finally:
        H.kill_hostiles(L.s)


def g_A11(L):
    st = L.status()
    rows = [p for p in L.rows() if p.get("faction") is None and p.get("intelligence") == "Animal"
            and not p.get("dead") and p.get("spawned", True)]
    o = L.origin([p["id"] for p in rows]) if rows else {}
    return {"status": st, "animals": list(o.values())}


def g_A12(L):
    pid, d = _round_trip(L)
    if pid and d.get("back_ok"):
        d["origin"] = L.origin([pid]).get(pid)
    d["id"] = pid
    return d


def g_A13(L):
    cand = None
    for c in FAIL_CANDIDATES:                                   # a call that changes nothing on the map
        if L.call("jawa/fire_incident", incidentDef=c).get("fired") is False:
            cand = c
            break
    if cand is None:
        return {"why": "no worker-false incident to repeat", "before": {}, "after": {}}
    before = L.status()
    j0 = L.call("jawa/incident_journal", limit=1)
    n = RING + 20
    for _ in range(n):
        L.call("jawa/fire_incident", incidentDef=cand)
    return {"before": before, "after": L.status(), "calls": n, "oldest_before": j0.get("oldestRetainedSeq"),
            "journal": L.call("jawa/incident_journal", limit=1), "incident": cand}


def main(argv):
    if len(argv) != 2 or argv[1] not in CLAUSES:
        print(__doc__)
        return 2
    clause = argv[1]
    try:
        _setup_path()
        from rimdrive import Session
    except Exception as e:                                      # noqa: BLE001
        print("%s UNMEASURED: harness import failed: %s" % (clause, e))
        return 2
    try:
        with Session(lock=None, focus=False, strict=False, quiet=True) as s:
            L = Live(s)
            mi = L.call("jawa/map_info")
            if not mi.get("success", True) or mi.get("sizeX") is None:
                print("%s UNMEASURED: no current map: %s" % (clause, str(mi)[:200]))
                return 2
            st = L.status()
            if not st.get("installed"):
                print("%s UNMEASURED: awareness recorder not installed: %s %s" % (
                    clause, st.get("installStatus"), st.get("installDetail") or st.get("message")))
                return 2
            if clause != "A11":
                L.call("jawa/awareness", action="arm", minutes=30)      # GeneratePawn hook (lazy by default)
            import helpers as H
            H.pause(s)
            try:
                d = globals()["g_" + clause](L)
            finally:
                L.cleanup()
    except Exception as e:                                      # noqa: BLE001 - any transport failure: the proof could not see
        print("%s UNMEASURED: %s: %s" % (clause, type(e).__name__, str(e)[:300]))
        return 2
    code, why = verdict(clause, d)
    print("%s %s: %s" % (clause, {0: "PASS", 1: "FAIL", 2: "UNMEASURED"}[code], why))
    return code


if __name__ == "__main__":
    sys.exit(main(sys.argv))

